Object.assign(window.TEM8_DICTIONARY, {"being":{"media":{"uk":"media/uk/being__gb_1.mp3","us":"media/us/being__us_1.mp3"},"oxford":{"phon":"ˈbiːɪŋ","pos":"noun","senses":[{"en":"existence","cn":"存在；生存","g":"[uncountable]","ex":{"en":"The Irish Free State came into being in 1922.","cn":"爱尔兰自由邦成立于 1922 年。"}},{"en":"a living creature","cn":"生物","g":"[countable]","ex":{"en":"human beings","cn":"人"}},{"en":"your mind and all of your feelings","cn":"思想感情；身心","g":"[uncountable]","lab":"formal","ex":{"en":"I hated him with my whole being.","cn":"我从心底憎恨他。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Being is the present participle of be ."},{"pos":"V-LINK 连系动词","cn":"（用于说明原因的非限定性从句中）因为，由于","en":"Being is used in non-finite clauses where you are giving the reason for something.","ex":{"en":"It being a Sunday, the old men had the day off","cn":"因为是星期天，所以老人都休息。"}},{"pos":"N-COUNT 可数名词","cn":"生物","en":"You can refer to any real or imaginary creature as a being .","ex":{"en":"People expect a horse to perform like a car, with no thought for its feelings as a living being.","cn":"人们希望马能像汽车一样，完全没有考虑到马作为一种有生命的动物会有什么样的感受。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"存在","en":"Being is existence. Something that is in being or comes into being exists.","ex":{"en":"Abraham Maslow described psychology as 'the science of being.'","cn":"亚伯拉罕·马斯洛形容心理学是“存在的科学”。"}},{"pos":"PHR-CONJ-SUBORD","cn":"（用于解释所说内容的原因）因为，由于","en":"You can use being as to introduce a reason for what you are saying.","ex":{"en":"I used to go everywhere with my mother being as I was the youngest.","cn":"我以前到哪儿都跟着我妈，因为我是老小。"}},{"pos":"See also:","cn":"","en":"other things being equal→see: ; for the time being→see: ;"}]},"examples":[{"en":"The Irish Free State came into being in 1922.","cn":"爱尔兰自由邦成立于 1922 年。"},{"en":"A new era was brought into being by the war.","cn":"那场战争带来了一个新的时代。"}]},"bedding":{"oxford":{"phon":"ˈbedɪŋ","pos":"noun","senses":[{"en":"the sheets and covers that you put on a bed, and often also the mattress and the pillows","cn":"寝具；铺盖"},{"en":"straw, etc. for animals to sleep on","cn":"（给动物歇息的）垫草"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"卧具；寝具；铺盖","en":"Bedding is sheets, blankets, and covers that are used on beds."}]},"media":{"uk":"media/uk/bedding__gb_1.mp3","us":"media/us/bedding__us_1.mp3"},"base":"bed"},"bean":{"oxford":{"phon":"biːn","pos":"noun","senses":[{"en":"a seed, or pod containing seeds, of a climbing plant, eaten as a vegetable. There are several types of bean and the plants that they grow on are also called beans.","cn":"豆；菜豆；豆荚；豆科植物","ex":{"en":"green beans","cn":"青豆"}},{"en":"a seed from a coffee plant, or some other plants","cn":"（咖啡树或其他某些植物的）籽实","ex":{"en":"cocoa/coffee beans","cn":"可可豆；咖啡豆"}},{"en":"to hit somebody on the head","cn":"击中（某人）头部","lab":"North American English, informal，，","ex":{"en":"I got beaned by a rock someone threw.","cn":"我的头被扔出的石头砸中了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"豆；豆子；豆荚","en":"Beans such as green beans, French beans, or broad beans are the seeds of a climbing plant or the long thin cases which contain those seeds."},{"pos":"N-COUNT 可数名词","cn":"干豆","en":"Beans such as soya beans and kidney beans are the dried seeds of a bean plant."},{"pos":"N-COUNT 可数名词","cn":"（咖啡）豆；（可可）豆；（巧克力）豆","en":"Beans such as coffee beans or cocoa beans are the seeds of plants that are used to produce coffee, cocoa, and chocolate."},{"pos":"N-COUNT 可数名词","cn":"烘豆","en":"Beans are baked beans .","ex":{"en":"...sausage and beans.","cn":"香肠和烘豆"}},{"pos":"N-SING 单数名词","cn":"（一文）钱","en":"If someone has not got a bean, they have no money at all.","ex":{"en":"It's quite incredible to think that he now hasn't got a bean","cn":"很难相信他现在身无分文。"}},{"pos":"PHRASE 短语","cn":"充满活力的；兴高采烈的；生机勃勃的","en":"If someone is full of beans, they are very lively and have a lot of energy and enthusiasm.","ex":{"en":"Jem was full of beans after a long sleep.","cn":"杰姆好好睡了一觉之后又变得精力充沛了。"}},{"pos":"PHRASE 短语","cn":"泄露秘密","en":"If you spill the beans, you tell someone something that people have been trying to keep secret."}]},"media":{"uk":"media/uk/bean__gb_1.mp3","us":"media/us/bean__us_1.mp3"},"examples":[{"en":"I got beaned by a rock someone threw.","cn":"我的头被扔出的石头砸中了。"},{"en":"beans (= baked beans ) on toast","cn":"面包片加烘豆"}]},"betray":{"media":{"uk":"media/uk/betray__gb_1.mp3","us":"media/us/betray__us_1.mp3"},"oxford":{"phon":"bɪˈtreɪ","pos":"verb","senses":[{"en":"to give information about somebody/something to an enemy","cn":"出卖；泄露（机密）","ex":{"en":"He was offered money to betray his colleagues.","cn":"有人收买他出卖他的同事。"}},{"en":"to hurt somebody who trusts you, especially by lying to or about them or telling their secrets to other people","cn":"背叛；辜负；对…不忠","ex":{"en":"She felt betrayed when she found out the truth about him.","cn":"她发现他的真实情况时，感到受了欺骗。"}},{"en":"to ignore your principles or beliefs in order to achieve something or gain an advantage for yourself","cn":"背叛（原则或信仰）","ex":{"en":"He has been accused of betraying his former socialist ideals.","cn":"有人指责他背弃了他先前的社会主义理想。"}},{"en":"to tell somebody or make them aware of a piece of information, a feeling, etc., usually without meaning to","cn":"（无意中）泄露信息，流露情感","ex":{"en":"His voice betrayed the worry he was trying to hide.","cn":"他的声音掩盖不了内心的担忧。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"失信于；辜负","en":"If you betray someone who loves or trusts you, your actions hurt and disappoint them.","ex":{"en":"When I tell someone I will not betray his confidence I keep my word","cn":"如果我告诉某人我不会辜负他的信任，我就会恪守诺言。"}},{"pos":"VERB 动词","cn":"背叛；出卖","en":"If someone betrays their country or their friends, they give information to an enemy, putting their country's security or their friends' safety at risk.","ex":{"en":"They offered me money if I would betray my associates","cn":"他们提出来只要我供出同伙就给我钱。"}},{"pos":"VERB 动词","cn":"违背，背弃（理想或原则）","en":"If you betray an ideal or your principles, you say or do something which goes against those beliefs.","ex":{"en":"We betray the ideals of our country when we support capital punishment.","cn":"如果我们支持死刑，那就背弃了我们立国的理念。"}},{"pos":"VERB 动词","cn":"流露出；暴露出","en":"If you betray a feeling or quality, you show it without intending to.","ex":{"en":"She studied his face, but it betrayed nothing","cn":"她仔细端详了一番他的脸，但什么也没有看出来。"}}]},"examples":[{"en":"He has been accused of betraying his former socialist ideals.","cn":"有人指责他背弃了他先前的社会主义理想。"},{"en":"For years they had been betraying state secrets to Russia.","cn":"他们多年来一直向俄罗斯泄露国家机密。"}]},"benevolent":{"media":{"uk":"media/uk/benevolent__gb_1.mp3","us":"media/us/benevolent__us_1.mp3"},"oxford":{"phon":"bəˈnevələnt","pos":"adjective","senses":[{"en":"kind, helpful and generous","cn":"慈善的；行善的；乐善好施的","lab":"formal","ex":{"en":"a benevolent smile/attitude","cn":"和蔼的笑容／态度"}},{"en":"used in the names of some organizations that give help and money to people in need","cn":"（用于慈善机构名称）","ex":{"en":"the RAF Benevolent Fund","cn":"英国皇家空军慈善基金（组织）"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（当权者）仁慈的，慈爱的，乐善好施的","en":"If you describe a person in authority as benevolent, you mean that they are kind and fair.","ex":{"en":"The company has proved to be a most benevolent employer","cn":"事实证明，这家公司是非常好的雇主。"}},{"pos":"ADJ 形容词","cn":"（用于慈善机构名称）慈善的，救济的","en":"Benevolent is used in the names of some organizations that give money and help to people who need it.","ex":{"en":"...the Army Benevolent Fund.","cn":"陆军慈善基金"}}]},"examples":[{"en":"belief in the existence of a benevolent god","cn":"对于存在仁慈的神的笃信"},{"en":"the RAF Benevolent Fund","cn":"英国皇家空军慈善基金（组织）"}]},"beamed":{"media":{"uk":"media/uk/beamed__gb_1.mp3","us":"media/us/beamed__us_1.mp3"},"oxford":{"phon":"biːmd","pos":"adjective","senses":[{"en":"having beams of wood","cn":"有木梁的","ex":{"en":"a high beamed ceiling","cn":"木梁高高支撑着的天花板"}}]},"examples":[{"en":"a high beamed ceiling","cn":"木梁高高支撑着的天花板"}],"base":"beam"},"beyond":{"media":{"uk":"media/uk/beyond__gb_1.mp3","us":"media/us/beyond__us_1.mp3"},"oxford":{"phon":"bɪˈjɒnd","pos":"preposition","senses":[{"en":"on or to the further side of something","cn":"在（或向）…较远的一边","ex":{"en":"The road continues beyond the village up into the hills.","cn":"那条路经过村子后又往上延伸到群山中。"}},{"en":"more than something","cn":"超出；除…之外","ex":{"en":"Our success was far beyond what we thought possible.","cn":"我们的成功远远超出了我们的估计范围。"}},{"en":"later than a particular time","cn":"晚于；迟于","ex":{"en":"It won't go on beyond midnight.","cn":"这事不会延续到午夜以后。"}},{"en":"used to say that something is not possible","cn":"（表示不可能）","ex":{"en":"The bicycle was beyond repair (= is too badly damaged to repair).","cn":"自行车已损坏得无法修理。"}},{"en":"too far or too advanced for somebody/something","cn":"超出…之外；非…所能及","ex":{"en":"The handle was just beyond my reach.","cn":"我差一点儿才够得着把手。"}},{"en":"on the other side; further on","cn":"在另一边；在（或向）更远处；以远","ex":{"en":"Snowdon and the mountains beyond were covered in snow.","cn":"斯诺登山及其以远的山脉都被积雪覆盖着。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…的另一边；在…那一边","en":"If something is beyond a place or barrier, it is on the other side of it.","ex":{"en":"They heard footsteps in the main room, beyond a door","cn":"他们听见门外的大厅里有脚步声。"}},{"pos":"PREP 介词","cn":"超过，迟于（某个时间）；逾（期）","en":"If something happens beyond a particular time or date, it continues after that time or date has passed.","ex":{"en":"Few jockeys continue race-riding beyond the age of 40","cn":"很少有职业赛马骑师超过40岁仍继续参加赛马的。"}},{"pos":"PREP 介词","cn":"影响；涵盖；包括","en":"If something extends beyond a particular thing, it affects or includes other things.","ex":{"en":"His interests extended beyond the fine arts to international politics and philosophy.","cn":"他兴趣广泛，涵盖了从美术到国际政治乃至哲学的各个领域。"}},{"pos":"PREP 介词","cn":"除了…；除…之外","en":"You use beyond to introduce an exception to what you are saying.","ex":{"en":"He appears to have almost no personal staff, beyond a secretary who can't make coffee","cn":"除了一个不会冲咖啡的秘书之外，他好像几乎没有什么随身的工作人员。"}},{"pos":"PREP 介词","cn":"超出，超过（某个点或阶段）","en":"If something goes beyond a particular point or stage, it progresses or increases so that it passes that point or stage.","ex":{"en":"Their five-year relationship was strained beyond breaking point","cn":"他们五年的关系已经紧张到无法维系。"}},{"pos":"PREP 介词","cn":"无法（理解、相信等）","en":"If something is, for example, beyond understanding or beyond belief, it is so extreme in some way that it cannot be understood or believed.","ex":{"en":"What Jock had done was beyond my comprehension","cn":"我无法理解乔克的所作所为。"}},{"pos":"PREP 介词","cn":"非…能力所及；超出…的能力","en":"If you say that something is beyond someone, you mean that they cannot deal with it.","ex":{"en":"Although he could give her sympathy, any practical help would almost certainly be beyond him","cn":"虽然他可以对她表示同情，但是他几乎根本无法提供任何实际的帮助。"}},{"pos":"","cn":"","en":"beyond the pale→see: ; beyond someone's means→see: ; beyond your wildest dreams→see: ; beyond a joke→see: ;"}]},"examples":[{"en":"I know what I'll be doing for the next three weeks but I haven't thought beyond that.","cn":"我知道我未来三周要干什么，但再往后我还没有想过。"},{"en":"She's got nothing beyond her state pension.","cn":"除了政府发的养老金外，她就什么都没有领取。"}]},"bewildering":{"media":{"uk":"media/uk/bewildering__gb_1.mp3","us":"media/us/bewildering__us_1.mp3"},"oxford":{"phon":"bɪˈwɪldərɪŋ","pos":"adjective","senses":[{"en":"making you feel confused because there are too many things to choose from or because something is difficult to understand","cn":"令人困惑的；使人糊涂的","ex":{"en":"a bewildering array/range","cn":"令人眼花缭乱的摆设／种类"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人困惑的；令人不知所措的；让人晕头转向的","en":"A bewildering thing or situation is very confusing and difficult to understand or to make a decision about.","ex":{"en":"A glance along his bookshelves reveals a bewildering array of interests","cn":"看一眼他的书架就知道他兴趣繁杂。"}}]},"examples":[{"en":"There is a bewildering variety of software available.","cn":"各种可供挑选的软件使人目不暇接。"},{"en":"All the houses looked bewilderingly similar.","cn":"所有的房屋都一样，使人难以分辨。"}]},"bel":{"oxford":{"phon":"bel","pos":"noun","senses":[{"en":"a measurement of sound equal to 10 decibels","cn":"贝尔，贝（声音计量单位，等于 10 分贝）"}]},"media":{"uk":"media/uk/bel__gb_1.mp3","us":"media/us/bel__us_1.mp3"}},"between":{"media":{"uk":"media/uk/between__gb_1.mp3","us":"media/us/between__us_1.mp3"},"oxford":{"phon":"bɪˈtwiːn","pos":"preposition","senses":[{"en":"in or into the space separating two or more points, objects, people, etc.","cn":"（空间上）在…中间，介于…之间","lab":"figurative","ex":{"en":"Q comes between P and R in the English alphabet.","cn":"英语字母表中，Q 在 P 和 R 之间。"}},{"en":"in the period of time that separates two days, years, events, etc.","cn":"（时间上）在…之间，在…中间","ex":{"en":"It's cheaper between 6 p.m. and 8 a.m.","cn":"下午 6 点到早晨 8 点间价钱较便宜。"}},{"en":"at some point along a scale from one amount, weight, distance, etc. to another","cn":"（数量、重量、距离等）介于…之间","ex":{"en":"It weighed between nine and ten kilos.","cn":"重量在九到十公斤之间。"}},{"en":"separating one place from another","cn":"分隔着；在…之间","ex":{"en":"the border between Sweden and Norway","cn":"瑞典和挪威之间的边界"}},{"en":"from one place to another","cn":"从（一地）到（另一地）；往返于","ex":{"en":"We fly between Rome and Paris twice daily.","cn":"我们每天有两次航班往返于罗马和巴黎之间。"}},{"en":"used to show a connection or relationship","cn":"（表示联系或关系）","ex":{"en":"a difference/distinction/contrast between two things","cn":"两事物之间的差异／区别／对比"}},{"en":"shared by two or more people or things","cn":"合用；共享","ex":{"en":"We ate a pizza between us.","cn":"我们合吃了一张比萨饼。"}},{"en":"by putting together the efforts or actions of two or more people or groups","cn":"通过共同努力；一起","ex":{"en":"We ought to be able to manage it between us.","cn":"我们齐心协力应该能把这事办妥。"}},{"en":"used to show that several activities are involved","cn":"（同时进行几项活动时用）","ex":{"en":"Between working full-time and taking care of the kids, he didn't have much time for hobbies.","cn":"他一边全职工作一边又要照顾孩子，所以抽不出很多时间搞业余爱好。"}},{"en":"in the space or period of time separating two or more points, objects, etc. or two dates, events, etc.","cn":"（空间或时间上）在中间，当中","ex":{"en":"The house was near a park but there was a road in between.","cn":"房子在一处公园附近，但两者之间隔着一条马路。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…之间；处于…中间","en":"If something is between two things or is in between them, it has one of the things on one side of it and the other thing on the other side.","ex":{"en":"She left the table to stand between the two men","cn":"她离开桌子，站在了那两个男人之间。"}},{"pos":"PREP 介词","cn":"在（两地）之间（穿梭）","en":"If people or things travel between two places, they travel regularly from one place to the other and back again.","ex":{"en":"I spent a lot of time in the early Eighties travelling between London and Bradford.","cn":"八十年代初，我有很多时间穿梭于伦敦和布拉德福德之间。"}},{"pos":"PREP 介词","cn":"在（两个人、群体或事物）之间","en":"A relationship, discussion, or difference between two people, groups, or things is one that involves them both or relates to them both.","ex":{"en":"I think the relationship between patients and doctors has got a lot less personal","cn":"我认为医患关系变得越来越缺乏人情味。"}},{"pos":"PREP 介词","cn":"挡在…之间","en":"If something stands between you and what you want, it prevents you from having it.","ex":{"en":"His sense of duty often stood between him and the enjoyment of life.","cn":"他的责任感经常让他无法好好享受生活。"}},{"pos":"PREP 介词","cn":"（数量、年龄等）介于…之间","en":"If something is between two amounts or ages, it is greater or older than the first one and smaller or younger than the second one.","ex":{"en":"Increase the amount of time you spend exercising by walking between 15 and 20 minutes","cn":"步行15至20分钟，增加一下你的运动时间。"}},{"pos":"PREP 介词","cn":"（时间上）在…之间，介于…之间","en":"If something happens between or in between two times or events, it happens after the first time or event and before the second one.","ex":{"en":"The canal was built between 1793 and 1797","cn":"运河开凿于1793到1797年间。"}},{"pos":"PREP 介词","cn":"在…之间（作出选择）","en":"If you must choose between two or more things, you must choose just one of them.","ex":{"en":"Students will be able to choose between English, French and Russian as their first foreign language.","cn":"学生可以在英语、法语和俄语中间选择一门作为第一外语。"}},{"pos":"PREP 介词","cn":"总共；总计","en":"If people or places have a particular amount of something between them, this is the total amount that they have.","ex":{"en":"The three sites employ 12,500 people between them","cn":"这三处共雇用了12,500名员工。"}},{"pos":"PREP 介词","cn":"由…分担；由…分享","en":"When something is divided or shared between people, they each have a share of it.","ex":{"en":"His company was bought out by Hogg Robinson for £3.5m, divided between five partners","cn":"他的公司被霍格·鲁宾逊公司以350万英镑的价格收购，分给了五位合伙人。"}},{"pos":"PHRASE 短语","cn":"你我之间（的秘密）；只限于你我之间；我俩私下说说","en":"When you introduce a statement by saying 'between you and me' or 'between ourselves', you are indicating that you do not want anyone else to know what you are saying.","ex":{"en":"Between you and me, though, it's been awful for business","cn":"不过你我之间说说，这事儿办得真不怎么样。"}}]},"examples":[{"en":"Between working full-time and taking care of the kids, he didn't have much time for hobbies.","cn":"他一边全职工作一边又要照顾孩子，所以抽不出很多时间搞业余爱好。"},{"en":"The temperature remained between 25 ° C and 30 ° C all week.","cn":"整个星期气温都保持在 25 到 30 摄氏度之间。"}]},"bee":{"oxford":{"phon":"biː","pos":"noun","senses":[{"en":"a black and yellow flying insect that can sting (= touch your skin and make you feel a sharp pain).Bees live in large groups and make honey (= a sweet sticky substance that is good to eat).","cn":"蜜蜂","ex":{"en":"Bees were buzzing in the clover.","cn":"蜜蜂在三叶草丛中嗡嗡作响。"}},{"en":"a meeting in a group where people combine work, competition and pleasure","cn":"（集工作、竞赛、娱乐为一体的）聚会","lab":"North American English","ex":{"en":"a sewing bee","cn":"缝纫友谊赛"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蜜蜂","en":"A bee is an insect with a yellow-and-black striped body that makes a buzzing noise as it flies. Bees make honey, and can sting."},{"pos":"PHRASE 短语","cn":"痴迷于…；对…念念不忘","en":"If you have a bee in your bonnet about something, you are so enthusiastic or worried about it that you keep mentioning it or thinking about it.","ex":{"en":"He's got a bee in his bonnet about factory farming.","cn":"他满脑子都是工厂化养殖的事儿。"}},{"pos":"N-COUNT 可数名词","cn":"（进行缝纫等比赛或集体活动的）聚会","en":"A bee is a social event where people get together for a competition or to do something such as sew.","ex":{"en":"That year I won first prize in the spelling bee","cn":"那年，我在单词拼写比赛中得了第一名。"}}]},"media":{"uk":"media/uk/bee__gb_1.mp3","us":"media/us/bee__us_1.mp3","img":["media/ldoce/img/bee.jpg"]},"examples":[{"en":"Bees were buzzing in the clover.","cn":"蜜蜂在三叶草丛中嗡嗡作响。"},{"en":"She thinks she's the bee's knees (= she has a very high opinion of herself).","cn":"她自以为很了不起。"}]},"belief":{"media":{"uk":"media/uk/belief__gb_1.mp3","us":"media/us/belief__us_1.mp3"},"oxford":{"phon":"bɪˈliːf","pos":"noun","senses":[{"en":"a strong feeling that something/somebody exists or is true; confidence that something/somebody is good or right","cn":"相信；信心","g":"[uncountable]","ex":{"en":"I admire his passionate belief in what he is doing.","cn":"我佩服他对自己的工作所抱的坚定信心。"}},{"en":"an opinion about something; something that you think is true","cn":"看法；信念","g":"[singular, uncountable]","ex":{"en":"There is a general belief that things will soon get better.","cn":"大家普遍认为情况很快就会好转。"}},{"en":"something that you believe, especially as part of your religion","cn":"信仰；宗教信仰","g":"[countable, usually plural]","ex":{"en":"religious/political beliefs","cn":"宗教／政治信仰"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"信心；信念；信仰","en":"Belief is a feeling of certainty that something exists, is true, or is good.","ex":{"en":"One billion people throughout the world are Muslims, united by belief in one god.","cn":"全世界有10亿穆斯林，共同的一神信仰将他们团结在一起。"}},{"pos":"N-PLURAL 复数名词","cn":"（对宗教或政治的）信仰，观点，看法","en":"Your religious or political beliefs are your views on religious or political matters.","ex":{"en":"He refuses to compete on Sundays because of his religious beliefs.","cn":"出于宗教信仰，他拒绝在礼拜天进行比赛。"}},{"pos":"N-SING 单数名词","cn":"信念；坚定的看法","en":"If it is your belief that something is the case, it is your strong opinion that it is the case.","ex":{"en":"It is our belief that improvements in health care will lead to a stronger, more prosperous economy.","cn":"我们坚信，改善医疗保健会使经济更加繁荣昌盛。"}},{"pos":"PHRASE 短语","cn":"难以置信","en":"You use beyond belief to emphasize that something is true to a very great degree or that it happened to a very great degree.","ex":{"en":"We are devastated, shocked beyond belief","cn":"我们极为震惊，无法相信所发生的一切。"}},{"pos":"PHRASE 短语","cn":"和人们一般的认识相反；和一般看法相反","en":"You use contrary to popular belief to introduce a statement that is the opposite to what is thought to be true by most ordinary people.","ex":{"en":"Contrary to popular belief, there is no evidence that what you look like makes much difference to your life.","cn":"和人们一般的看法相反，没有证据表明面相对人生有多大影响。"}},{"pos":"PHRASE 短语","cn":"（通常错误地）认为","en":"If you do one thing in the belief that another thing is true or will happen, you do it because you think, usually wrongly, that it is true or will happen.","ex":{"en":"Civilians had broken into the building, apparently in the belief that it contained food.","cn":"平民百姓闯进了大楼，显然他们误以为里面有食物。"}}]},"examples":[{"en":"Contrary to popular belief (= in spite of what people may think), he was not responsible for the tragedy.","cn":"与大家的看法相反，他对这桩悲剧没有责任。"},{"en":"Dissatisfaction with the government has grown beyond belief.","cn":"对政府的不满已经达到令人难以置信的程度。"}]},"beat":{"media":{"uk":"media/uk/beat__gb_1.mp3","us":"media/us/beat__us_1.mp3"},"oxford":{"phon":"biːt","pos":"verb","senses":[{"en":"to defeat somebody in a game or competition","cn":"（在比赛或竞争中）赢，打败（某人）","g":"[transitive]","sc":"in game","ex":{"en":"He beat me at chess.","cn":"他下棋赢了我。"}},{"en":"to do or be better than something","cn":"比…更好；赛过；胜过","g":"[transitive]","lab":"rather informal","sc":"be better","ex":{"en":"Nothing beats home cooking.","cn":"什么也比不上家里的饭菜。"}},{"en":"to get control of something","cn":"控制","g":"[transitive]","lab":"informal","sc":"control","ex":{"en":"The government's main aim is to beat inflation.","cn":"政府的主要目标是抑制通货膨胀。"}},{"en":"to be too difficult for somebody","cn":"难倒","g":"[transitive]","lab":"informal","sc":"be too difficult","ex":{"en":"It is a problem that beats even the experts.","cn":"这个问题连专家都难以解答。"}},{"en":"to avoid something","cn":"避免；逃避","g":"[transitive]","lab":"informal","sc":"avoid","ex":{"en":"If we go early we should beat the traffic.","cn":"我们早点出发应该就可以避开交通拥挤。"}},{"en":"to hit a person hard and many times in order to hurt them","cn":"打；击打","g":"[transitive]","sc":"hit","ex":{"en":"At that time children were regularly beaten for quite minor offences (= as a punishment).","cn":"那时候孩子们常常因为很小的过错而挨打。"}},{"en":"to hit something hard several times","cn":"用力敲打","g":"[intransitive, transitive]","sc":"hit","ex":{"en":"Somebody was beating at the door.","cn":"有人在捶门。"}},{"en":"to make, or cause something to make, a regular sound or movement","cn":"（使）规律作响，做规律性运动","g":"[intransitive, transitive]","sc":"of heart/drums/wings","ex":{"en":"She's alive—her heart is still beating.","cn":"她没死，她的心还在跳动。"}},{"en":"to mix something with short quick movements with a fork, etc.","cn":"（用叉等）快速搅拌，打","g":"[transitive]","sc":"mix","ex":{"en":"Beat the eggs up to a frothy consistency.","cn":"把鸡蛋打成黏稠泡沫状。"}},{"en":"to change the shape of something, especially metal, by hitting it with a hammer, etc.","cn":"把（金属等）锤成；敲打（成…）","g":"[transitive, often passive]","sc":"shape metal","ex":{"en":"The gold is beaten out into thin strips.","cn":"金子被锤成了薄薄的长条。"}},{"en":"to make a path, etc. by walking somewhere or by pressing branches down and walking over them","cn":"踏出，踩出（道路）","g":"[transitive]","sc":"make path","ex":{"en":"a well-beaten track (= one that has been worn hard by much use)","cn":"经过很多人踏出来的路"}},{"en":"a single hit to something, such as a drum, or a movement of something, such as your heart; the sound that this makes","cn":"（鼓的）一击；（翅的）一振；（心脏等的）跳动；击鼓声；振翅声；跳动声","g":"[countable]","sc":"of drums/heart/wings","ex":{"en":"several loud beats on the drum","cn":"几下隆隆鼓声"},"pos":"noun"},{"en":"a series of regular hits to something, such as a drum; the sound that this makes","cn":"有规律的敲击（声）","g":"[singular]","sc":"of drums/heart/wings","ex":{"en":"the steady beat of the drums","cn":"有节奏的敲鼓声"},"pos":"noun"},{"en":"the main rhythm, or a unit of rhythm, in a piece of music, a poem, etc.","cn":"（音乐、诗歌等的）主节奏，节拍","g":"[countable]","sc":"rhythm","ex":{"en":"This type of music has a strong beat to it.","cn":"这种音乐节奏感很强。"},"pos":"noun"},{"en":"the area that a police officer walks around regularly and which they are responsible for","cn":"（警察的）巡区","g":"[countable, usually singular]","sc":"of police officer","ex":{"en":"More police officers out on the beat may help to cut crime.","cn":"增加巡逻的警察可能有助于减少罪行。"},"pos":"noun"},{"en":"very tired","cn":"筋疲力尽；累垮了","pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"打；猛击","en":"If you beat someone or something, you hit them very hard.","ex":{"en":"My wife tried to stop them and they beat her","cn":"我妻子想阻止他们，他们就打了她。"}},{"pos":"VERB 动词","cn":"（通常指多次或连续地）撞击，猛撞，拍打","en":"To beat on, at, or against something means to hit it hard, usually several times or continuously for a period of time.","ex":{"en":"There was dead silence but for a fly beating against the glass","cn":"当时一片寂静，只听见一只苍蝇不停地撞击着玻璃。"}},{"pos":"VERB 动词","cn":"（心脏、脉搏等）跳动","en":"When your heart or pulse beats, it continually makes regular rhythmic movements.","ex":{"en":"I felt my heart beating faster.","cn":"我感觉我的心越跳越快。"}},{"pos":"V-ERG 及物/不及物动词","cn":"敲，打，击（鼓等）；（鼓等）敲响","en":"If you beat a drum or similar instrument, you hit it in order to make a sound. You can also say that a drum beats .","ex":{"en":"When you beat the drum, you feel good.","cn":"敲鼓的时候感觉很好。"}},{"pos":"N-COUNT 可数名词","cn":"（音乐的）节奏","en":"The beat of a piece of music is the main rhythm that it has.","ex":{"en":"...the thumping beat of rock music.","cn":"摇滚乐强烈的节奏"}},{"pos":"N-COUNT 可数名词","cn":"（音乐的）拍子，节拍","en":"In music, a beat is a unit of measurement. The number of beats in a bar of a piece of music is indicated by two numbers at the beginning of the piece.","ex":{"en":"It's got four beats to a bar.","cn":"一个小节有4拍。"}},{"pos":"VERB 动词","cn":"搅拌；搅打","en":"If you beat eggs, cream, or butter, you mix them thoroughly using a fork or beater.","ex":{"en":"Beat the eggs and sugar until they start to thicken.","cn":"把鸡蛋和白糖混在一起搅打至开始变稠。"}},{"pos":"V-ERG 及物/不及物动词","cn":"拍打，拍动（翅膀）；（翅膀）拍动","en":"When a bird or insect beats its wings or when its wings beat, its wings move up and down.","ex":{"en":"Beating their wings they flew off","cn":"它们拍打着翅膀飞走了。"}},{"pos":"VERB 动词","cn":"打败；击败；战胜","en":"If you beat someone in a competition or election, you defeat them.","ex":{"en":"In yesterday's games, Switzerland beat the United States two-one","cn":"在昨天的比赛中，瑞士以2比1击败美国。"}},{"pos":"VERB 动词","cn":"打破（纪录等）；超过； 突破","en":"If someone beats a record or achievement, they do better than it.","ex":{"en":"He was as eager as his Captain to beat the record.","cn":"他和队长一样渴望打破这项纪录。"}},{"pos":"VERB 动词","cn":"战胜（某个组织、问题、疾病等）","en":"If you beat something that you are fighting against, for example an organization, a problem, or a disease, you defeat it.","ex":{"en":"It became clear that the Union was not going to beat the government","cn":"情况已然明朗，工会无法和政府抗衡。"}},{"pos":"VERB 动词","cn":"（常指暂时）击退，中断，中止","en":"If an attack or an attempt is beaten off or is beaten back, it is stopped, often temporarily.","ex":{"en":"The rescuers were beaten back by strong winds and currents","cn":"救援人员因风浪太大而被迫中断工作。"}},{"pos":"VERB 动词","cn":"好于；优于；胜于","en":"If you say that one thing beats another, you mean that it is better than it.","ex":{"en":"Being boss of a software firm beats selling insurance","cn":"当软件公司的老板比卖保险强多了。"}},{"pos":"VERB 动词","cn":"没有比…更好的；什么也比不上；最好的莫过于","en":"If you say you can't beat a particular thing you mean that it is the best thing of its kind.","ex":{"en":"You can't beat soap and water for cleansing.","cn":"做清洁没有比用肥皂和水更好的了。"}},{"pos":"VERB 动词","cn":"赶在…前面；抢先","en":"To beat a time limit or an event means to achieve something before that time or event.","ex":{"en":"They were trying to beat the midnight deadline","cn":"他们要努力赶在午夜的最后期限之前完成。"}},{"pos":"N-COUNT 可数名词","cn":"（警察的）辖区，巡逻区；（记者的）负责采访的区域","en":"A police officer's or journalist's beat is the area for which he or she is responsible.","ex":{"en":"The team police get to know the people in their patrol areas better than cops who must cover a larger beat.","cn":"小分队的警察比那些负责大片区域的警察更了解自己管片的群众。"}},{"pos":"VERB 动词","cn":"把…难住；使不明白；使无法解释","en":"You use beat in expressions such as 'It beats me' or 'What beats me is' to indicate that you cannot understand or explain something.","ex":{"en":"'What am I doing wrong, anyway?' — 'Beats me, Lewis.'","cn":"“不管怎样，我到底做错了什么？”——“这我也不知道，刘易斯。”"}},{"pos":"PHRASE 短语","cn":"滚开；走开","en":"If you tell someone to beat it, you are telling them to go away.","ex":{"en":"Beat it before it's too late.","cn":"趁早滚开。"}},{"pos":"CONVENTION 惯用语","cn":"（表示惊讶或恼怒）竟然有这种事？岂有此理！","en":"You can say Can you beat it? or Can you beat that? to show that you are surprised and perhaps annoyed about something.","ex":{"en":"Can you beat it; there was Graham Greene in Freetown and there was I on the other side of Africa.","cn":"真是岂有此理！格雷厄姆·格林在弗里敦，而我却在非洲的另一边。"}},{"pos":"PHRASE 短语","cn":"比…抢先行动；赶在…前面（做某事）","en":"If you intend to do something but someone beats you to it, they do it before you do.","ex":{"en":"Don't be too long about it or you'll find someone has beaten you to it.","cn":"别拖得太久，不然就会有人捷足先登了。"}},{"pos":"PHRASE 短语","cn":"打不过，就入伙","en":"If you can't beat them, join them means that, if someone is too strong for you to defeat, it is better to be on the same side as them."},{"pos":"PHRASE 短语","cn":"停顿；犹豫","en":"If you say or do something without missing a beat, you continue to speak or do it, even though people might have expected you to hesitate or stop.","ex":{"en":"'Are you jealous?' — 'Only when I'm not in control,' he says, not missing a beat.","cn":"“你眼红吗？”——“除非我把持不住自己，”他毫不犹豫地说道。"}},{"pos":"PHRASE 短语","cn":"错失机会","en":"If you say that someone never misses a beat, you mean that they always know what is going on and how they can take advantage of it.","ex":{"en":"Skye has scarcely missed a beat as one of the Gold Coast's spectacular models since her marriage.","cn":"丝凯作为黄金海岸大红大紫的模特儿，自结婚以后从来就没有错失过任何机会。"}},{"pos":"PHRASE 短语","cn":"（警察）值勤，当班，巡逻","en":"A police officer on the beat is on duty, walking around the area for which he or she is responsible.","ex":{"en":"The officer on the beat picks up information; hears cries for help; makes people feel safe.","cn":"值勤警员注意观察情况，对救援呼叫及时反应，确保让百姓有一种安全感。"}},{"pos":"PHRASE 短语","cn":"打拍子","en":"If you beat time to a piece of music, you move your hand or foot up and down in time with the music. A conductor beats time to show the choir or orchestra how fast they should sing or play the music.","ex":{"en":"He beats time with hands and feet.","cn":"他手脚并用地打着拍子。"}},{"pos":"","cn":"","en":"to beat someone black and blue→see: ; to beat someone's brains out→see: ; to beat one's breast→see: ; to beat about the bush→see: ; to beat the clock→see: ; to beat or knock the living daylights out of someone→see: ; to beat the drum for someone or something→see: ; to beat someone at their own game→see: ; to beat a retreat→see: ; to beat a retreat→see: ; to beat→see: ; a stick to beat someone with→see: ;"},{"pos":"","cn":"","en":"相关词组：beat down beat out beat out of beat up beat up on"}]},"examples":[{"en":"He wanted $8 000 for the car but I beat him down to $6 000.","cn":"他那辆汽车要价 8 000 元，但我压到了 6 000 元。"},{"en":"Top theatrical agents are beating a path to the teenager's door.","cn":"顶尖级戏剧演员代理人正纷纷把目光投向那个青少年。"}]},"beneath":{"media":{"uk":"media/uk/beneath__gb_1.mp3","us":"media/us/beneath__us_1.mp3"},"oxford":{"phon":"bɪˈniːθ","pos":"preposition","senses":[{"en":"in or to a lower position than somebody/something; under somebody/something","cn":"在（或往）…下面；在（或往）…下方","ex":{"en":"They found the body buried beneath a pile of leaves.","cn":"他们发现尸体被埋在一堆树叶下面。"}},{"en":"not good enough for somebody","cn":"（对某人来说）不够好","ex":{"en":"He considers such jobs beneath him.","cn":"他觉得这些工作有失他的身份。"}},{"en":"in or to a lower position than somebody/something","cn":"在（或往）…下面；在（或往）…下方","ex":{"en":"Her careful make-up hid the signs of age beneath.","cn":"她精心的化妆遮盖了她年龄的痕迹。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…之下；在…下面","en":"Something that is beneath another thing is under the other thing.","ex":{"en":"She could see the muscles of his shoulders beneath his T-shirt","cn":"她可以看到他T恤衫下的肩部肌肉。"}},{"pos":"PREP 介词","cn":"在…表面之下；在…的背后","en":"If you talk about what is beneath the surface of something, you are talking about the aspects of it which are hidden or not obvious.","ex":{"en":"...emotional strains beneath the surface","cn":"表面之下的情感纠结"}},{"pos":"PREP 介词","cn":"不如；比不上；配不上","en":"If you say that someone or something is beneath you, you feel that they are not good enough for you or not suitable for you.","ex":{"en":"They decided she was marrying beneath her","cn":"他们认定她要嫁给一个配不上她的人。"}}]},"examples":[{"en":"They thought she had married beneath her (= married a man of lower social status).","cn":"他们认为她下嫁了（嫁给了地位比她低的人）。"},{"en":"They found the body buried beneath a pile of leaves.","cn":"他们发现尸体被埋在一堆树叶下面。"}]},"be":{"media":{"uk":"media/uk/be__gb_1.mp3","us":"media/us/be__us_1.mp3"},"oxford":{"phon":"bi","pos":"verb","senses":[{"en":"used when you are naming people or things, describing them or giving more information about them","cn":"（提供名称或信息时用）","ex":{"en":"Today is Monday.","cn":"今天是星期一。"}},{"en":"used when you are describing a situation or saying what you think about it","cn":"（描述情况或表达想法时用）","ex":{"en":"It was really hot in the sauna.","cn":"桑拿浴的确很热。"}},{"en":"to exist; to be present","cn":"有；存在","ex":{"en":"Is there a God?","cn":"上帝存在吗？"}},{"en":"to be located; to be in a place","cn":"位于；在（某处）","g":"[intransitive]","ex":{"en":"The town is three miles away.","cn":"镇子距此地三英里远。"}},{"en":"used to say where somebody was born or where their home is","cn":"出生于（某地）；来自…；是（某地的）人","g":"[intransitive]","ex":{"en":"She's from Italy.","cn":"她是意大利人。"}},{"en":"to happen at a time or in a place","cn":"（在某时或某地）发生","g":"[intransitive]","ex":{"en":"The party is on Friday evening.","cn":"聚会定于周五晚上举行。"}},{"en":"to remain in a place","cn":"留在（某地）；逗留","g":"[intransitive]","ex":{"en":"She has been in her room for hours.","cn":"她已经在她的房间里待了几个小时了。"}},{"en":"to attend an event; to be present in a place","cn":"出席；到场","g":"[intransitive]","ex":{"en":"I'll be at the party.","cn":"我将出席聚会。"}},{"en":"used to talk about time","cn":"（用于表达时间）","ex":{"en":"It's two thirty.","cn":"现在是两点三十。"}},{"en":"to cost","cn":"花费；值","ex":{"en":"‘How much is that dress?’ ‘Eighty dollars.’","cn":"“那条连衣裙多少钱？”“八十美元。”"}},{"en":"to be equal to","cn":"等于；等同","ex":{"en":"Three and three is six.","cn":"三加三等于六。"}},{"en":"to visit or call","cn":"前往；造访；访问","g":"[intransitive]","lab":"British English","ex":{"en":"I've never been to Spain.","cn":"我从未去过西班牙。"}},{"en":"used to say what something is made of","cn":"（表示所用的材料）","ex":{"en":"Is your jacket real leather?","cn":"你的夹克是真皮的吗？"}},{"en":"used to say who something belongs to or who it is intended for","cn":"（表示某物所属）","g":"[intransitive]","ex":{"en":"The money's not yours, it's John's.","cn":"这钱不是你的，是约翰的。"}},{"en":"used to say how important something is to somebody","cn":"（表示对某人的重要性）","ex":{"en":"Money isn't everything (= it is not the only important thing).","cn":"金钱不是一切（不是唯一重要的东西）。"}},{"en":"used with a present participle to form progressive tenses","cn":"（与现在分词连用构成进行时）","ex":{"en":"I am studying Chinese.","cn":"我正在学中文。"},"pos":"auxiliary verb"},{"en":"used to make question tags (= short questions added to the end of statements)","cn":"（用于反意疑问句）","ex":{"en":"You're not hungry, are you?","cn":"你不饿，对吧？"},"pos":"auxiliary verb"},{"en":"used with a past participle to form the passive","cn":"（与过去分词连用构成被动语态）","ex":{"en":"He was killed in the war.","cn":"他死于这场战争。"},"pos":"auxiliary verb"},{"en":"used to avoid repeating the full form of a verb in the passive or a progressive tense","cn":"（在被动语态或进行时中代替重复的动词完整形式）","ex":{"en":"Karen wasn't beaten in any of her games, but all the others were.","cn":"卡伦没有输掉任何一场比赛，但所有其他人都输过。"},"pos":"auxiliary verb"},{"en":"used to say what must or should be done","cn":"（表示必须或应该）","ex":{"en":"I am to call them once I reach the airport.","cn":"我一到机场就得给他们打电话。"},"pos":"auxiliary verb"},{"en":"used to say what is arranged to happen","cn":"（表示已安排好要做的事）","ex":{"en":"They are to be married in June.","cn":"他们计划于六月份结婚。"},"pos":"auxiliary verb"},{"en":"used to say what happened later","cn":"（表示后来发生的事）","ex":{"en":"He was to regret that decision for the rest of his life (= he did regret it).","cn":"他终生都会后悔作出了那一决定。"},"pos":"auxiliary verb"},{"en":"used to say what could not or did not happen","cn":"（表示不会或没有发生时用）","ex":{"en":"Anna was nowhere to be found (= we could not find her anywhere).","cn":"我们到处都找不到安娜。"},"pos":"auxiliary verb"},{"en":"used to express a condition","cn":"（表述条件）","lab":"formal","ex":{"en":"If we were to offer you more money, would you stay?","cn":"假如我们给你加钱，你愿意留下吗？"},"pos":"auxiliary verb"},{"en":"to make or treat somebody/something as","cn":"使…变成；把…当作","ex":{"en":"Don't belittle his achievements (= say they are not important).","cn":"不要贬低他的成就。"},"pos":"prefix"},{"en":"wearing or covered with","cn":"穿着；戴着；裹着","ex":{"en":"heavily bejewelled fingers","cn":"戴满珠宝的手指"},"pos":"prefix"},{"en":"to cause something to be","cn":"使；使成为","ex":{"en":"The ship was becalmed (= there was no wind so it could not move).","cn":"帆船因无风而停航。"},"pos":"prefix"},{"en":"used to turn intransitive verbs (= without an object) into transitive verbs (= with an object)","cn":"（与不及物动词结合，构成及物动词）","ex":{"en":"She is always bemoaning her lot.","cn":"她总是怪命不好。"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"AUX 助动词","cn":"（和现在分词连用构成动词的进行式）","en":"You use be with a present participle to form the continuous tenses of verbs. be going to→see: ;","ex":{"en":"This is happening in every school throughout the country","cn":"全国各地每所学校都在发生这样的事情。"}},{"pos":"AUX 助动词","cn":"（和过去分词连用构成被动语态）","en":"You use be with a past participle to form the passive voice.","ex":{"en":"Forensic experts were called in","cn":"法医专家被请来。"}},{"pos":"AUX 助动词","cn":"（和不定式连用表示将来的安排或确定会发生的事情）","en":"You use be with an infinitive to indicate that something is planned to happen, that it will definitely happen, or that it must happen. be about to→see: ;","ex":{"en":"The talks are to begin tomorrow","cn":"谈判将于明天开始。"}},{"pos":"AUX 助动词","cn":"（和不定式连用表示在某种情况下会发生什么事，应该怎样做或应该由谁来做）","en":"You use be with an infinitive to say or ask what should happen or be done in a particular situation, how it should happen, or who should do it.","ex":{"en":"What am I to do without him?","cn":"没有他，我该怎么办？"}},{"pos":"AUX 助动词","cn":"（was和were和不定式连用，表示说话时间之后发生的事）","en":"You use was and were with an infinitive to talk about something that happened later than the time you are discussing, and was not planned or certain at that time.","ex":{"en":"Then he received a phone call that was to change his life","cn":"然后，他接到一个将改变他一生的电话。"}},{"pos":"AUX 助动词","cn":"（表示可见到、可听到、可发现等）","en":"You can say that something is to be seen, heard, or found in a particular place to mean that people can see it, hear it, or find it in that place.","ex":{"en":"Little traffic was to be seen on the streets","cn":"街上车辆很少。"}},{"pos":"V-LINK 连系动词","cn":"（用于提供与主语相关的信息）","en":"You use be to introduce more information about the subject, such as its identity, nature, qualities, or position.","ex":{"en":"She's my mother","cn":"她是我母亲。"}},{"pos":"V-LINK 连系动词","cn":"（以it作主语，用来进行描述或作出判断）","en":"You use be, with 'it' as the subject, in clauses where you are describing something or giving your judgment of a situation.","ex":{"en":"It was too chilly for swimming","cn":"这时候游泳太冷了。"}},{"pos":"V-LINK 连系动词","cn":"（与非人称代词there连用构成there is和there are表示存在或发生）","en":"You use be with the impersonal pronoun 'there' in expressions like there is and there are to say that something exists or happens.","ex":{"en":"Clearly there is a problem here","cn":"显然，这里出了个问题。"}},{"pos":"V-LINK 连系动词","cn":"（表示主语和从句和其他从句结构之间的某种联系）","en":"You use be as a link between a subject and a clause and in certain other clause structures, as shown below.","ex":{"en":"It was me she didn't like, not what I represented","cn":"她不喜欢的是我，而不是我的陈述。"}},{"pos":"V-LINK 连系动词","cn":"（用在如the thing is和the point is这样的结构中，引导表示陈述或提出观点的从句）","en":"You use be in expressions like the thing is and the point is to introduce a clause in which you make a statement or give your opinion.","ex":{"en":"The fact is, the players gave everything they had","cn":"事实上，选手们尽了全力。"}},{"pos":"V-LINK 连系动词","cn":"（用在如to be fair, to be honest或to be serious 这样的结构中表示尽量）","en":"You use be in expressions like to be fair ,to be honest, or to be serious to introduce an additional statement or opinion, and to indicate that you are trying to be fair, honest, or serious.","ex":{"en":"She's always noticed. But then, to be honest, Ghislaine likes being noticed","cn":"她总是受到关注。但是说句实在话，吉莱纳喜欢被人关注。"}},{"pos":"V-LINK 连系动词","cn":"（有时用来代替现在时态中be的几个常规形式，尤用于whether后）","en":"The form 'be' is used occasionally instead of the normal forms of the present tense, especially after 'whether'.","ex":{"en":"The chemical agent, whether it be mustard gas or nerve gas, can be absorbed by the skin.","cn":"这类化学制剂，不管是芥子气还是神经瓦斯，都会被皮肤吸收。"}},{"pos":"VERB 动词","cn":"存在","en":"If something is, it exists.","ex":{"en":"It hurt so badly he wished to cease to be.","cn":"他觉得疼痛难忍，恨不得死了算了。"}},{"pos":"V-LINK 连系动词","cn":"保持真我；按自己的方式行事；显常态","en":"To be yourself means to behave in the way that is right and natural for you and your personality.","ex":{"en":"She'd learnt to be herself and to stand up for her convictions.","cn":"她已经学会了按自己的方式行事，坚持自己的信仰。"}},{"pos":"PHRASE 短语","cn":"非常；极为","en":"If someone or something is, for example, as happy as can be or as quiet as could be, they are extremely happy or extremely quiet."},{"pos":"PHRASE 短语","cn":"如果不是…的话；如果没有…的话","en":"If you talk about what would happen if it wasn't for someone or something, you mean that they are the only thing that is preventing it from happening.","ex":{"en":"I could happily move back into a flat if it wasn't for the fact that I'd miss my garden","cn":"如果不是因为我会想念自己的花园的话，我会很乐意搬回公寓住。"}},{"pos":"PHRASE 短语","cn":"尽管那样；即便如此","en":"You say 'Be that as it may' when you want to move onto another subject or go further with the discussion, without deciding whether what has just been said is right or wrong.","ex":{"en":"'Is he still just as fat?' — 'I wouldn't know,' continued her mother, ignoring the interruption, 'and be that as it may, he has made a fortune.'","cn":"“他还是那么胖吗？”——“我不知道，”她妈妈接着说，没有理睬这一打岔，“就算那样，他已经发财了。”"}},{"pos":"PHRASE 短语","cn":"身体不舒服；身体不适","en":"If you say that you are not yourself, you mean you are not feeling well.","ex":{"en":"She is not herself. She came near to a breakdown.","cn":"她身体不舒服，简直要崩溃了。"}}]},"examples":[{"en":"London is not England (= do not think that all of England is like London).","cn":"伦敦并不等于英格兰（不要以为整个英格兰都像伦敦）。"},{"en":"Karen wasn't beaten in any of her games, but all the others were.","cn":"卡伦没有输掉任何一场比赛，但所有其他人都输过。"}]},"benefit":{"media":{"uk":"media/uk/benefit__gb_1.mp3","us":"media/us/benefit__us_1.mp3"},"oxford":{"phon":"ˈbenɪfɪt","pos":"noun","senses":[{"en":"an advantage that something gives you; a helpful and useful effect that something has","cn":"优势；益处；成效","g":"[countable, uncountable]","ex":{"en":"Freedom of information brings great benefits.","cn":"信息自由带来巨大的益处。"}},{"en":"money provided by the government to people who need financial help because they are unemployed, ill, etc.","cn":"福利费（政府对失业者、病人等提供的补助金）","g":"[countable, usually plural, uncountable]","lab":"British English","ex":{"en":"You may be eligible to receive benefits.","cn":"你也许有资格领取福利金。"}},{"en":"an advantage that you get from a company in addition to the money that you earn","cn":"（公司发的）福利，奖金","g":"[countable, usually plural]","ex":{"en":"Private health insurance is offered as part of the employees' benefits package.","cn":"私人医疗保险是提供给员工的一整套福利的其中一项。"}},{"en":"money from an insurance company","cn":"（保险公司发的）给付，保险金","g":"[countable, usually plural]","ex":{"en":"The insurance plan will provide substantial cash benefits to your family in case of your death.","cn":"投保人一旦死亡，该项保险将支付给其家属相当可观的保险金。"}},{"en":"an event such as a performance, a dinner, etc., organized in order to raise money for a particular person or charity","cn":"慈善（或公益）活动","g":"[countable]","ex":{"en":"a benefit match/concert","cn":"义赛；慈善音乐会"}},{"en":"to be useful to somebody or improve their life in some way","cn":"对（某人）有用；使受益","g":"[transitive]","ex":{"en":"We should spend the money on something that will benefit everyone.","cn":"我们应该把这笔钱花在大家都能得益的事上。"},"pos":"verb"},{"en":"to be in a better position because of something","cn":"得益于；得利于","g":"[intransitive]","ex":{"en":"We all benefit when our young people realize their potential.","cn":"当我们的年轻人意识到他们的潜力时，我们都会受益。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"好处；益处；裨益","en":"The benefit of something is the help that you get from it or the advantage that results from it.","ex":{"en":"Each family farms individually and reaps the benefit of its labor","cn":"各家经营各自的农场，收获各自的劳动成果。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（对…有）好处，帮助","en":"If something is to your benefit or is of benefit to you, it helps you or improves your life.","ex":{"en":"This could now work to Albania's benefit","cn":"这种情况目前对阿尔巴尼亚有利。"}},{"pos":"V-ERG 及物/不及物动词","cn":"获益；对…有益；有利于","en":"If you benefit from something or if it benefits you, it helps you or improves your life.","ex":{"en":"Both sides have benefited from the talks.","cn":"双方都从谈判中获益。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"有利条件；优势","en":"If you have the benefit of some information, knowledge, or equipment, you are able to use it so that you can achieve something.","ex":{"en":"Steve didn't have the benefit of a formal college education","cn":"史蒂夫没能接受正规的大学教育。"}},{"pos":"N-VAR 可变名词","cn":"（政府提供给穷人、病人和失业人员的）救济金，补助金","en":"Benefit is money that is given by the government to people who are poor, ill, or unemployed.","ex":{"en":"...the removal of benefit from school-leavers","cn":"取消辍学者的补助金"}},{"pos":"N-COUNT 可数名词","cn":"慈善活动","en":"A benefit, or a benefit concert or dinner, is an event that is held in order to raise money for a particular charity or person.","ex":{"en":"I am organising a benefit gig in Bristol to raise these funds.","cn":"我要在布里斯托尔组织一场义演来募集这些资金。"}},{"pos":"PHRASE 短语","cn":"暂且相信；姑且信之","en":"If you give someone the benefit of the doubt, you treat them as if they are telling the truth or as if they have behaved properly, even though you are not sure that this is the case.","ex":{"en":"At first I gave him the benefit of the doubt","cn":"起初，我姑且相信了他。"}},{"pos":"PHRASE 短语","cn":"为了…的利益；为…好","en":"If you say that someone is doing something for the benefit of a particular person, you mean that they are doing it for that person.","ex":{"en":"You need people working for the benefit of the community","cn":"你们需要为社区谋利益的人。"}}]},"examples":[{"en":"The insurance plan will provide substantial cash benefits to your family in case of your death.","cn":"投保人一旦死亡，该项保险将支付给其家属相当可观的保险金。"},{"en":"We should spend the money on something that will benefit everyone.","cn":"我们应该把这笔钱花在大家都能得益的事上。"}]},"best":{"media":{"uk":"media/uk/best__gb_1.mp3","us":"media/us/best__us_1.mp3"},"oxford":{"phon":"best","pos":"adjective","senses":[{"en":"of the most excellent type or quality","cn":"最好的；最出色的；最优秀的","ex":{"en":"That's the best movie I've ever seen!","cn":"那是我看过的最棒的电影！"}},{"en":"giving most pleasure; happiest","cn":"最快乐的；最幸福的","ex":{"en":"Those were the best years of my life.","cn":"那些年是我一生最幸福的时光。"}},{"en":"most suitable or appropriate","cn":"最合适的；最恰当的","ex":{"en":"What's the best way to cook steak?","cn":"牛排怎么做最好？"}},{"en":"most; to the greatest extent","cn":"最；最高程度地","ex":{"en":"Which one do you like best?","cn":"你最喜欢哪一个？"},"pos":"adverb"},{"en":"in the most excellent way; to the highest standard","cn":"最出色地；最高标准地","ex":{"en":"He works best in the mornings.","cn":"他早上工作效率最高。"},"pos":"adverb"},{"en":"in the most suitable or appropriate way","cn":"最适合地；最恰当地","ex":{"en":"Painting is best done in daylight.","cn":"作画的最佳时间是白天。"},"pos":"adverb"},{"en":"the most excellent thing or person","cn":"最好的事物（或人）","ex":{"en":"We all want the best for our children.","cn":"我们都想给孩子提供最好的条件。"},"pos":"noun"},{"en":"the highest standard that somebody/something can reach","cn":"（人或事物所能达到的）最高标准","ex":{"en":"She always brings out the best in people.","cn":"她总是让人表现出最优秀的品质。"},"pos":"noun"},{"en":"something that is as close as possible to what you need or want","cn":"最合乎要求的事物","ex":{"en":"Fifty pounds is the best I can offer you.","cn":"我顶多出五十英镑。"},"pos":"noun"},{"en":"the highest standard that a particular person has reached, especially in a sport","cn":"（个人的）最高水平，最高纪录","ex":{"en":"a lifetime best of 12.0 seconds","cn":"12.0 秒的毕生最好成绩"},"pos":"noun"},{"en":"to defeat or be more successful than somebody","cn":"打败；胜过","ex":{"en":"He was determined not to be bested by his old rival.","cn":"他决心不被他的老对手打败。"},"pos":"verb"},{"en":"a British magazine aimed at women that contains articles on health, fashion, sex, food, famous people and entertainment. It first appeared in 1987 and is published every week.","cn":"一本针对女性的英国杂志，包含有关健康、时尚、性、食物、名人和娱乐的文章。它于 1987 年首次出版，每周出版一次。","pos":""}]},"collins":{"senses":[{"pos":"","cn":"","en":"Best is the superlative of good .","ex":{"en":"If you want further information the best thing to do is have a word with the driver as you get on the bus","cn":"如果你想了解更多信息，最好的办法是在上公交车时问一问司机。"}},{"pos":"","cn":"","en":"Best is the superlative of well .","ex":{"en":"James Fox is best known as the author of White Mischief.","cn":"詹姆斯·福克斯以《欲望城》一书最为出名。"}},{"pos":"N-SING 单数名词","cn":"最好的；绝佳的","en":"The best is used to refer to things of the highest quality or standard.","ex":{"en":"We offer only the best to our clients","cn":"我们只把最好的服务提供给客户。"}},{"pos":"N-SING 单数名词","cn":"最大努力；最高成就；最好水平","en":"Someone's best is the greatest effort or highest achievement or standard that they are capable of.","ex":{"en":"Miss Blockey was at her best when she played the piano","cn":"布洛基小姐弹钢琴的时候发挥了她的最好水平。"}},{"pos":"N-SING 单数名词","cn":"最好的结果；顶多","en":"If you say that something is the best that can be done or hoped for, you think it is the most pleasant, successful, or useful thing that can be done or hoped for.","ex":{"en":"A draw seems the best they can hope for","cn":"看来他们顶多只能指望打个平局了。"}},{"pos":"ADV-SUPERL 副词最高级形式","cn":"最；极","en":"If you like something best or like it the best, you prefer it.","ex":{"en":"The thing I liked best about the show was the music","cn":"这场演出中我最喜欢的是它的音乐。"}},{"pos":"","cn":"（用于构成以good和well开头的复合形容词的最高级，如well-known的最高级为best-known）","en":"Best is used to form the superlative of compound adjectives beginning with 'good' and 'well'. For example, the superlative of 'well-known' is 'best-known'."},{"pos":"CONVENTION 惯用语","cn":"（用于道别或信件末尾）万事如意，一切顺利","en":"You can say 'All the best' when you are saying goodbye to someone, or at the end of a letter.","ex":{"en":"Wish him all the best, and tell him we miss him.","cn":"祝他一切顺利，告诉他我们想念他。"}},{"pos":"PHRASE 短语","cn":"最好的是","en":"You use best of all to indicate that what you are about to mention is the thing that you prefer or that has most advantages out of all the things you have mentioned.","ex":{"en":"It was comfortable and cheap: best of all, most of the rent was being paid by two American friends.","cn":"房子既舒适又便宜：最妙的是，大部分租金是由两位美国朋友支付的。"}},{"pos":"PHRASE 短语","cn":"尽全力；竭尽所能；尽最大努力","en":"If someone does something as best they can, they do it as well as they can, although it is very difficult.","ex":{"en":"The older people were left to carry on as best they could.","cn":"年纪大一点的人被留下来，奋力坚持。"}},{"pos":"PHRASE 短语","cn":"充其量；顶多；至多","en":"You use at best to indicate that even if you describe something as favourably as possible or if it performs as well as it possibly can, it is still not very good.","ex":{"en":"This policy, they say, is at best confused and at worst non-existent","cn":"有人说这项政策往好里说是混乱不堪，往坏里说就是形同虚设。"}},{"pos":"PHRASE 短语","cn":"尽力；竭尽所能","en":"If you do your best or try your best to do something, you try as hard as you can to do it, or do it as well as you can.","ex":{"en":"I'll do my best to find out","cn":"我会尽力查明真相。"}},{"pos":"PHRASE 短语","cn":"（综合考虑起来）是最好的","en":"If you say that something is for the best, you mean it is the most desirable or helpful thing that could have happened or could be done, considering all the circumstances.","ex":{"en":"In the long run, it was for the best","cn":"长远来说，这是最好的。"}},{"pos":"PHRASE 短语","cn":"（尤指冰释前嫌后）最好的朋友；知己","en":"If two people are the best of friends, they are close friends, especially when they have had a disagreement or fight in the past.","ex":{"en":"Magda is now married to George Callerby and we are the best of friends.","cn":"玛格达现在已经和乔治·卡勒比结婚了，我们成了最好的朋友。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"最好（有些人认为此用法不规范）","en":"If you say that someone had best do something or that they'd best do it, you mean they ought to do it. Some people consider this to be non-standard.","ex":{"en":"You'd best take a look.","cn":"你最好还是看一看。"}},{"pos":"PHRASE 短语","cn":"（因经验丰富）最清楚，最明白","en":"If you say that a particular person knows best, you mean that they have a lot of experience and should therefore be trusted to make decisions for other people.","ex":{"en":"He was convinced that doctors and dentists knew best.","cn":"他确信医生和牙医最清楚该怎么做。"}},{"pos":"PHRASE 短语","cn":"看起来处于自己最迷人的状态","en":"If you look your best, you are looking as smart and attractive as you can.","ex":{"en":"I made sure I was very clean and looking my best.","cn":"我把自己收拾得十分整洁，美丽动人。"}},{"pos":"PHRASE 短语","cn":"乐观地尽可能利用（逆境）","en":"If you make the best of something, you accept an unsatisfactory situation cheerfully and try to manage as well as you can. In British English, you can also say that you make the best of a bad job .","ex":{"en":"She instilled in the children the virtues of good hard work, and making the best of what you have.","cn":"她慢慢给孩子们灌输勤奋工作的品德，教导他们充分利用现有的条件。"}},{"pos":"","cn":"","en":"to the best of your ability→see: ; the best of the bunch→see: ; to hope for the best→see: ; to the best of your knowledge→see: ; best of luck→see: ; the best part→see: ; at the best of times→see: ; the best of both worlds→see: ;"}]},"examples":[{"en":"She won the race with a personal best of 2 minutes 22.","cn":"她以 2 分 22 秒的个人最好成绩赢得了这项比赛。"},{"en":"I'm sorry if my advice offended you — I meant it for the best.","cn":"如果我的建议冒犯了你，我很抱歉。但我原本是出于好意。"}],"base":"good"},"bent":{"media":{"img":["media/pic/curved_comp.jpg","media/thumb/bent.jpg"],"uk":"media/uk/bent__gb_2.mp3","us":"media/us/bent__us_2.mp3"},"oxford":{"phon":"bent","pos":"adjective","senses":[{"en":"not straight","cn":"弯曲的","ex":{"en":"a piece of bent wire","cn":"一段弯曲的金属丝"}},{"en":"not able to stand up straight, usually as a result of being old or ill","cn":"（因年老或生病）驼背的，弯腰的","ex":{"en":"a small bent old woman","cn":"一个矮小驼背的老太太"}},{"en":"dishonest","cn":"不诚实的；不正派的","lab":"British English, informal，，"},{"en":"a natural skill or interest in something","cn":"（某方面的）天赋，爱好","ex":{"en":"She has a bent for mathematics.","cn":"她有数学天赋。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Bent is the past tense and past participle of bend ."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"折断的；弯曲的；变形的","en":"If an object is bent, it is damaged and no longer has its correct shape.","ex":{"en":"The trees were all bent and twisted from the wind.","cn":"树全被风吹弯折断了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）驼背的","en":"If a person is bent, their body has become curved because of old age or disease.","ex":{"en":"...a bent, frail, old man.","cn":"一位孱弱的驼背老人"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指做不好的事情）决意的，下定决心的","en":"If someone is bent on doing something, especially something harmful, they are determined to do it.","ex":{"en":"He's bent on suicide.","cn":"他执意要自杀。"}},{"pos":"N-SING 单数名词","cn":"才能；爱好；禀赋","en":"If you have a bent for something, you have a natural ability to do it or a natural interest in it.","ex":{"en":"His bent for natural history directed him towards his first job.","cn":"他选择第一份工作是出自对博物学的热爱。"}},{"pos":"N-SING 单数名词","cn":"信仰","en":"If someone is of a particular bent, they hold a particular set of beliefs.","ex":{"en":"...economists of a socialist bent.","cn":"信仰社会主义的经济学家"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（官员等）不正直的，贪赃枉法的","en":"If you say that someone in a position of responsibility is bent, you mean that they are dishonest or do illegal things.","ex":{"en":"...this bent accountant.","cn":"这个腐败的会计"}},{"pos":"ADJ 形容词","cn":"同性恋的（可能具冒犯意味）","en":"Homosexuals are sometimes described as bent. This use could cause offence."},{"pos":"PHRASE 短语","cn":"（疼或笑得）弯了腰，直不起腰（美国英语中亦用 bent over double）","en":"If someone is bent double, the top part of their body is leaning forward towards their legs, usually because they are in great pain or because they are laughing a lot. In American English, you can also say that someone is bent over double.","ex":{"en":"He left the courtroom on the first day bent double with stomach pain.","cn":"第一天他就因胃痛得直不起腰而离开了法庭。"}}]},"examples":[{"en":"Don't get bent out of shape about it. It was just a mistake!","cn":"不要为这事烦恼了，那只是一个错误而已！"},{"en":"Do this exercise with your knees bent (= not with your legs straight).","cn":"做这个动作要双膝弯曲。"}],"base":"bend"},"beautiful":{"media":{"uk":"media/uk/beautiful__gb_1.mp3","us":"media/us/beautiful__us_1.mp3"},"oxford":{"phon":"ˈbjuːtɪfl","pos":"adjective","senses":[{"en":"having beauty; giving pleasure to the senses or to the mind","cn":"美丽的；美好的","ex":{"en":"a beautiful woman/girl","cn":"漂亮的女人／女孩"}},{"en":"very good; very kind or showing great skill","cn":"极好的；善良的；巧妙的","ex":{"en":"Thank you—you have done a beautiful thing.","cn":"谢谢你！你做了一件大好事。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"美丽的；漂亮的","en":"A beautiful person is very attractive to look at.","ex":{"en":"She was a very beautiful woman","cn":"她是个大美女。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"美好的；极好的；美妙的","en":"If you describe something as beautiful, you mean that it is very attractive or pleasing.","ex":{"en":"New England is beautiful","cn":"新英格兰很美。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"巧妙的；娴熟的；漂亮的","en":"You can describe something that someone does as beautiful when they do it very skilfully.","ex":{"en":"That's a beautiful shot!","cn":"射得漂亮！"}}]},"examples":[{"en":"He was described as ‘ tall, dark and handsome ’.","cn":"他被描述为“高大黝黑、相貌堂堂”。"},{"en":"She arrived with a very good-looking man.","cn":"她和一个非常英俊的男人一起到来。"}]},"beguiling":{"media":{"uk":"media/uk/beguiling__gb_1.mp3","us":"media/us/beguiling__us_1.mp3"},"oxford":{"phon":"bɪˈɡaɪlɪŋ","pos":"adjective","senses":[{"en":"attractive and interesting but sometimes mysterious or trying to trick you","cn":"迷人的；诱人的；诱骗的；难以琢磨的","ex":{"en":"beguiling advertisements","cn":"富有诱惑力的广告"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"迷人的；吸引人的","en":"Something that is beguiling is charming and attractive.","ex":{"en":"Mombasa is a town with a beguiling Arabic flavour.","cn":"蒙巴萨是一座充满迷人的阿拉伯风情的城市。"}}]},"examples":[{"en":"Her beauty was beguiling.","cn":"她美得迷人。"},{"en":"beguiling advertisements","cn":"富有诱惑力的广告"}]},"beacons":{"lemma":"beacon"},"beneficial":{"oxford":{"phon":"ˌbenɪˈfɪʃl","pos":"adjective","senses":[{"en":"improving a situation; having a helpful or useful effect","cn":"有利的；有裨益的；有用的","ex":{"en":"A good diet is beneficial to health.","cn":"良好的饮食有益于健康。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有益的；有利的；有帮助的","en":"Something that is beneficial helps people or improves their lives.","ex":{"en":"...vitamins which are beneficial to our health","cn":"对我们健康有益的维生素"}}]},"media":{"uk":"media/uk/beneficial__gb_1.mp3","us":"media/us/beneficial__us_1.mp3"},"examples":[{"en":"A good diet is beneficial to health.","cn":"良好的饮食有益于健康。"},{"en":"a drug that has a beneficial effect on the immune system","cn":"有益于免疫系统的一种药物"}]},"became":{"lemma":"become","media":{"uk":"media/uk/became__gb_1.mp3","us":"media/us/became__us_1.mp3"}},"befriend":{"media":{"uk":"media/uk/befriend__gb_1.mp3","us":"media/us/befriend__us_1.mp3"},"oxford":{"phon":"bɪˈfrend","pos":"verb","senses":[{"en":"to become a friend of somebody, especially somebody who needs your help","cn":"（尤指和需要帮助者）做朋友；友善相待","ex":{"en":"Shortly after my arrival at the school, I was befriended by an older girl.","cn":"我到学校后不久便得到了一位年龄较大的女孩友善对待。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"和（尤指孤独者或离乡人）交朋友；把…当朋友","en":"If you befriend someone, especially someone who is lonely or far from home, you make friends with them.","ex":{"en":"The film's about an elderly woman and a young nurse who befriends her","cn":"电影讲述的是一位老太太和一个待她友善的年轻护士的故事。"}}]},"examples":[{"en":"Shortly after my arrival at the school, I was befriended by an older girl.","cn":"我到学校后不久便得到了一位年龄较大的女孩友善对待。"},{"en":"They befriended me when I first arrived in London as a student.","cn":"我初到伦敦求学时﹐他们待我如同朋友。"}]},"bench":{"media":{"uk":"media/uk/bench__gb_1.mp3","us":"media/us/bench__us_1.mp3","img":["media/ldoce/img/park_bench.jpg"]},"oxford":{"phon":"bentʃ","pos":"noun","senses":[{"en":"a long seat for two or more people, usually made of wood","cn":"（木制）长凳，长椅","g":"[countable]","ex":{"en":"a park bench","cn":"公园的长椅"}},{"en":"a judge in court or the seat where he/she sits; the position of being a judge or magistrate","cn":"法官；法官席位；法官（或裁判官）的职位","g":"[singular]","lab":"law","ex":{"en":"His lawyer turned to address the bench.","cn":"他的律师转身对法官讲话。"}},{"en":"(in the British parliament) a seat where a particular group of politicians sit","cn":"（英国议会的）议员席","g":"[countable, usually plural]","ex":{"en":"There was cheering from the Opposition benches.","cn":"反对党议员席那边响起了欢呼声。"}},{"en":"the seats where players sit when they are not playing in the game","cn":"（场边的）运动员休息区","g":"[singular]","lab":"sport","ex":{"en":"the substitutes’ bench","cn":"替补队员席"}},{"en":"a long heavy table used for doing practical jobs, working with tools, etc.","cn":"工作台","g":"[countable]","ex":{"en":"a carpenter’s bench","cn":"木工的工作台"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"长凳；长椅","en":"A bench is a long seat of wood or metal that two or more people can sit on.","ex":{"en":"He sat down on a park bench.","cn":"他在公园的长椅上坐了下来。"}},{"pos":"N-COUNT 可数名词","cn":"（长方形）工作台，实验台","en":"A bench is a long, narrow table in a factory or laboratory.","ex":{"en":"...the laboratory bench.","cn":"实验台"}},{"pos":"N-PLURAL 复数名词","cn":"议员席；议席","en":"In parliament, different groups sit on different benches. For example, the government sits on the government benches .","ex":{"en":"...the opposition benches.","cn":"反对派议席"}},{"pos":"N-SING-COLL 单数集合名词","cn":"法官；地方执法官","en":"In a court of law, the bench is the judge or magistrates.","ex":{"en":"The chairman of the bench adjourned the case until October 27.","cn":"主审法官将案件延期到10月27日审理。"}},{"pos":"N-SING 单数名词","cn":"法官职位；地方执法官职位","en":"If someone serves on the bench, they work as a judge or magistrate.","ex":{"en":"Allgood served on the bench for more than 50 years.","cn":"奥尔古德当了五十多年的法官。"}},{"pos":"N-SING 单数名词","cn":"（体育比赛的）替补席","en":"If a member of a sports team is on the bench for a particular match, he or she waits at the side of the field until the manager tells them to play.","ex":{"en":"Ian Ferguson was preferred to Stuart McCall, who was on the bench.","cn":"伊恩·弗格森比坐在替补席上的斯图尔特·麦考尔更受器重。"}}]},"examples":[{"en":"There was cheering from the Opposition benches.","cn":"反对党议员席那边响起了欢呼声。"},{"en":"His lawyer turned to address the bench.","cn":"他的律师转身对法官讲话。"}]},"behalf":{"oxford":{"phon":"bɪˈhɑːf","pos":"noun","senses":[{"en":"( US ) in order to help sb","cn":"为帮助某人"},{"en":"as the representative of sb or instead of them","cn":"代表（或代替）某人"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"代表（亦使用 in someone's behalf，主要用于美国英语中）","en":"If you do something on someone's behalf, you do it for that person as their representative. The form in someone's behalf is also used, mainly in American English.","ex":{"en":"She made an emotional public appeal on her son's behalf","cn":"她代表儿子动情地发出了公开呼吁。"}},{"pos":"PHRASE 短语","cn":"为（某人）；替（某人）","en":"If you feel, for example, embarrassed or angry on someone's behalf, you feel embarrassed or angry for them.","ex":{"en":"'What do you mean?' I asked, offended on Liddie's behalf.","cn":"“你什么意思啊？”我问，替利迪感到愤愤不平。"}}]},"media":{"uk":"media/uk/behalf__gb_1.mp3","us":"media/us/behalf__us_1.mp3"},"examples":[{"en":"Mr Knight cannot be here, so his wife will accept the prize on his behalf.","cn":"奈特先生不能来，因此由他的夫人代他领奖。"},{"en":"We collected money in behalf of the homeless.","cn":"我们为帮助无家可归者而募捐。"}]},"beams":{"lemma":"beam"},"been":{"lemma":"be","media":{"uk":"media/uk/been__gb_1.mp3","us":"media/us/been__us_1.mp3"}},"beak":{"oxford":{"phon":"biːk","pos":"noun","senses":[{"en":"the hard pointed or curved outer part of a bird’s mouth","cn":"鸟喙","ex":{"en":"The gull held the fish in its beak.","cn":"海鸥嘴里叼着鱼。"}},{"en":"a person’s nose, especially when it is large and/or pointed","cn":"鹰钩鼻；尖鼻；鼻子","lab":"humorous"},{"en":"a person in a position of authority, especially a judge","cn":"掌权者；（尤指）法官","lab":"British English, old-fashioned, slang，，，，"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鸟喙；鸟嘴","en":"A bird's beak is the hard curved or pointed part of its mouth.","ex":{"en":"...a black bird with a yellow beak.","cn":"一只黄喙黑鸟"}}]},"media":{"uk":"media/uk/beak__gb_1.mp3","us":"media/us/beak__us_1.mp3"},"examples":[{"en":"The gull held the fish in its beak.","cn":"海鸥嘴里叼着鱼。"}]},"believe":{"media":{"uk":"media/uk/believe__gb_1.mp3","us":"media/us/believe__us_1.mp3"},"oxford":{"phon":"bɪˈliːv","pos":"verb","senses":[{"en":"to feel certain that something is true or that somebody is telling you the truth","cn":"相信；认为真实","g":"[transitive]","sc":"feel certain","ex":{"en":"I don't believe you!","cn":"我不相信你的话！"}},{"en":"to think that something is true or possible, although you are not completely certain","cn":"把（某事）当真；认为有可能","g":"[intransitive, transitive]","sc":"think possible","ex":{"en":"‘Where does she come from?’ ‘Spain, I believe.’","cn":"“她是哪里人？”“我想是西班牙人。”"}},{"en":"to have the opinion that something is right or true","cn":"认定；看作","g":"[transitive]","sc":"have opinion","ex":{"en":"The party believes (that) education is the most important issue facing the government.","cn":"该党把教育视为政府面临的最重要的问题。"}},{"en":"used to say that you are surprised or annoyed at something","cn":"（表示对某事吃惊或恼怒）","g":"[transitive]","sc":"be surprised/annoyed","ex":{"en":"She couldn’t believe (that) it was all happening again.","cn":"她简直无法相信整件事又在重演。"}},{"en":"to have a religious faith","cn":"有宗教信仰","g":"[intransitive]","sc":"religion","ex":{"en":"The god appears only to those who believe.","cn":"信神则神在。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"相信；认为","en":"If you believe that something is true, you think that it is true, but you are not sure.","ex":{"en":"Experts believe that the coming drought will be extensive","cn":"专家们认为即将发生的旱灾将侵袭大片地区。"}},{"pos":"VERB 动词","cn":"相信（某人或某人的话）","en":"If you believe someone or if you believe what they say or write, you accept that they are telling the truth.","ex":{"en":"He did not sound as if he believed her","cn":"他听起来似乎并不相信她。"}},{"pos":"VERB 动词","cn":"相信有…；认为…存在","en":"If you believe in fairies, ghosts, or miracles, you are sure that they exist or happen. If you believe in a god, you are sure of the existence of that god.","ex":{"en":"I don't believe in ghosts","cn":"我不相信有鬼。"}},{"pos":"VERB 动词","cn":"认为…是应该的（或正确的）","en":"If you believe in a way of life or an idea, you are in favour of it because you think it is good or right.","ex":{"en":"He believed in marital fidelity.","cn":"他认为婚内应该忠诚。"}},{"pos":"VERB 动词","cn":"对…有信心；信任；信赖","en":"If you believe in someone or what they are doing, you have confidence in them and think that they will be successful.","ex":{"en":"If you believe in yourself you can succeed.","cn":"只要自信，就能成功。"}},{"pos":"VERB 动词","cn":"（表示惊奇）难以置信","en":"Believe is used in expressions such as I can't believe how or it's hard to believe that in order to express surprise, for example because something bad has happened or something very difficult has been achieved.","ex":{"en":"Many officers I spoke to found it hard to believe what was happening around them","cn":"很多和我谈过的官员都觉得发生在他们周围的事情令人难以置信。"}},{"pos":"PHRASE 短语","cn":"（表示对所见所闻惊讶不已）相信自己的眼睛/耳朵","en":"If you say that you cannot believe your eyes or cannot believe your ears, you are emphasizing that you are very surprised about something you have seen or heard.","ex":{"en":"I could not believe my eyes. She was far more beautiful than I had imagined.","cn":"我简直不敢相信自己的眼睛。她比我想象的漂亮多了。"}},{"pos":"PHRASE 短语","cn":"（强调刚才所述之事令人吃惊）信不信由你","en":"You can use believe it or not to emphasize that what you have just said is surprising.","ex":{"en":"That's normal, believe it or not.","cn":"那很正常，信不信由你。"}},{"pos":"PHRASE 短语","cn":"（强调对某事感到惊讶）你会相信吗？","en":"If you say would you believe it, you are emphasizing your surprise about something.","ex":{"en":"And would you believe it, he's younger than me!","cn":"你信吗？他比我年轻！"}},{"pos":"PHRASE 短语","cn":"（强调所述属实）相信我","en":"You can use believe you me to emphasize that what you are saying is true.","ex":{"en":"It's absolutely amazing, believe you me.","cn":"这太不可思议了，真的。"}}]},"examples":[{"en":"The man claimed to be a social worker and the old woman believed him.","cn":"那个男人自称是社会福利工作者，老妇人信以为真。"},{"en":"‘Does he still work there?’ ‘I believe so/not. ’ “","cn":"他还在那里工作吗？” “我想是/不是。”"}]},"beans":{"lemma":"bean"},"betrayal":{"oxford":{"phon":"bɪˈtreɪəl","pos":"noun","senses":[{"en":"the act of betraying somebody/something or the fact of being betrayed","cn":"（被）背叛，出卖","ex":{"en":"a sense/a feeling/an act of betrayal","cn":"被出卖的感觉；背叛行为"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"辜负；背叛；出卖","en":"A betrayal is an action which betrays someone or something, or the fact of being betrayed.","ex":{"en":"She felt that what she had done was a betrayal of Patrick","cn":"她觉得自己的所作所为是对帕特里克的背叛。"}}]},"media":{"uk":"media/uk/betrayal__gb_1.mp3","us":"media/us/betrayal__us_1.mp3"},"examples":[{"en":"I saw her actions as a betrayal of my trust.","cn":"我认为她的所作所为辜负了我的信任。"},{"en":"the many disappointments and betrayals in his life","cn":"他一生中遭受的诸多失望与背叛"}]},"beef":{"media":{"uk":"media/uk/beef__gb_1.mp3","us":"media/us/beef__us_1.mp3"},"oxford":{"phon":"biːf","pos":"noun","senses":[{"en":"meat that comes from a cow","cn":"牛肉","g":"[uncountable]","ex":{"en":"roast beef","cn":"烤牛肉"}},{"en":"a complaint","cn":"抱怨；牢骚","g":"[countable]","lab":"informal","ex":{"en":"What's his latest beef?","cn":"他最近在抱怨什么？"}},{"en":"to complain a lot about somebody/something","cn":"老是抱怨；大发牢骚","ex":{"en":"Don't just beef about it—do something!","cn":"不要只是抱怨——做点什么吧！"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"牛肉","en":"Beef is the meat of a cow, bull, or ox.","ex":{"en":"...roast beef.","cn":"烤牛肉"}},{"pos":"VERB 动词","cn":"不断抱怨；大发牢骚","en":"If someone beefs about something, they keep complaining about it.","ex":{"en":"Instead of beefing about what Mrs Martin has not done, her critics might take a look at what she is trying to do.","cn":"批评者不要老是抱怨马丁太太没有做什么事情，不妨看看她正要做什么事情。"}},{"pos":"","cn":"","en":"相关词组：beef up"}]},"examples":[{"en":"What's his latest beef?","cn":"他最近在抱怨什么？"},{"en":"roast/minced beef","cn":"烤牛肉；碎牛肉"}]},"belt":{"media":{"img":["media/ldoce/img/belt.jpg","media/pic/shirt_hoodyclothes_comp.jpg"],"uk":"media/uk/belt__gb_1.mp3","us":"media/us/belt__us_1.mp3"},"oxford":{"phon":"belt","pos":"noun","senses":[{"en":"a long narrow piece of leather, cloth, etc. that you wear around the middle part of your body","cn":"腰带；皮带","ex":{"en":"to do up/fasten/tighten a belt","cn":"系上／扎牢／扎紧腰带"}},{"en":"a continuous band of material that moves round and is used to carry things along or to drive a machine","cn":"传送带；传动带"},{"en":"a narrow area or an area around the edge of something that has particular characteristics","cn":"狭长的地带；环形地带","ex":{"en":"the country’s corn/industrial belt","cn":"这个国家的产粮区／工业区"}},{"en":"an act of hitting something/somebody hard","cn":"狠打；猛击","lab":"informal","ex":{"en":"She gave the ball a terrific belt.","cn":"她猛击了一下球。"}},{"en":"to hit somebody/something hard","cn":"猛击；狠打","lab":"informal","ex":{"en":"He belted the ball right out of the park.","cn":"他用力一击，球径直飞出了球场外。"},"pos":"verb"},{"en":"to move very fast","cn":"疾驰；飞驰","g":"[intransitive]","lab":"informal, British English，，","ex":{"en":"A truck came belting up behind us.","cn":"一辆货车从我们后方飞驰而来。"},"pos":"verb"},{"en":"to fasten a belt around something","cn":"用带子系住","g":"[transitive]","ex":{"en":"The dress was belted at the waist.","cn":"那件连衣裙的裙腰束着条带子。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"腰带；裤带；皮带","en":"A belt is a strip of leather or cloth that you fasten round your waist.","ex":{"en":"He wore a belt with a large brass buckle.","cn":"他系着一条带大铜扣的腰带。"}},{"pos":"N-COUNT 可数名词","cn":"（机器的）皮带，输送带","en":"A belt in a machine is a circular strip of rubber that is used to drive moving parts or to move objects along.","ex":{"en":"The turning disc is connected by a drive belt to an electric motor.","cn":"转盘由一根传动带与电机相连。"}},{"pos":"N-COUNT 可数名词","cn":"地带；带状区域","en":"A belt of land or sea is a long, narrow area of it that has some special feature.","ex":{"en":"Miners in Zambia's northern copper belt have gone on strike","cn":"赞比亚北部铜矿带的矿工已经罢工了。"}},{"pos":"VERB 动词","cn":"抽打；痛打","en":"If someone belts you, they hit you very hard.","ex":{"en":"'Is it right she belted old George in the gut?' she asked.","cn":"“她真的把老乔治痛打了一顿？”她问。"}},{"pos":"VERB 动词","cn":"飞奔；疾驰","en":"If you belt somewhere, you move or travel there very fast.","ex":{"en":"We belted down Iveagh Parade to where the motor was.","cn":"我们沿着艾维格大街一路飞奔到汽车那儿。"}},{"pos":"N-COUNT 可数名词","cn":"（表示柔道或空手道级别的）段，带","en":"If someone is or has a belt of a particular colour in judo or karate, they have reached the standard which that colour represents.","ex":{"en":"He is a black belt in karate.","cn":"他是空手道黑带选手。"}},{"pos":"PHRASE 短语","cn":"残酷而不公正的","en":"Something that is below the belt is cruel and unfair.","ex":{"en":"Do you think it's a bit below the belt what they're doing?","cn":"你觉得他们的做法是不是有点儿不太光明正大？"}},{"pos":"PHRASE 短语","cn":"勒紧裤腰带；紧缩开支；节衣缩食","en":"If you have to tighten your belt, you have to spend less money and manage without things because you have less money than you used to have.","ex":{"en":"Clearly, if you are spending more than your income, you'll need to tighten your belt.","cn":"明摆着，要是你入不敷出，你就得省着点了。"}},{"pos":"PHRASE 短语","cn":"已经取得（或完成）","en":"If you have something under your belt, you have already achieved it or done it.","ex":{"en":"Clare is now a full-time author with six books, including four novels, under her belt.","cn":"克莱尔现在是全职作家，著有6本书，其中有4部小说。"}},{"pos":"","cn":"","en":"相关词组：belt out belt up"}]},"examples":[{"en":"He belted the ball right out of the park.","cn":"他用力一击，球径直飞出了球场外。"},{"en":"A truck came belting up behind us.","cn":"一辆货车从我们后方飞驰而来。"}]},"bedtime":{"media":{"uk":"media/uk/bedtime__gb_1.mp3","us":"media/us/bedtime__us_1.mp3"},"oxford":{"phon":"ˈbedtaɪm","pos":"noun","senses":[{"en":"the time when somebody usually goes to bed","cn":"就寝时间","ex":{"en":"It's way past your bedtime.","cn":"你早该睡觉了。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"就寝时间","en":"Your bedtime is the time when you usually go to bed.","ex":{"en":"It was eight-thirty, Trevor's bedtime.","cn":"八点半了，特雷弗该上床睡觉了。"}}]},"examples":[{"en":"Will you read me a bedtime story?","cn":"给我读个睡前故事好吗？"},{"en":"It's way past your bedtime.","cn":"你早该睡觉了。"}]},"begun":{"lemma":"begin","media":{"uk":"media/uk/begun__gb_1.mp3","us":"media/us/begun__us_1.mp3"}},"beanie":{"media":{"img":["media/pic/hats_comp.jpg","media/thumb/beanie.jpg"],"uk":"media/uk/beanie__gb_1.mp3","us":"media/us/beanie__us_1.mp3"},"oxford":{"phon":"ˈbiːni","pos":"noun","senses":[{"en":"a small, round close-fitting hat","cn":"无檐小便帽","ex":{"en":"If you’re after a simple, stylish beanie to keep you warm this winter, then this is the one for you.","cn":"如果您想要一顶简单时尚的无檐小便帽来为您在这个冬天保暖，那么这款帽子就是您的最佳选择。"}}]}},"bearing":{"media":{"uk":"media/uk/bearing__gb_1.mp3","us":"media/us/bearing__us_1.mp3"},"oxford":{"phon":"ˈbeərɪŋ","pos":"noun","senses":[{"en":"the way in which something is related to something or influences it","cn":"关系；影响","g":"[uncountable, singular]","ex":{"en":"Recent events had no bearing on our decision.","cn":"近期的事件与我们的决定没有关系。"}},{"en":"the way in which you stand, walk or behave","cn":"姿态；举止","g":"[singular]","ex":{"en":"Her whole bearing was alert.","cn":"她整个人保持着戒备状态。"}},{"en":"a direction measured from a fixed point using a compass","cn":"（用罗盘测定的）方位","g":"[countable]","lab":"specialist","ex":{"en":"They took compass bearings on the tower.","cn":"他们用罗盘测定塔的方位。"}},{"en":"knowledge of your position relative to everything that is around or near you","cn":"方位感；方向感","g":"[plural]","lab":"figurative","ex":{"en":"to get/find/take your bearings","cn":"确定你所处的方位"}},{"en":"a part of a machine that supports a moving part, especially one that is turning","cn":"（机器的）支座；（尤指）轴承","g":"[countable]","lab":"specialist"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"与…有关；对…有影响","en":"If something has a bearing on a situation or event, it is relevant to it.","ex":{"en":"Experts generally agree that diet has an important bearing on your general health","cn":"专家们普遍认为饮食和健康总体状况密切相关。"}},{"pos":"N-SING 单数名词","cn":"举止；仪态","en":"Someone's bearing is the way in which they move or stand.","ex":{"en":"She later wrote warmly of his bearing and behaviour.","cn":"后来她以饱含热情的笔触写到了他的举止和行为。"}},{"pos":"N-COUNT 可数名词","cn":"（罗盘显示的）方位","en":"If you take a bearing with a compass, you use it to work out the direction in which a particular place lies or in which something is moving."},{"pos":"PHRASE 短语","cn":"清楚/不清楚所在方位；知道/不知道下一步怎么做","en":"If you get your bearings or find your bearings, you find out where you are or what you should do next. If you lose your bearings, you do not know where you are or what you should do next.","ex":{"en":"A sightseeing tour of the city is included to help you get your bearings","cn":"市区观光游也包含在内，帮助你熟悉一下这里的情况。"}},{"pos":"N-COUNT 可数名词","cn":"轴承","en":"Bearings are small metal balls that are placed between moving parts of a machine in order to make them move smoothly and easily over each other.","ex":{"en":"An oil seal was replaced, along with both front wheel bearings.","cn":"换了一个油封和两个前轮轴承。"}}]},"examples":[{"en":"Regular exercise has a direct bearing on fitness and health.","cn":"经常性锻炼对于身体健康有直接影响。"},{"en":"Recent events had no bearing on our decision.","cn":"近期的事件与我们的决定没有关系。"}],"base":"bear"},"behind":{"media":{"uk":"media/uk/behind__gb_1.mp3","us":"media/us/behind__us_1.mp3"},"oxford":{"phon":"bɪˈhaɪnd","pos":"preposition","senses":[{"en":"at or towards the back of somebody/something, and often hidden by it or them","cn":"在（或向）…的后面；在（或向）…的背面","ex":{"en":"Who's the girl standing behind Jan?","cn":"站在简身后的女孩是谁？"}},{"en":"making less progress than somebody/something","cn":"落后于","ex":{"en":"He's behind the rest of the class in reading.","cn":"他的阅读能力不及班上其他人。"}},{"en":"giving support to or approval of somebody/something","cn":"支持；赞成","ex":{"en":"She knew that, whatever she decided, her family was right behind her.","cn":"她知道，无论她作出什么决定，她的家人肯定会支持她的。"}},{"en":"responsible for starting or developing something","cn":"是…产生（或发展）的原因","ex":{"en":"What's behind that happy smile (= what is causing it)?","cn":"为什么会笑得那么开心？"}},{"en":"used to say that something is in somebody’s past","cn":"成为（某人的）过去","ex":{"en":"The accident is behind you now, so try to forget it.","cn":"这次意外已经过去了，把它忘掉吧。"}},{"en":"at or towards the back of somebody/something; further back","cn":"在（或向）后面；在后面较远处","ex":{"en":"She rode off down the road with the dog running behind.","cn":"她骑车沿路而去，狗跟在后面奔跑着。"},"pos":"adverb"},{"en":"in the place where somebody/something is or was","cn":"留在原地","ex":{"en":"I was told to stay behind after school (= remain in school).","cn":"我被告知放学后留下。"},"pos":"adverb"},{"en":"late in paying money or completing work","cn":"拖欠；积压（工作）","ex":{"en":"She's fallen behind with the payments.","cn":"她尚未付款。"},"pos":"adverb"},{"en":"a person’s bottom. People often say ‘behind’ to avoid saying ‘bottom’.","cn":"腚（义同 bottom，委婉说法）","ex":{"en":"The dog bit him on his behind.","cn":"狗咬了他的腚。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…后面","en":"If something is behind a thing or person, it is on the other side of them from you, or nearer their back rather than their front.","ex":{"en":"I put one of the cushions behind his head","cn":"我把其中的一个软垫垫在他脑后。"}},{"pos":"PREP 介词","cn":"跟在…后面","en":"If you are walking or travelling behind someone or something, you are following them.","ex":{"en":"Keith wandered along behind him","cn":"基思跟在他后面闲逛。"}},{"pos":"PREP 介词","cn":"在（桌子、柜台、吧台等）的后面","en":"If someone is behind a desk, counter, or bar, they are on the other side of it from where you are.","ex":{"en":"The colonel was sitting behind a cheap wooden desk","cn":"上校坐在一张廉价的木桌后面。"}},{"pos":"PREP 介词","cn":"在…身后（随手关上门）","en":"When you shut a door or gate behind you, you shut it after you have gone through it.","ex":{"en":"I walked out and closed the door behind me","cn":"我走了出来，随手带上了门。"}},{"pos":"PREP 介词","cn":"在（某一局势）背后（或幕后）","en":"The people, reason, or events behind a situation are the causes of it or are responsible for it.","ex":{"en":"It is still not clear who was behind the killing","cn":"凶杀案的幕后主使尚不清楚。"}},{"pos":"PREP 介词","cn":"支持；作为…的后盾","en":"If something or someone is behind you, they support you and help you.","ex":{"en":"He had the state's judicial power behind him.","cn":"他有国家司法权作后盾。"}},{"pos":"PREP 介词","cn":"在（…的外表）之下","en":"If you refer to what is behind someone's outside appearance, you are referring to a characteristic which you cannot immediately see or is not obvious, but which you think is there.","ex":{"en":"What lay behind his anger was really the hurt he felt at Grace's refusal","cn":"他生气的表面之下是因遭格雷斯拒绝而深受伤害的心。"}},{"pos":"PREP 介词","cn":"不及；比不上；落后于","en":"If you are behind someone, you are less successful than them, or have done less or advanced less.","ex":{"en":"She finished second behind the American, Ann Cody, in the 800 metres","cn":"她在800米赛跑中落后于美国选手安·科迪而位居第二。"}},{"pos":"PREP 介词","cn":"对…来说成为过去；抛到…的脑后","en":"If an experience is behind you, it happened in your past and will not happen again, or no longer affects you.","ex":{"en":"Maureen put the nightmare behind her","cn":"莫琳已将噩梦抛诸脑后。"}},{"pos":"PREP 介词","cn":"有（某种成就）","en":"If you have a particular achievement behind you, you have managed to reach this achievement, and other people consider it to be important or valuable.","ex":{"en":"He has 20 years of loyal service to Barclays Bank behind him","cn":"他已经忠心耿耿地为巴克莱银行效力了20年。"}},{"pos":"PREP 介词","cn":"落后于；迟于；晚于","en":"If something is behind schedule, it is not as far advanced as people had planned. If someone is behind schedule, they are not progressing as quickly at something as they had planned.","ex":{"en":"The work is 22 weeks behind schedule","cn":"这项工作比计划滞后了22周。"}},{"pos":"ADV 副词","cn":"留在原处；留下来","en":"If you stay behind, you remain in a place after other people have gone.","ex":{"en":"As women were not permitted in the war zone, Eleanor would have to stay behind","cn":"女性是不允许进入战区的，所以埃莉诺不得不留在后方。"}},{"pos":"ADV 副词","cn":"丢下；抛下","en":"If you leave something or someone behind, you do not take them with you when you go.","ex":{"en":"The rebels fled into the mountains, leaving behind their weapons and supplies","cn":"叛军丢下武器和给养，逃进了山里。"}},{"pos":"","cn":"","en":"to do something behind someone's back→see: ; behind bars→see: ; →see: ; →see: ; behind the times→see: ;"},{"pos":"N-COUNT 可数名词","cn":"臀部；屁股","en":"Your behind is the part of your body that you sit on."}]},"examples":[{"en":"She knew that, whatever she decided, her family was right behind her.","cn":"她知道，无论她做出什么决定，她的家人肯定会支持她的。"},{"en":"I had fallen so far behind that it seemed pointless trying to catch up.","cn":"我落后太多，似乎追赶下去也毫无意义。"}]},"beautifully":{"media":{"uk":"media/uk/beautifully__gb_1.mp3","us":"media/us/beautifully__us_1.mp3"},"oxford":{"phon":"ˈbjuːtɪfli","pos":"adverb","senses":[{"en":"in a beautiful way","cn":"美好地；美妙地；漂亮地","ex":{"en":"She sings beautifully.","cn":"她唱歌很动听。"}},{"en":"very well; in a way that pleases you","cn":"很好；令人满意地","ex":{"en":"It's all working out beautifully.","cn":"一切进展都很顺利。"}}]},"examples":[{"en":"It's all working out beautifully.","cn":"一切进展都很顺利。"},{"en":"She sings beautifully.","cn":"她唱歌很动听。"}]},"because":{"media":{"uk":"media/uk/because__gb_1.mp3","us":"media/us/because__us_1.mp3"},"oxford":{"phon":"bɪˈkəz","pos":"conjunction","senses":[{"en":"for the reason that","cn":"因为","ex":{"en":"I did it because he told me to.","cn":"是他吩咐我才做的。"}}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"（说明原因）因为，由于","en":"You use because when stating the reason for something.","ex":{"en":"He is called Mitch, because his name is Mitchell","cn":"人们叫他米奇，因为他大名叫米切尔。"}},{"pos":"CONJ-SUBORD 连词","cn":"（作出解释）因为","en":"You use because when stating the explanation for a statement you have just made.","ex":{"en":"Maybe they just didn't want to ask too many questions, because they rented us a room without even asking to see our papers","cn":"也许他们只是懒得问太多的问题，因为他们都没要求看我们的证件就把一个房间租给我们了。"}},{"pos":"PREP-PHRASE 短语介词","cn":"因为；由于","en":"If an event or situation occurs because of something, that thing is the reason or cause.","ex":{"en":"Many families break up because of a lack of money","cn":"许多家庭由于缺钱而破裂。"}},{"pos":"PHR-CONJ-SUBORD","cn":"仅仅因为","en":"You use just because when you want to say that a particular situation should not necessarily make you come to a particular conclusion.","ex":{"en":"Just because it has a good tune does not mean it is great music","cn":"仅凭旋律优美并不见得就是一首杰出的音乐作品。"}}]},"examples":[{"en":"Just because I don't complain, people think I'm satisfied.","cn":"就因为我不发牢骚，大家便以为我满意了。"},{"en":"Because of his wife('s) being there, I said nothing about it.","cn":"他的妻子在场，我便没提及这事。"}]},"below":{"media":{"uk":"media/uk/below__gb_1.mp3","us":"media/us/below__us_1.mp3"},"oxford":{"phon":"bɪˈləʊ","pos":"adverb","senses":[{"en":"at or to a lower level, position or place","cn":"在（或到）下面","ex":{"en":"They live on the floor below.","cn":"他们住在下一层楼。"}},{"en":"at a lower rank","cn":"下级","ex":{"en":"This ruling applies to the ranks of Inspector and below.","cn":"这项规定适用于巡官及以下人员。"}},{"en":"lower than zero","cn":"零度以下","ex":{"en":"The thermometer had dropped to a record 40 below (= −40 degrees).","cn":"温度计降到了零下 40 度的纪录。"}},{"en":"at or to a lower level or position than somebody/something","cn":"在（或到）…下面","ex":{"en":"He dived below the surface of the water.","cn":"他潜入了水中。"},"pos":"preposition"},{"en":"of a lower amount or standard than somebody/something","cn":"（数量）少于；（标准）低于","ex":{"en":"The temperatures remained below freezing all day.","cn":"气温一整天都保持在冰点以下。"},"pos":"preposition"},{"en":"of a lower rank or of less importance than somebody/something","cn":"（级别、重要性）低于","ex":{"en":"A police sergeant is below an inspector.","cn":"巡佐的级别低于巡官。"},"pos":"preposition"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"（位置）在…下面，低于","en":"If something is below something else, it is in a lower position.","ex":{"en":"He appeared from the apartment directly below Leonard's","cn":"他从伦纳德家正下方的公寓里走了出来。"}},{"pos":"PHRASE 短语","cn":"在地下；在地表以下","en":"If something is below ground or below the ground, it is in the ground.","ex":{"en":"They have designed a system which pumps up water from 70m below ground","cn":"他们设计了一套从地下70米处抽水的系统。"}},{"pos":"ADV 副词","cn":"以下；在下文中","en":"You use below in a piece of writing to refer to something that is mentioned later.","ex":{"en":"Please write to me at the address below","cn":"请按照下面的地址给我写信。"}},{"pos":"PREP 介词","cn":"（数量、比率或水平）低于，小于，少于","en":"If something is below a particular amount, rate, or level, it is less than that amount, rate, or level.","ex":{"en":"Night temperatures can drop below 15 degrees Celsius","cn":"夜间气温会降到15摄氏度以下。"}},{"pos":"PREP 介词","cn":"（职位、官衔等）低于","en":"If someone is below you in an organization, they are lower in rank.","ex":{"en":"Such people often experience less stress than those in the ranks immediately below them.","cn":"这些人承受的压力往往小于那些职位仅次于他们的人。"}},{"pos":"","cn":"","en":"below par→see: ;"}]},"examples":[{"en":"The thermometer had dropped to a record 40 below (= −40 degrees).","cn":"温度计降到了零下 40 度的纪录。"},{"en":"Her work was well below average for the class.","cn":"她的功课远在班上的中等水平以下。"}]},"bend":{"media":{"uk":"media/uk/bend__gb_1.mp3","us":"media/us/bend__us_1.mp3"},"oxford":{"phon":"bend","pos":"verb","senses":[{"en":"to lean, or make something lean, in a particular direction","cn":"（使）倾斜，偏向","g":"[intransitive, transitive]","ex":{"en":"He bent and kissed her.","cn":"他低下头吻了她。"}},{"en":"if you bend your arm, leg, etc. or if it bends, you move it so that it is no longer straight","cn":"（使四肢等）弯曲","g":"[transitive, intransitive]","ex":{"en":"Bend your knees, keeping your back straight.","cn":"膝盖弯曲，背部挺直。"}},{"en":"to force something that was straight into an angle or a curve","cn":"把…弄弯（或折起）","g":"[transitive]","ex":{"en":"Mark the pipe where you want to bend it.","cn":"在管子上把要弄弯的地方做个记号。"}},{"en":"to change direction to form a curve or an angle; to make something change direction in this way","cn":"（使）拐弯，弯曲","g":"[intransitive, transitive]","ex":{"en":"The road bent sharply to the right.","cn":"路向右急拐。"}},{"en":"a curve or turn, especially in a road or river","cn":"（尤指道路或河流的）拐弯，弯道","g":"[countable]","ex":{"en":"a sharp bend in the road","cn":"公路上的急转弯"},"pos":"noun"},{"en":"severe pain and difficulty in breathing experienced by a diver who comes back to the surface of the water too quickly","cn":"（潜水员过快浮出水面造成的）减压病","g":"[plural]","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"弯腰；俯身；弯曲","en":"When you bend, you move the top part of your body downwards and forwards. Plants and trees also bend .","ex":{"en":"I bent over and kissed her cheek","cn":"我俯身亲吻了她的脸颊。"}},{"pos":"VERB 动词","cn":"低（头）；俯（首）","en":"When you bend your head, you move your head forwards and downwards.","ex":{"en":"Rick appeared, bending his head a little to clear the top of the door.","cn":"里克到了，进门时为了避开门楣稍微低了下头。"}},{"pos":"V-ERG 及物/不及物动词","cn":"弯曲（手臂、腿等）；（手臂、腿等）弯曲","en":"When you bend a part of your body such as your arm or leg, or when it bends, you change its position so that it is no longer straight.","ex":{"en":"These cruel devices are designed to stop prisoners bending their legs","cn":"这些残酷的刑具是用来阻止犯人弯腿的。"}},{"pos":"VERB 动词","cn":"使弯曲；使变弯","en":"If you bend something that is flat or straight, you use force to make it curved or to put an angle in it.","ex":{"en":"Bend the bar into a horseshoe","cn":"把铁条弯成马蹄形。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（路、光束等）弯曲","en":"When a road, beam of light, or other long thin thing bends, or when something bends it, it changes direction to form a curve or angle.","ex":{"en":"The road bent slightly to the right","cn":"这条路稍微朝右弯。"}},{"pos":"N-COUNT 可数名词","cn":"（路、管道等的）弯曲处，转弯处","en":"A bend in a road, pipe, or other long thin object is a curve or angle in it.","ex":{"en":"The crash occurred on a sharp bend.","cn":"撞车发生在一个急转弯处。"}},{"pos":"VERB 动词","cn":"屈从；不情愿地服从","en":"If someone bends to your wishes, they believe or do something different, usually when they do not want to.","ex":{"en":"Congress has to bend to his will","cn":"国会不得不屈从于他的意志。"}},{"pos":"VERB 动词","cn":"曲解，通融，篡改（规则、法律等）","en":"If you bend rules or laws, you interpret them in a way that allows you to do something they would not normally allow you to do.","ex":{"en":"A minority of officers were prepared to bend the rules.","cn":"少数官员准备篡改规则。"}},{"pos":"VERB 动词","cn":"歪曲（事实）","en":"If you bend the truth or bend the facts, you say something that is not exactly true.","ex":{"en":"Sometimes we bend the truth a little in order to spare them the pain of the real facts.","cn":"有时我们会稍微变动一下事实，以免他们知道实情会太痛苦。"}},{"pos":"PHRASE 短语","cn":"竭尽全力","en":"If you say that someone is bending over backwards to be helpful or kind, you are emphasizing that they are trying very hard to be helpful or kind.","ex":{"en":"People are bending over backwards to please customers.","cn":"人们正使出浑身解数取悦顾客。"}},{"pos":"PHRASE 短语","cn":"使非常恼火；使极为恼怒","en":"If you say that someone or something drives you round the bend, you mean that you dislike them and they annoy or upset you very much.","ex":{"en":"And can you make that tea before your fidgeting drives me completely round the bend.","cn":"你能不能把那壶茶泡好？瞧你坐立不安的样子，真要把我惹急了。"}},{"pos":"PHRASE 短语","cn":"做蠢事；干傻事；发疯","en":"If you say that someone is round the bend, you mean that they do foolish or silly things.","ex":{"en":"People thought I was round the bend.","cn":"人们以为我疯了。"}},{"pos":"","cn":"","en":"to bend someone's ear→see: ;"}]},"examples":[{"en":"He manipulates people and tries to bend them to his will (= make them do what he wants).","cn":"他能左右民众，让大家跟随他的意志。"},{"en":"Mark the pipe where you want to bend it.","cn":"在管子上把要弄弯的地方做个记号。"}]},"begin":{"media":{"uk":"media/uk/begin__gb_1.mp3","us":"media/us/begin__us_1.mp3"},"oxford":{"phon":"bɪˈɡɪn","pos":"verb","senses":[{"en":"to start doing something; to do the first part of something","cn":"开始；启动","g":"[intransitive, transitive]","ex":{"en":"Shall I begin?","cn":"我可以开始了吗？"}},{"en":"to start to happen or exist, especially from a particular time","cn":"起始；开始存在（或进行）","g":"[intransitive]","ex":{"en":"When does the concert begin?","cn":"音乐会什么时间开始？"}},{"en":"to have something as the first part or the point where something starts","cn":"（从…）开始；（以…）为起点","g":"[intransitive]","ex":{"en":"Where does Europe end and Asia begin?","cn":"欧洲和亚洲的交界处在哪里？"}},{"en":"to start or make something start for the first time","cn":"创始；创办","g":"[intransitive, transitive]","ex":{"en":"The school began in 1920, with only ten pupils.","cn":"这所学校创建于 1920 年，当时只有十名学生。"}},{"en":"to be something first, before becoming something else","cn":"起初是；本来是","g":"[intransitive]","ex":{"en":"He began as an actor, before starting to direct films.","cn":"他先是当演员，后来开始执导影片。"}},{"en":"to start speaking","cn":"开始讲话","g":"[transitive]","ex":{"en":"‘Ladies and gentlemen,’ he began, ‘welcome to the Town Hall.’","cn":"他开始讲话：“女士们、先生们，欢迎光临市政厅。”"}},{"en":"to make no attempt to do something or have no chance of doing something","cn":"不想；绝不能","g":"[transitive]","ex":{"en":"I can't begin to thank you enough.","cn":"我说不尽对你的感激。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"开始；着手","en":"To begin to do something means to start doing it.","ex":{"en":"He stood up and began to move around the room","cn":"他起身开始在屋里来回走动。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）开始（进行或存在）","en":"When something begins or when you begin it, it takes place from a particular time onwards.","ex":{"en":"The problems began last November","cn":"问题在去年11月份开始出现。"}},{"pos":"VERB 动词","cn":"从…开始；从…着手；首先做（某事）","en":"If you begin with something, or begin by doing something, this is the first thing you do.","ex":{"en":"Could I begin with a few formalities?","cn":"请允许我开场先讲几句套话。"}},{"pos":"VERB 动词","cn":"开始说；开口说","en":"You use begin to mention the first thing that someone says.","ex":{"en":"'Professor Theron,' he began, 'I'm very pleased to see you'","cn":"“西伦教授，”他开口说道，“很高兴见到您。”"}},{"pos":"VERB 动词","cn":"起初是；开始是","en":"If one thing began as another, it first existed in the form of the second thing.","ex":{"en":"What began as a local festival has blossomed into an international event.","cn":"原先的地方节日已经发展成为一项国际性活动。"}},{"pos":"VERB 动词","cn":"（界限或边缘）起始于","en":"If you say that a thing or place begins somewhere, you are talking about one of its limits or edges.","ex":{"en":"The fate line begins close to the wrist","cn":"命运线始于接近手腕的地方。"}},{"pos":"VERB 动词","cn":"以…开头；首字母为","en":"If a word begins with a particular letter, that is the first letter of that word.","ex":{"en":"The first word begins with an F.","cn":"第一个词的首字母为F。"}},{"pos":"VERB 动词","cn":"无法，难以（解释、理解、想象等）","en":"If you say that you cannot begin to imagine, understand, or explain something, you are emphasizing that it is almost impossible to explain, understand, or imagine.","ex":{"en":"You can't begin to imagine how much that saddens me.","cn":"你都无从想象这让我有多悲伤。"}},{"pos":"PHRASE 短语","cn":"最初；刚开始","en":"You use to begin with when you are talking about the first stage of a situation, event, or process.","ex":{"en":"It was great to begin with but now it's difficult.","cn":"一开始非常好，但现在可就难了。"}},{"pos":"PHRASE 短语","cn":"首先；第一","en":"You use to begin with to introduce the first of several things that you want to say.","ex":{"en":"'What do scientists you've spoken with think about that?' — 'Well, to begin with, they doubt it's going to work.'","cn":"“跟你聊过的科学家是怎么看的？”——“嗯，首先，他们怀疑这能否行得通。”"}},{"pos":"","cn":"","en":"charity begins at home→see: ; begin life→see: ;"}]},"examples":[{"en":"‘What was it you didn't like?’ ‘Well, to begin with, our room was far too small.’ “","cn":"你不喜欢的是什么呢？” “唔，首先是，我们的屋子太小了。”"},{"en":"‘Ladies and gentlemen,’ he began, ‘welcome to the Town Hall.’","cn":"他开始讲话：“女士们、先生们，欢迎光临市政厅。”"}]},"better":{"media":{"uk":"media/uk/better__gb_1.mp3","us":"media/us/better__us_1.mp3"},"oxford":{"phon":"ˈbetə(r)","pos":"adjective","senses":[{"en":"of a higher standard or less poor quality; not as bad as something else","cn":"较好的；更好的","ex":{"en":"We're hoping for better weather tomorrow.","cn":"我们希望明天天气转好。"}},{"en":"more suitable or appropriate","cn":"更合适的；更恰当的","ex":{"en":"Can you think of a better word than ‘nice’?","cn":"你能找到一个比 nice 更合适的字眼吗？"}},{"en":"more able; showing more skill","cn":"能力更强的；更熟练的","ex":{"en":"She's far better at science than her brother.","cn":"她在理科方面比她的弟弟强得多。"}},{"en":"less ill or unhappy","cn":"（病势）好转的；舒服些的；舒坦些的","ex":{"en":"She's a lot better today.","cn":"她今天好多了。"}},{"en":"fully recovered after an illness; in good health again","cn":"痊愈；恢复健康","ex":{"en":"Don't go back to work until you are better.","cn":"身体康复之前，不要回去工作。"}},{"en":"in a more excellent or pleasant way; not as badly","cn":"更好；更愉快；不那么差","ex":{"en":"She sings much better than I do.","cn":"她唱歌比我好得多。"},"pos":"adverb"},{"en":"more; to a greater degree","cn":"更；较大程度地","ex":{"en":"You'll like her when you know her better.","cn":"你对她了解得多一点就会喜欢她。"},"pos":"adverb"},{"en":"used to suggest that something would be a suitable or appropriate thing to do","cn":"更妥；更恰当","ex":{"en":"The money could be better spent on more urgent cases.","cn":"这笔钱用于较紧迫的事情也许会好些。"},"pos":"adverb"},{"en":"something that is better","cn":"更好的事物；较好者","g":"[singular, uncountable]","ex":{"en":"the better of the two books","cn":"两本书中较好的一本"},"pos":"noun"},{"en":"people who are more intelligent or more important than you","cn":"更有才智者；更重要的人","g":"[plural]","lab":"old-fashioned","pos":"noun"},{"en":"to be better or do something better than somebody/something else","cn":"胜过；超过","g":"[often passive]","ex":{"en":"The work he produced early in his career has never really been bettered.","cn":"他后来没出过什么作品能真正比得上他的早期作品。"},"pos":"verb"},{"en":"to improve your social position through education, a better job, etc.","cn":"（通过教育、更好的工作等）改进社会地位，上进","ex":{"en":"Thousands of Victorian workers joined educational associations in an attempt to better themselves.","cn":"维多利亚时代成千上万名工人加入了各种教育协会，以求上进。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Better is the comparative of good ."},{"pos":"","cn":"","en":"Better is the comparative of well ."},{"pos":"ADV-COMPAR 副词比较级形式","cn":"更；更大程度上","en":"If you like one thing better than another, you like it more.","ex":{"en":"I like your interpretation better than the one I was taught","cn":"你的解释比我以前学过的更让我喜欢。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（病情、伤势）好转的，减轻的","en":"If you are better after an illness or injury, you have recovered from it. If you feel better, you no longer feel so ill.","ex":{"en":"He is much better now, he's fine","cn":"他现在好多了，身体状况不错。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（用于建议、警告、威胁、发表意见等）最好","en":"You use had better or 'd better when you are advising, warning, or threatening someone, or expressing an opinion about what should happen.","ex":{"en":"It's half past two. I think we had better go home","cn":"现在两点半了。我想我们最好还是回家吧。"}},{"pos":"PRON 代词","cn":"更大成就；更好行为；更好待遇","en":"If you say that you expect or deserve better, you mean that you expect or deserve a higher standard of achievement, behaviour, or treatment from people than they have shown you.","ex":{"en":"We expect better of you in the future","cn":"我们希望将来你有更大的成就。"}},{"pos":"N-PLURAL 复数名词","cn":"上司；上级","en":"Your betters are people who have a higher status or rank than you do.","ex":{"en":"Sit down and be quiet in front of your elders and betters.","cn":"在长辈和上级面前要老老实实地坐着。"}},{"pos":"VERB 动词","cn":"超越；胜过；超出","en":"If someone betters a high achievement or standard, they achieve something higher.","ex":{"en":"He recorded a time of 4 minutes 23, bettering the old record of 4-24","cn":"他用时4分23秒，刷新了4分24秒的原纪录。"}},{"pos":"VERB 动词","cn":"提高；改善","en":"If you better your situation, you improve your social status or the quality of your life. If you better yourself, you improve your social status.","ex":{"en":"He had dedicated his life to bettering the lot of the oppressed people of South Africa","cn":"他毕生致力于改变南非受压迫人民的命运。"}},{"pos":"","cn":"（用于构成以 good 和 well 开头的复合形容词的比较级，如 well-off 的比较级为 better-off）","en":"Better is used to form the comparative of compound adjectives beginning with 'good' and 'well.' For example, the comparative of 'well-off' is 'better-off.'"},{"pos":"PHRASE 短语","cn":"（用于建议）最好，更好","en":"You can say that someone is better doing one thing than another, or it is better doing one thing than another, to advise someone about what they should do.","ex":{"en":"You are better eating just a small snack than hurrying a main meal","cn":"你最好简单吃点快餐，不要着急着慌地吃正餐。"}},{"pos":"PHRASE 短语","cn":"好转；变好","en":"If something changes for the better, it improves.","ex":{"en":"Dreams of changing the world for the better.","cn":"让世界变得更美好的梦想"}},{"pos":"PHRASE 短语","cn":"（嫉妒、好奇心、愤怒等感情）使不能自制","en":"If a feeling such as jealousy, curiosity, or anger gets the better of you, it becomes too strong for you to hide or control.","ex":{"en":"She didn't allow her emotions to get the better of her.","cn":"她没有感情用事。"}},{"pos":"PHRASE 短语","cn":"（在比赛、打斗或争论中）战胜，打败","en":"If you get the better of someone, you defeat them in a contest, fight, or argument.","ex":{"en":"He is used to tough defenders, and he usually gets the better of them.","cn":"他习惯了彪悍的后卫，通常都能战而胜之。"}},{"pos":"PHRASE 短语","cn":"（因阅历丰富）不至于…","en":"If someone knows better than to do something, they are old enough or experienced enough to know it is the wrong thing to do.","ex":{"en":"She knew better than to argue with Adeline","cn":"她不至于和阿德琳发生争执。"}},{"pos":"PHRASE 短语","cn":"比…更了解（或更渊博、更有经验）","en":"If you know better than someone, you have more information, knowledge, or experience than them.","ex":{"en":"He thought he knew better than I did, though he was much less experienced","cn":"虽然他经验远没有我丰富，但他认为他比我懂行。"}},{"pos":"PHRASE 短语","cn":"（用于建议）不如，最好","en":"If you say that someone would be better off doing something, you are advising them to do it or expressing the opinion that it would benefit them to do it.","ex":{"en":"If you've got bags you're better off taking a taxi","cn":"你要是大包小包的，不如打的算了。"}},{"pos":"PHRASE 短语","cn":"胜过；超过","en":"If you go one better, you do something better than it has been done before or obtain something better than someone else has.","ex":{"en":"Now General Electric have gone one better than nature and made a diamond purer than the best quality natural diamonds.","cn":"现在通用电气公司已经制造出了巧夺天工的钻石，其纯度比最好的天然钻石还要高。"}},{"pos":"CONVENTION 惯用语","cn":"（表示赞成、表扬或鼓励）很好，这就对了","en":"You say 'That's better' in order to express your approval of what someone has said or done, or to praise or encourage them.","ex":{"en":"'I came to ask your advice — no, to ask for your help.' — 'That's better. And how can I help you?'","cn":"“我来征求你们的意见——不对，请求你们帮助。”——“这还差不多。我们怎么帮助你？”"}},{"pos":"PHRASE 短语","cn":"这样更好；那更好","en":"You can say 'so much the better' or 'all the better' to indicate that it is desirable that a particular thing is used, done, or available.","ex":{"en":"Use strong white flour, and if you can get hold of durum wheat flour, then so much the better","cn":"使用高筋白面粉，如果你能弄到硬粒小麦面粉，那就更好了。"}},{"pos":"PHRASE 短语","cn":"越…越好","en":"You can use expressions like 'The bigger the better' or 'The sooner the better' to say that you would prefer it if something is big or happens soon.","ex":{"en":"The Irish love a party, the bigger the better","cn":"爱尔兰人喜欢聚会，规模越大越好。"}},{"pos":"PHRASE 短语","cn":"为了更好地…；以便更有效地…","en":"If you do something the better to do something else, you do the first thing in order to be able to do the second thing more effectively.","ex":{"en":"She came on every ride herself, the better to instruct her eager pupils.","cn":"每一个骑乘项目她都要亲自试一试，以便更好地指导她那些跃跃欲试的小学生。"}},{"pos":"PHRASE 短语","cn":"重新考虑后决定不做","en":"If you intend to do something and then think better of it, you decide not to do it because you realize it would not be sensible.","ex":{"en":"Alberg opened his mouth, as if to protest. But he thought better of it.","cn":"阿尔伯格张了张嘴，似乎想要申辩，但想想又放弃了。"}},{"pos":"PHRASE 短语","cn":"不论好坏；不管结果怎样","en":"If you say that something has happened or been done for better or worse, you mean that you are not sure whether the consequences will be good or bad, but they will have to be accepted because the action cannot be changed.","ex":{"en":"I married you for better or worse, knowing all about these problems.","cn":"这些问题我都知道，不管怎样我还是嫁给了你。"}},{"pos":"","cn":"","en":"better the devil you know→see: ; discretion is the better part of valour→see: ; your better half→see: ; against your better judgment→see: ; to be better than nothing→see: ; the better part→see: ;"}]},"examples":[{"en":"Thousands of Victorian workers joined educational associations in an attempt to better themselves.","cn":"维多利亚时代成千上万名工人加入了各种教育协会，以求上进。"},{"en":"We don't actually need it on Tuesday, but if it arrives by then, so much the better.","cn":"实际上我们星期二并不需要它，但如果那时能到就更好。"}],"base":"good"},"becoming":{"media":{"uk":"media/uk/becoming__gb_1.mp3","us":"media/us/becoming__us_1.mp3"},"oxford":{"phon":"bɪˈkʌmɪŋ","pos":"adjective","senses":[{"en":"making the person wearing them look more attractive","cn":"相配的；合身的"},{"en":"suitable or appropriate for somebody or their situation","cn":"合适的；与…相称的","ex":{"en":"It was not very becoming behaviour for a teacher.","cn":"这种举止与一个教师的身份不太相称。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（衣服、颜色、发型等）合适的，相配的，好看的","en":"A piece of clothing, a colour, or a hairstyle that is becoming makes the person who is wearing it look attractive.","ex":{"en":"Softer fabrics are much more becoming than stiffer ones.","cn":"软面料要比硬面料合身得多。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行为）得体的，适宜的","en":"Behaviour that is becoming is appropriate and proper in the circumstances.","ex":{"en":"This behaviour is not any more becoming among our politicians than it is among our voters.","cn":"这种行为对于我们的政治家和选民来说都不合适。"}}]},"examples":[{"en":"It was not very becoming behaviour for a teacher.","cn":"这种举止与一个教师的身分不太相称。"},{"en":"Her short hairstyle is very becoming.","cn":"她的短发很适合她。"}],"base":"become"},"beverage":{"media":{"uk":"media/uk/beverage__gb_1.mp3","us":"media/us/beverage__us_1.mp3"},"oxford":{"phon":"ˈbevərɪdʒ","pos":"noun","senses":[{"en":"any type of drink except water","cn":"（除水以外的）饮料","ex":{"en":"laws governing the sale of alcoholic beverages","cn":"控制酒类销售的法规"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"饮料","en":"Beverages are drinks.","ex":{"en":"Alcoholic beverages are served in the hotel lounge.","cn":"酒店的公共休息室出售酒精饮料。"}}]},"examples":[{"en":"laws governing the sale of alcoholic beverages","cn":"控制酒类销售的法规"},{"en":"alcoholic beverages","cn":"含酒精的饮料"}]},"beacon":{"oxford":{"phon":"ˈbiːkən","pos":"noun","senses":[{"en":"a light that is placed somewhere to guide vehicles and warn them of danger","cn":"（指引车船等的）灯标，灯塔，立标","lab":"figurative","ex":{"en":"a navigation beacon","cn":"航标灯"}},{"en":"a radio station whose signal helps ships and aircraft to find their position","cn":"（导航）无线电信标台","ex":{"en":"The plane was guided in by radio beacon.","cn":"飞机由无线电信标引导。"}},{"en":"(in the past) a fire lit on top of a hill as a signal","cn":"（旧时）烽火"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"灯塔","en":"A beacon is a light or a fire, usually on a hill or tower, which acts as a signal or a warning."},{"pos":"N-COUNT 可数名词","cn":"指路明灯；指引者；楷模","en":"If someone acts as a beacon to other people, they inspire or encourage them.","ex":{"en":"Our Parliament has been a beacon of hope to the peoples of Europe","cn":"我们的国会一直是欧洲各族人民的希望之灯。"}}]},"media":{"uk":"media/uk/beacon__gb_1.mp3","us":"media/us/beacon__us_1.mp3"},"examples":[{"en":"( figurative ) He was a beacon of hope for the younger generation.","cn":"他是年轻一代的希望之灯。"},{"en":"He was a beacon of hope for the younger generation.","cn":""}]},"beam":{"oxford":{"phon":"biːm","pos":"noun","senses":[{"en":"a line of light, electromagnetic waves or particles","cn":"光线；（电磁波的）波束；（粒子的）束","lab":"British English","ex":{"en":"narrow beams of light/sunlight","cn":"一丝丝的光线／阳光"}},{"en":"a long piece of wood, metal, etc. used to support weight, especially as part of the roof in a building","cn":"梁","ex":{"en":"The cottage had exposed oak beams.","cn":"小屋的橡木梁裸露着。"}},{"en":"a wooden bar that is used in the sport of gymnastics for people to move and balance on","cn":"平衡木","lab":"especially British English","ex":{"en":"The gymnast performed a somersault on the beam.","cn":"体操运动员在横梁上翻了一个筋斗。"}},{"en":"a wide and happy smile","cn":"笑容；眉开眼笑","ex":{"en":"a beam of satisfaction","cn":"满意的笑容"}},{"en":"to have a big happy smile on your face","cn":"笑容满面；眉开眼笑","g":"[intransitive, transitive, no passive]","ex":{"en":"He beamed at the journalists.","cn":"他笑容满面地面对记者。"},"pos":"verb"},{"en":"to send radio or television signals over long distances using electronic equipment","cn":"发射（电波）；播送","g":"[transitive]","ex":{"en":"Live pictures of the ceremony were beamed around the world.","cn":"典礼的实况经电视直播传到世界各地。"},"pos":"verb"},{"en":"to produce a stream of light and/or heat","cn":"照射；发光；发热","g":"[intransitive]","ex":{"en":"The morning sun beamed down on us.","cn":"早上的太阳照射着我们。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"眉开眼笑；笑容满面","en":"If you say that someone is beaming, you mean that they have a big smile on their face because they are happy, pleased, or proud about something.","ex":{"en":"Frances beamed at her friend with undisguised admiration","cn":"弗朗西丝开心地对自己的朋友笑着，毫不掩饰她的羡慕之情。"}},{"pos":"N-COUNT 可数名词","cn":"（能量、放射线或粒子的）束，柱","en":"A beam is a line of energy, radiation, or particles sent in a particular direction.","ex":{"en":"...high-energy laser beams.","cn":"高能激光束"}},{"pos":"V-ERG 及物/不及物动词","cn":"（通过电子设备）发送，发射","en":"If something beams radio signals or television pictures or they are beamed somewhere, they are sent there by means of electronic equipment.","ex":{"en":"The interview was beamed live across America","cn":"这次访谈向全美国现场直播。"}},{"pos":"N-COUNT 可数名词","cn":"（光）束；（光）线","en":"A beam of light is a line of light that shines from an object such as a lamp."},{"pos":"VERB 动词","cn":"照耀；照射","en":"If something such as the sun or a lamp beams down, it sends light to a place and shines on it.","ex":{"en":"A sharp white spotlight beamed down on a small stage","cn":"聚光灯的强烈白光照在小舞台上。"}},{"pos":"N-COUNT 可数名词","cn":"梁；横梁","en":"A beam is a long thick bar of wood, metal, or concrete, especially one used to support the roof of a building.","ex":{"en":"The ceilings are supported by oak beams.","cn":"房顶用橡木横梁支撑。"}},{"pos":"N-SING 单数名词","cn":"（体操中的）平衡木","en":"In gymnastics, the beam is a piece of equipment that consists of a narrow wooden bar on which gymnasts balance and perform movements."}]},"media":{"uk":"media/uk/beam__gb_1.mp3","us":"media/us/beam__us_1.mp3"},"examples":[{"en":"Live pictures of the ceremony were beamed around the world.","cn":"典礼的实况经电视直播传到世界各地。"},{"en":"Light beamed through a hole in the curtain.","cn":"光线透过窗帘上的一个孔照射进来。"}]},"behave":{"media":{"uk":"media/uk/behave__gb_1.mp3","us":"media/us/behave__us_1.mp3"},"oxford":{"phon":"bɪˈheɪv","pos":"verb","senses":[{"en":"to do things in a particular way","cn":"表现","g":"[intransitive]","lab":"North American English","ex":{"en":"The doctor behaved very unprofessionally.","cn":"那位医生的做法违反职业道德。"}},{"en":"to do things in a way that people think is correct or polite","cn":"表现得体；有礼貌","g":"[intransitive, transitive]","ex":{"en":"Will you kids just behave!","cn":"孩子们，规矩点！"}},{"en":"behaving in the way mentioned","cn":"表现得…的","ex":{"en":"well-/badly behaved children","cn":"表现好／差的孩子"}},{"en":"to naturally react, move, etc. in a particular way","cn":"作某种自然反应（或变化等）","g":"[intransitive]","lab":"specialist","ex":{"en":"a study of how metals behave under pressure","cn":"对于金属受压反应的研究"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"表现","en":"The way that you behave is the way that you do and say things, and the things that you do and say.","ex":{"en":"I couldn't believe these people were behaving in this way","cn":"我难以相信这些人竟会有这种举动。"}},{"pos":"VERB 动词","cn":"守规矩；举止得体；行为检点","en":"If you behave or behave yourself, you act in the way that people think is correct and proper.","ex":{"en":"You have to behave","cn":"你得规矩点。"}},{"pos":"VERB 动词","cn":"（在科学领域）运动，起作用，作出反应","en":"In science, the way that something behaves is the things that it does.","ex":{"en":"Under certain conditions, electrons can behave like waves rather than particles.","cn":"在一定条件下，电子可以作波状运动，而不是粒子状运动。"}}]},"examples":[{"en":"The doctor behaved very unprofessionally.","cn":"那位医生的做法违反专业道德。"},{"en":"They behave differently when you're not around.","cn":"你不在时他们就是另一副面孔。"}]},"bends":{"lemma":"bend","media":{"uk":"media/uk/bend__gb_1.mp3","us":"media/us/bend__us_1.mp3"}},"belongings":{"media":{"uk":"media/uk/belongings__gb_1.mp3","us":"media/us/belongings__us_1.mp3"},"oxford":{"phon":"bɪˈlɒŋɪŋz","pos":"noun","senses":[{"en":"the things that you own which can be moved, for example not land or buildings","cn":"动产；财物","ex":{"en":"insurance of property and personal belongings","cn":"不动产和个人财物保险"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"所有物；（随身）财物","en":"Your belongings are the things that you own, especially things that are small enough to be carried.","ex":{"en":"I collected my belongings and left","cn":"我收拾好随身物品就离开了。"}}]},"examples":[{"en":"She packed her few belongings in a bag and left.","cn":"她把她的几件东西装进包里便离开了。"},{"en":"insurance of property and personal belongings","cn":"不动产和个人财物保险"}],"base":"belonging"},"bed":{"media":{"uk":"media/uk/bed__gb_1.mp3","us":"media/us/bed__us_1.mp3","img":["media/ldoce/img/ldoce_020.png"]},"oxford":{"phon":"bed","pos":"noun","senses":[{"en":"a piece of furniture for sleeping on","cn":"床","g":"[countable, uncountable]","sc":"furniture","ex":{"en":"a single/double bed","cn":"一张单人／双人床"}},{"en":"the bottom of a river, the sea, etc.","cn":"（河）床；（海等的）底","g":"[countable]","sc":"of river/lake/sea","ex":{"en":"the ocean bed","cn":"海洋底"}},{"en":"an area of ground in a garden or park for growing flowers, vegetables, etc.","cn":"花坛；苗圃；菜园","g":"[countable]","sc":"for flowers/vegetables","ex":{"en":"flower beds","cn":"花坛"}},{"en":"a layer of something that other things lie or rest on","cn":"底层；基；基座","g":"[countable]","sc":"bottom layer","ex":{"en":"grilled chicken, served on a bed of rice","cn":"烤鸡盖饭"}},{"en":"a layer of clay, rock, etc. in the ground","cn":"（地下由黏土、岩石等构成的）地层","g":"[countable]","sc":"geology"},{"en":"to fix something in something so that it cannot move easily","cn":"把…固定在；嵌入；置入","ex":{"en":"The bricks were bedded in sand to improve drainage.","cn":"砖块铺在沙里，以增加透水性。"},"pos":"verb"},{"en":"to have sex with somebody","cn":"与（某人）上床","lab":"old-fashioned","ex":{"en":"He’s been trying to bed her for weeks.","cn":"几个星期以来，他一直想和她上床。"},"pos":"verb"},{"en":"a first university degree in education (the abbreviation for ‘Bachelor of Education’)","cn":"教育学学士（大学教育学的初级学位，全写为 Bachelor of Education）","lab":"British English","ex":{"en":"Sarah Wells BEd","cn":"教育学学士萨拉·韦尔斯"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"床；床铺","en":"A bed is a piece of furniture that you lie on when you sleep.","ex":{"en":"She went into her bedroom and lay down on the bed","cn":"她走进卧室，躺在床上。"}},{"pos":"N-COUNT 可数名词","cn":"（旅馆、医院等的）床位","en":"If a place such as a hospital or a hotel has a particular number of beds, it is able to hold that number of patients or guests."},{"pos":"N-COUNT 可数名词","cn":"畦；苗床；花圃；花坛","en":"A bed in a garden or park is an area of ground that has been specially prepared so that plants can be grown in it.","ex":{"en":"The geraniums in the flower bed looked bedraggled from the heavy rain.","cn":"花坛里的天竺葵被大雨浇得七零八落。"}},{"pos":"N-COUNT 可数名词","cn":"（海洋或湖泊中某种贝类和植物密集分布的）场，层，带","en":"A bed of shellfish or plants is an area in the sea or in a lake where a particular type of shellfish or plant is found in large quantities.","ex":{"en":"Fishermen fear valuable oyster and mussel beds could be decimated","cn":"渔民们害怕宝贵的牡蛎和贻贝层会被破坏。"}},{"pos":"N-COUNT 可数名词","cn":"海床；河床","en":"The sea bed or a river bed is the ground at the bottom of the sea or of a river.","ex":{"en":"For three weeks a big operation went on to recover the wreckage from the sea bed.","cn":"打捞海底残骸这一浩大工程持续了三周。"}},{"pos":"N-COUNT 可数名词","cn":"（岩）层","en":"A bed of rock is a layer of rock that is found within a larger area of rock.","ex":{"en":"Between the white limestone and the greyish pink limestone is a thin bed of clay.","cn":"在白色石灰石和粉灰色石灰石之间是一层薄薄的黏土。"}},{"pos":"N-COUNT 可数名词","cn":"底部食物；底层食物","en":"If a recipe or a menu says that something is served on a bed of a food such as rice or vegetables, it means it is served on a layer of that food.","ex":{"en":"Heat the curry thoroughly and serve it on a bed of rice.","cn":"把咖喱热透后浇在米饭上。"}},{"pos":"PHRASE 短语","cn":"把…搞上床；诱使…发生性关系","en":"To get someone into bed means to persuade them to have sex with you."},{"pos":"PHR-RECIP 相互短语","cn":"和…上床；和…发生性关系","en":"To go to bed with someone means to have sex with them."},{"pos":"PHRASE 短语","cn":"正在和…性交","en":"If you say that someone is in bed with someone else, you mean that they are having sex in bed."},{"pos":"PHRASE 短语","cn":"在做爱方面；就床上功夫而言","en":"If you say that someone is good in bed, you mean that they are a skilful lover."},{"pos":"PHRASE 短语","cn":"自作自受；自食其果","en":"If you say that someone has made their bed and must lie in it, you mean that since they have chosen to do a particular thing, they must now accept the unpleasant results of their action."},{"pos":"PHRASE 短语","cn":"铺床","en":"When you make the bed, you neatly arrange the sheets and covers of a bed so that it is ready to sleep in."},{"pos":"PHRASE 短语","cn":"自打起床心情就不好","en":"If you say that someone got out of bed on the wrong side, you mean that they have been bad-tempered ever since they woke up that morning."},{"pos":"","cn":"","en":"bed of roses→see: ;"},{"pos":"","cn":"","en":"相关词组：bed down"}]},"examples":[{"en":"( BrE ) Sarah Wells BEd","cn":"教育学士萨拉 · 韦尔斯"},{"en":"Simon lay in bed thinking.","cn":"西蒙躺在床上想事情。"}],"base":"be"},"bemused":{"media":{"uk":"media/uk/bemused__gb_1.mp3","us":"media/us/bemused__us_1.mp3"},"oxford":{"phon":"bɪˈmjuːzd","pos":"adjective","senses":[{"en":"showing that you are confused and unable to think clearly","cn":"困惑的；茫然的","ex":{"en":"a bemused expression/smile","cn":"困惑不解的表情／微笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"困惑不解的；茫然的","en":"If you are bemused, you are puzzled or confused.","ex":{"en":"He was rather bemused by children","cn":"他为孩子们大伤脑筋。"}}]},"examples":[{"en":"a bemused expression/smile","cn":"困惑不解的表情/微笑"},{"en":"He looked slightly bemused by all the questions.","cn":"面对所有这些问题﹐他看上去有点儿困惑。"}]},"beside":{"media":{"uk":"media/uk/beside__gb_1.mp3","us":"media/us/beside__us_1.mp3"},"oxford":{"phon":"bɪˈsaɪd","pos":"preposition","senses":[{"en":"next to or at the side of somebody/something","cn":"在旁边；在近旁","ex":{"en":"He sat beside her all night.","cn":"整个晚上他都坐在她的身边。"}},{"en":"compared with somebody/something","cn":"与…相比","ex":{"en":"My painting looks childish beside yours.","cn":"同你的相比，我的画显得很幼稚。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…旁边；在…附近","en":"Something that is beside something else is at the side of it or next to it.","ex":{"en":"On the table beside an empty plate was a pile of books","cn":"桌上空盘子的旁边是一堆书。"}},{"pos":"PHRASE 短语","cn":"非常；极度","en":"If you are beside yourself with anger or excitement, you are extremely angry or excited. beside the point→see: ;","ex":{"en":"He had shouted down the phone at her, beside himself with anxiety","cn":"他焦急万分地对着电话那头的她大喊大叫。"}}]},"examples":[{"en":"I don’t think I’ll come on Saturday. I have a lot of work to do. Besides, I don’t really like parties.","cn":"我想我星期六不会来。我有好多事要做。再说，我不太喜欢社交聚会。"},{"en":"Yes, I know it was an accident, but that's beside the point.","cn":"是的，我知道那是个事故，可是这无关紧要。"}]},"behavioural":{"media":{"uk":"media/uk/behavioral__gb_1.mp3","us":"media/us/behavioral__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"行为的；行为研究的","en":"Behavioural means relating to the behaviour of a person or animal, or to the study of their behaviour.","ex":{"en":"...emotional and behavioural problems.","cn":"情感和行为问题"}}]},"examples":[{"en":"behavioural science (= the study of human behaviour)","cn":"行为科学"},{"en":"children with behavioural difficulties","cn":"有行为问题的儿童"}],"oxford":{"phon":"bɪˈheɪvjərəl","pos":"adjective","senses":[{"en":"connected with behaviour","cn":"（有关）行为的；行为方面的","ex":{"en":"behavioural problems/difficulties","cn":"行为问题/困难"}},{"en":"connected with the scientific study of human and animal behaviour","cn":"行为科学的","ex":{"en":"behavioural science/research","cn":"行为科学/研究"}}]}},"behaviour":{"media":{"uk":"media/uk/behaviour__gb_1.mp3","us":"media/us/behaviour__us_1.mp3"},"oxford":{"phon":"bɪˈheɪvjə(r)","pos":"noun","senses":[{"en":"the way that somebody behaves, especially towards other people","cn":"行为；举止；态度","g":"[uncountable]","ex":{"en":"good/bad behaviour","cn":"良好／恶劣行为"}},{"en":"the way a person, an animal, a plant, a chemical, etc. behaves or functions in a particular situation","cn":"（人、动植物、化学品等的）表现方式，活动方式","g":"[uncountable, countable]","lab":"specialist","ex":{"en":"studying human and animal behaviour","cn":"研究人类和动物的行为模式"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"行为；举止","en":"People's or animals' behaviour is the way that they behave. You can refer to a typical and repeated way of behaving as a behaviour .","ex":{"en":"Make sure that good behaviour is rewarded.","cn":"确保懿行得到嘉奖。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（科学领域中的）运动方式，活动方式，性能，特点","en":"In science, the behaviour of something is the way that it behaves.","ex":{"en":"It will be many years before anyone can predict a hurricane's behavior with much accuracy.","cn":"要能够相当准确地预测出飓风的特性尚需多年。"}},{"pos":"PHRASE 短语","cn":"极力表现；尽量做到举止得体","en":"If someone is on their best behaviour, they are trying very hard to behave well."}]},"examples":[{"en":"His behaviour towards her was becoming more and more aggressive.","cn":"他对待她的态度越来越蛮横。"},{"en":"behavioural science (= the study of human behaviour)","cn":"行为科学"}]},"besides":{"oxford":{"phon":"bɪˈsaɪdz","pos":"preposition","senses":[{"en":"in addition to somebody/something; apart from somebody/something","cn":"除…之外（还）","ex":{"en":"We have lots of things in common besides music.","cn":"除了音乐，我们还有很多共通点。"}},{"en":"used for making an extra comment that adds to what you have just said","cn":"而且；再说","ex":{"en":"I don't really want to go. Besides, it's too late now.","cn":"我并不真的想去，而且现在太晚了。"},"pos":"adverb"},{"en":"in addition; also","cn":"此外；以及；也","ex":{"en":"discounts on televisions, stereos and much more besides","cn":"电视、立体声音响设备以及很多其他货品的折扣"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"此外；另外；除了","en":"Besides something or beside something means in addition to it.","ex":{"en":"I think she has many good qualities besides being very beautiful","cn":"我觉得她不但长得非常漂亮，而且还有很多优秀品质。"}},{"pos":"ADV 副词","cn":"而且，再说（强调所补充的内容）","en":"Besides is used to emphasize an additional point that you are making, especially one that you consider to be important.","ex":{"en":"The house was too expensive and too big. Besides, I'd grown fond of our little rented house.","cn":"这座房子太贵太大了。再说，我已经喜欢上我们租的小房子了。"}}]},"media":{"uk":"media/uk/besides__gb_1.mp3","us":"media/us/besides__us_1.mp3"},"examples":[{"en":"discounts on televisions, stereos and much more besides","cn":"对电视、立体声音响设备以及很多其他货品的折扣"},{"en":"Besides working as a doctor, he also writes novels in his spare time.","cn":"除了当医生之外，他在业余时间还写小说。"}]},"berry":{"media":{"img":["media/pic/berries_fruit_comp.jpg","media/thumb/strawberry.jpg"],"uk":"media/uk/berry__gb_1.mp3","us":"media/us/berry__us_1.mp3"},"oxford":{"phon":"ˈberi","pos":"noun","senses":[{"en":"a small fruit that grows on a bush. There are several types of berry, some of which can be eaten.","cn":"浆果；莓","ex":{"en":"Birds feed on nuts and berries in the winter.","cn":"鸟类靠坚果和浆果过冬。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"浆果；莓","en":"Berries are small, round fruit that grow on a bush or a tree. Some berries are edible, for example blackberries and raspberries."}]},"examples":[{"en":"Birds feed on nuts and berries in the winter.","cn":"鸟类靠坚果和浆果过冬。"},{"en":"blackberries/raspberries","cn":"黑莓；悬钩子"}]},"before":{"media":{"uk":"media/uk/before__gb_1.mp3","us":"media/us/before__us_1.mp3"},"oxford":{"phon":"bɪˈfɔː(r)","pos":"preposition","senses":[{"en":"earlier than somebody/something","cn":"在…以前","ex":{"en":"before lunch","cn":"午餐前"}},{"en":"used to say that somebody/something is ahead of somebody/something in an order or arrangement","cn":"（次序或排列）在前面","ex":{"en":"Your name is before mine on the list.","cn":"名单上你的名字在我之前。"}},{"en":"used to say that somebody/something is in a position in front of somebody/something","cn":"在…面前（或前面）","lab":"rather formal","ex":{"en":"They knelt before the throne.","cn":"他们跪在御座前。"}},{"en":"used to say that something is facing somebody in the future","cn":"（表示面临或临近）","ex":{"en":"The task before us is a daunting one.","cn":"我们所面临的任务令人生畏。"}},{"en":"in the presence of somebody who is listening, watching, etc.","cn":"当面","ex":{"en":"He was brought before the judge.","cn":"他被带上法庭。"}},{"en":"used to say how somebody reacts when they have to face somebody/something","cn":"（表示面对某人、某事时的反应）","lab":"formal","ex":{"en":"They retreated before the enemy.","cn":"面对敌人，他们撤退了。"}},{"en":"earlier than the time when","cn":"在…以前","ex":{"en":"Do it before you forget.","cn":"尽早把事情做好，免得忘了。"},"pos":"conjunction"},{"en":"until","cn":"到…为止；到…之前","ex":{"en":"It may be many years before the situation improves.","cn":"这种状况或许要过很多年才能得到改善。"},"pos":"conjunction"},{"en":"used to warn or threaten somebody that something bad could happen","cn":"以免；不然","ex":{"en":"Put that away before it gets broken.","cn":"把它收好，免得打碎了。"},"pos":"conjunction"},{"en":"rather than","cn":"（宁可…而）不愿","lab":"formal","ex":{"en":"I'd die before I apologized!","cn":"我宁愿死也不道歉！"},"pos":"conjunction"},{"en":"at an earlier time; in the past; already","cn":"以前；过去；已经","ex":{"en":"You should have told me so before.","cn":"你早该告诉我的。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"（时间上）在…之前，早于","en":"If something happens before a particular date, time, or event, it happens earlier than that date, time, or event. →see usage note at:","ex":{"en":"Annie was born a few weeks before Christmas","cn":"安妮出生在圣诞节前几周。"}},{"pos":"PREP 介词","cn":"在（做某事）之前","en":"If you do one thing before doing something else, you do it earlier than the other thing.","ex":{"en":"He spent his early life in Sri Lanka before moving to England","cn":"在移居英格兰之前，他早年是在斯里兰卡度过的。"}},{"pos":"ADV 副词","cn":"在（某时间或某事）以前","en":"You use before when you are talking about time. For example, if something happened the day before a particular date or event, it happened during the previous day.","ex":{"en":"The war had ended only a month or so before.","cn":"战争大约一个月前才刚刚结束。"}},{"pos":"CONJ-SUBORD 连词","cn":"在（他人做某事）之前","en":"If you do something before someone else can do something, you do it when they have not yet done it.","ex":{"en":"Before Gallacher could catch up with the ball, Nadlovu had beaten him to it.","cn":"加拉赫还没来得及追上球，纳德洛武就已经抢先一步触到球了。"}},{"pos":"ADV 副词","cn":"以前；以往；过去","en":"If someone has done something before, they have done it on a previous occasion. If someone has not done something before, they have never done it.","ex":{"en":"I've been here before","cn":"我以前来过这儿。"}},{"pos":"CONJ-SUBORD 连词","cn":"（直到…）才；（过了…）才","en":"If there is a period of time or if several things are done before something happens, it takes that amount of time or effort for this thing to happen.","ex":{"en":"It was some time before the door opened in response to his ring.","cn":"他按完门铃后过了一会儿门才打开。"}},{"pos":"CONJ-SUBORD 连词","cn":"（必须先具备某一条件）才能；在…之前（必须具备某一条件）","en":"If a particular situation has to happen before something else happens, this situation must happen or exist in order for the other thing to happen.","ex":{"en":"There was additional work to be done before all the troops would be ready.","cn":"在全军准备就绪之前，还有一些杂事必须处理。"}},{"pos":"PREP 介词","cn":"（方位）在…前面，在…面前","en":"If someone is before something, they are in front of it.","ex":{"en":"They drove through a tall iron gate and stopped before a large white villa.","cn":"他们开车穿过一个大铁门，在一栋白色的大别墅前面停了下来。"}},{"pos":"PREP 介词","cn":"（所经位置）在…前面","en":"If you tell someone that one place is a certain distance before another, you mean that they will come to the first place first.","ex":{"en":"The turn is about two kilometres before the roundabout.","cn":"拐弯就在环岛前面约2公里处。"}},{"pos":"PREP 介词","cn":"面对…（回答质询）","en":"If you appear or come before an official person or group, you go there and answer questions.","ex":{"en":"The Governor will appear before the committee next Tuesday.","cn":"下周二，州长将接受委员会的质询。"}},{"pos":"PREP 介词","cn":"当着…的面；在…注视之下","en":"If something happens before a particular person or group, it is seen by or happens while this person or this group is present.","ex":{"en":"The game followed a colourful opening ceremony before a crowd of seventy-four thousand.","cn":"绚丽多彩的开幕式过后，这场比赛在74,000名观众的瞩目之下开始了。"}},{"pos":"PREP 介词","cn":"摆在…面前；使面对；使面临","en":"If you have something such as a journey, a task, or a stage of your life before you, you must do it or live through it in the future.","ex":{"en":"Everyone in the room knew it was the single hardest task before them","cn":"房间里所有人都清楚，摆在他们面前的是最为艰巨的任务。"}},{"pos":"PREP 介词","cn":"（重要性）超过；比…重要","en":"When you want to say that one person or thing is more important than another, you can say that they come before the other person or thing.","ex":{"en":"Her husband, her children, and the Church came before her needs.","cn":"丈夫、孩子和教会都比她本人的需求重要。"}},{"pos":"","cn":"","en":"before long→see: ;"}]},"examples":[{"en":"Before you is a list of the points we have to discuss.","cn":"放在你面前的是一份我们所要讨论的要点清单。"},{"en":"The year before last he won a gold medal, and the year before that he won a silver.","cn":"他前年得了一枚金牌，大前年得了一枚银牌。"}]},"beginning":{"media":{"uk":"media/uk/beginning__gb_1.mp3","us":"media/us/beginning__us_1.mp3"},"oxford":{"phon":"bɪˈɡɪnɪŋ","pos":"noun","senses":[{"en":"the time when something starts; the first part of an event, a story, etc.","cn":"开头；开端；开始部分","g":"[countable, usually singular]","ex":{"en":"A story has to have a beginning, middle, and end.","cn":"一个故事必须有开头、中间和结尾。"}},{"en":"the first or early ideas, signs or stages of something","cn":"原始思想；前兆；初级阶段","g":"[plural]","ex":{"en":"Did democracy have its beginnings in ancient Greece?","cn":"民主制度发端于古希腊吗？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"开始；开端；开头；起点","en":"The beginning of an event or process is the first part of it.","ex":{"en":"This was also the beginning of her recording career","cn":"这也是她唱片生涯的开始。"}},{"pos":"N-PLURAL 复数名词","cn":"先兆；开始部分","en":"The beginnings of something are the signs or events which form the first part of it.","ex":{"en":"I had the beginnings of a headache","cn":"我有了头痛的先兆。"}},{"pos":"N-SING 单数名词","cn":"初期；早期","en":"The beginning of a period of time is the time at which it starts.","ex":{"en":"The wedding will be at the beginning of March.","cn":"婚礼定于三月初举行。"}},{"pos":"N-COUNT 可数名词","cn":"开头；开篇","en":"The beginning of a piece of written material is the first words or sentences of it.","ex":{"en":"...the question which was raised at the beginning of this chapter.","cn":"在本章开头所提出的问题"}},{"pos":"N-PLURAL 复数名词","cn":"出身；背景；起源","en":"If you talk about the beginnings of a person, company, or group, you are referring to their backgrounds or origins.","ex":{"en":"His views come from his own humble beginnings.","cn":"他的观点源于他卑微的出身。"}},{"pos":"ADJ 形容词","cn":"刚入门的；初级的","en":"You use beginning to describe someone who is in the early stages of learning to do something.","ex":{"en":"The people that she had in her classroom were beginning learners.","cn":"她带的这班学生都是初学者。"}}]},"examples":[{"en":"He built up his multimillion-pound music business from small beginnings.","cn":"他从小本生意起步，逐步建立起了数百万英镑的音乐企业。"},{"en":"The birth of their first child marked the beginning of a new era in their married life.","cn":"第一个孩子的出世使他们的婚姻生活开始了一个新阶段。"}],"base":"begin"},"bedroom":{"media":{"img":["media/pic/bedroomobjects_labels_comp.jpg","media/thumb/bedroom.jpg"],"uk":"media/uk/bedroom__gb_1.mp3","us":"media/us/bedroom__us_1.mp3"},"oxford":{"phon":"ˈbedruːm","pos":"noun","senses":[{"en":"a room for sleeping in","cn":"卧室","ex":{"en":"the spare/guest bedroom","cn":"备用卧室；客卧"}},{"en":"having the number of bedrooms mentioned","cn":"有…个卧室的","ex":{"en":"a three-bedroomed house","cn":"有三个卧室的房子"}},{"en":"used as a way of referring to sexual activity","cn":"房事的；男女性爱的","ex":{"en":"the bedroom scenes in the movie","cn":"电影中的床上戏"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"卧室；卧房","en":"A bedroom is a room used for sleeping in.","ex":{"en":"...the spare bedroom.","cn":"空置的卧室"}}]},"examples":[{"en":"the bedroom scenes in the movie","cn":"电影中的床上戏"},{"en":"This is the master bedroom (= the main bedroom of the house).","cn":"这是主卧室。"}]},"beach":{"media":{"uk":"media/uk/beach__gb_1.mp3","us":"media/us/beach__us_1.mp3"},"oxford":{"phon":"biːtʃ","pos":"noun","senses":[{"en":"an area of sand or small stones (called shingle), next to the sea or a lake","cn":"海滩；沙滩；海滨；湖滨","lab":"especially British English","ex":{"en":"tourists sunbathing on the beach","cn":"在海滩上沐浴着阳光的游客"}},{"en":"to bring a boat out of the water and onto a beach","cn":"把船拖上岸","g":"[transitive]","ex":{"en":"He beached the boat and lifted the boy onto the shore.","cn":"他把小船拖上岸，把男孩抱到海岸上。"},"pos":"verb"},{"en":"to become stuck on land and unable to get back into the water","cn":"（在海滩上）搁浅","g":"[intransitive, transitive]","ex":{"en":"a beached whale","cn":"在海滩上搁浅的鲸"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海滩；海滨","en":"A beach is an area of sand or stones beside the sea.","ex":{"en":"...a beautiful sandy beach","cn":"美丽的沙滩"}},{"pos":"V-ERG 及物/不及物动词","cn":"把（船）拖上岸；（船等）搁浅","en":"If something such as a boat beaches, or if it is beached, it is pulled or forced out of the water and onto land.","ex":{"en":"We beached the canoe, running it right up the bank","cn":"我们把独木舟径直划到岸边，并拖上岸。"}}]},"examples":[{"en":"He beached the boat and lifted the boy onto the shore.","cn":"他把小船拖上岸，把男孩抱到海岸上。"},{"en":"a beached whale (= one that has become stuck on land and cannot get back into the water)","cn":"搁浅在海滩上的鲸"}]},"beard":{"oxford":{"phon":"bɪəd","pos":"noun","senses":[{"en":"hair that grows on the chin and sides of somebody's face; similar hair that grows on some animals","cn":"（人的）胡须，络腮胡子；（动物的）颔毛，须","lab":"informal","ex":{"en":"He has decided to grow a beard and a moustache.","cn":"他已经决定留起胡子。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胡须；胡子","en":"A man's beard is the hair that grows on his chin and cheeks.","ex":{"en":"He's decided to grow a beard.","cn":"他已经决定蓄胡子。"}}]},"media":{"uk":"media/uk/beard__gb_1.mp3","us":"media/us/beard__us_1.mp3"},"examples":[{"en":"He has decided to grow a beard and a moustache.","cn":"他已经决定留起络腮胡子和髭。"},{"en":"a week's growth of beard","cn":"一星期未刮的胡子"}]},"beer":{"media":{"uk":"media/uk/beer__gb_1.mp3","us":"media/us/beer__us_1.mp3"},"oxford":{"phon":"bɪə(r)","pos":"noun","senses":[{"en":"an alcoholic drink made from malt with hops added to give it taste. There are many types of beer.","cn":"啤酒","g":"[uncountable, countable]","ex":{"en":"a pint/can/bottle of beer","cn":"一品脱／一罐／一瓶啤酒"}},{"en":"a glass, bottle or can of beer","cn":"一杯（或一瓶、一罐）啤酒","g":"[countable]","ex":{"en":"Shall we have a beer?","cn":"我们来杯啤酒吧？"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"啤酒","en":"Beer is a bitter alcoholic drink made from grain.","ex":{"en":"He sat in the kitchen drinking beer","cn":"他坐在厨房里喝啤酒。"}}]},"examples":[{"en":"Are you a beer drinker?","cn":"你经常喝啤酒吗？"},{"en":"Shall we have a beer?","cn":"我们来杯啤酒吧？"}]},"become":{"media":{"uk":"media/uk/become__gb_1.mp3","us":"media/us/become__us_1.mp3"},"oxford":{"phon":"bɪˈkʌm","pos":"verb","senses":[{"en":"to start to be something","cn":"开始变得；变成；成为","ex":{"en":"It soon became apparent that no one was going to come.","cn":"情况很快就明了了，没人会来。"}},{"en":"to be suitable for somebody","cn":"适合（某人）；（与…）相称","g":"[transitive, no passive]","lab":"formal","ex":{"en":"Such behaviour did not become her.","cn":"这种举止与她的身份不相称。"}},{"en":"to look attractive on somebody","cn":"使（人）显得漂亮；使好看","g":"[transitive, no passive]","lab":"formal","ex":{"en":"Short hair really becomes you.","cn":"你理短发很好看。"}}]},"collins":{"senses":[{"pos":"V-LINK 连系动词","cn":"变成；成为；变得","en":"If someone or something becomes a particular thing, they start to change and develop into that thing, or start to develop the characteristics mentioned.","ex":{"en":"I first became interested in Islam while I was doing my nursing training","cn":"我在接受护理培训的时候开始对伊斯兰教产生了兴趣。"}},{"pos":"VERB 动词","cn":"适合；适宜；与…相称","en":"If something becomes someone, it makes them look attractive or it seems right for them.","ex":{"en":"Does khaki become you?","cn":"卡其布适合你吗？"}},{"pos":"PHRASE 短语","cn":"…怎么样了；…会怎么样","en":"If you wonder what has become of someone or something, you wonder where they are and what has happened to them.","ex":{"en":"She thought constantly about her family; she might never know what had become of them","cn":"她一直挂念着家人；她也许再也听不到他们的消息了。"}}]},"examples":[{"en":"What became of that student who used to live with you?","cn":"以前和你住在一起的那个学生后来怎么样了？"},{"en":"I dread to think what will become of them if they lose their home.","cn":"我不敢设想他们如果无家可归将会怎么样。"}]},"beating":{"media":{"uk":"media/uk/beating__gb_1.mp3","us":"media/us/beating__us_1.mp3"},"oxford":{"phon":"ˈbiːtɪŋ","pos":"noun","senses":[{"en":"an act of hitting somebody hard and repeatedly, as a punishment or in a fight","cn":"狠打；揍；笞打","g":"[countable]","ex":{"en":"to give somebody a beating","cn":"把某人揍一顿"}},{"en":"a very heavy defeat","cn":"惨败；严重受挫","g":"[countable]","lab":"informal","ex":{"en":"The team has taken a few beatings this season.","cn":"本赛季该队已经几次严重受挫。"}},{"en":"a series of regular hits to something such as a drum, or movements of something, such as your heart; the sound that this makes","cn":"有规律的敲打（声）；有节奏的运动（声）","g":"[uncountable]","ex":{"en":"He could hear the beating of his own heart.","cn":"他听得到自己的心跳。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指用棍子等进行的）殴打，痛打","en":"If someone is given a beating, they are hit hard many times, especially with something such as a stick.","ex":{"en":"...the savage beating of a black motorist by white police officers","cn":"白人警察对一名黑人驾车者的野蛮殴打。"}},{"pos":"N-SING 单数名词","cn":"（竞争或选举中的）大败，惨败","en":"If something such as a business, a political party, or a team takes a beating, it is defeated by a large amount in a competition or election.","ex":{"en":"Our firm has taken a terrible beating in recent years.","cn":"我们公司近几年败得一塌糊涂。"}},{"pos":"PHRASE 短语","cn":"难以被超越","en":"If you say that something will take some beating, you mean that it is very good and it is unlikely that anything better will be done or made.","ex":{"en":"For sheer scale and grandeur, Leeds Castle in Kent takes some beating.","cn":"单从规模和气势来说，肯特的利兹城堡独领风骚。"}}]},"examples":[{"en":"As a place to live, Oxford takes some beating.","cn":"就居住环境而论，牛津市是个难得的好地方。"},{"en":"The team has taken a few beatings this season.","cn":"本赛季该队已经几次严重受挫。"}],"base":"beat"},"bell":{"media":{"uk":"media/uk/bell__gb_1.mp3","us":"media/us/bell__us_1.mp3","img":["media/ldoce/img/bell.jpg"]},"oxford":{"phon":"bel","pos":"noun","senses":[{"en":"a hollow metal object, often like a cup in shape, that makes a ringing sound when hit by a small piece of metal inside it; the sound that it makes","cn":"铃（声）；钟（声）；钟状物","ex":{"en":"A peal of church bells rang out in the distance.","cn":"远处响起了一阵教堂的钟声。"}},{"en":"an electrical device which makes a ringing sound when a button on it is pushed; the sound that it makes, used as a signal or a warning","cn":"电铃（声）","lab":"figurative","ex":{"en":"Ring the bell to see if they're in.","cn":"按按门铃，看他们在不在家。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"铃","en":"A bell is a device that makes a ringing sound and is used to give a signal or to attract people's attention.","ex":{"en":"I had just enough time to finish eating before the bell rang and I was off to my first class","cn":"我刚吃完饭铃声就响了，于是我赶去上第一堂课。"}},{"pos":"N-COUNT 可数名词","cn":"钟","en":"A bell is a hollow metal object shaped like a cup which has a piece hanging inside it that hits the sides and makes a sound.","ex":{"en":"My brother, Neville, was born on a Sunday, when all the church bells were ringing.","cn":"我弟弟内维尔是星期天出生的，当时所有的教堂钟声齐鸣。"}},{"pos":"PHRASE 短语","cn":"十分清晰；非常清楚","en":"If something is as clear as a bell, it is very clear indeed.","ex":{"en":"There are 80 of these pictures and they're all as clear as a bell.","cn":"这些照片一共有80张，都非常清晰。"}},{"pos":"PHRASE 短语","cn":"给…打电话","en":"If you give someone a bell, you telephone them.","ex":{"en":"I was going to give you a bell tomorrow.","cn":"我明天给你打电话。"}},{"pos":"PHRASE 短语","cn":"听起来耳熟（但记不真切）","en":"If you say that something rings a bell, you mean that it reminds you of something, but you cannot remember exactly what it is.","ex":{"en":"The description of one of the lads is definitely familiar. It rings a bell.","cn":"对其中一个小伙子的描述确实似曾熟悉。听起来挺耳熟。"}},{"pos":"PHRASE 短语","cn":"非常健康的；完好无损的","en":"If something is as sound as a bell it is healthy and not damaged in any way.","ex":{"en":"The horse returned sound as a bell.","cn":"这匹马安然无恙地回来了。"}}]},"examples":[{"en":"His voice came down the line as clear as a bell.","cn":"他的声音如铃声般清脆地从听筒里传出来。"},{"en":"( figurative ) Warning bells started ringing in her head as she sensed that something was wrong.","cn":"当她意识到有差错时，头脑中便敲了警钟。"}]},"bet":{"oxford":{"phon":"bet","pos":"verb","senses":[{"en":"to risk money on a race or an event by trying to predict the result","cn":"下赌注（于）；用…打赌","g":"[intransitive, transitive]","ex":{"en":"You have to be over 16 to bet.","cn":"赌博者年龄不得低于 16 岁。"}},{"en":"used to say that you are almost certain that something is true or that something will happen","cn":"敢说；八成儿","g":"[transitive]","lab":"informal","ex":{"en":"I bet (that) we’re too late.","cn":"我们八成儿太晚了。"}},{"en":"an arrangement to risk money, etc. on the result of a particular event; the money that you risk in this way","cn":"打赌；赌注","ex":{"en":"to win/lose a bet","cn":"赢／输一场赌局"},"pos":"noun"},{"en":"an opinion about what is likely to happen or to have happened","cn":"预计；估计","lab":"informal","ex":{"en":"My bet is that they've been held up in traffic.","cn":"我估计他们是堵车了。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"打赌；下注","en":"If you bet on the result of a horse race, football game, or other event, you give someone a sum of money which they give you back with extra money if the result is what you predicted, or which they keep if it is not.","ex":{"en":"Jockeys are forbidden to bet on the outcome of races","cn":"职业赛马骑师禁止对赛马结果下注。"}},{"pos":"N-COUNT 可数名词","cn":"赌注","en":"A bet is a sum of money which you give to someone when you bet.","ex":{"en":"You can put a bet on almost anything these days.","cn":"如今几乎可以对任何东西下赌注。"}},{"pos":"VERB 动词","cn":"希望；期待","en":"If someone is betting that something will happen, they are hoping or expecting that it will happen.","ex":{"en":"The party is betting that the presidential race will turn into a battle for younger voters","cn":"该党期待这次总统竞选变成一场争取年轻一代选民的斗争。"}},{"pos":"PHRASE 短语","cn":"我敢说；我确信","en":"You use expressions such as 'I bet', 'I'll bet', and 'you can bet' to indicate that you are sure something is true.","ex":{"en":"I bet you were good at games when you were at school","cn":"我敢说你上学时体育很棒。"}},{"pos":"PHRASE 短语","cn":"十拿九稳的事；有望成功的行动；合适之选","en":"If you tell someone that something is a good bet, you are suggesting that it is the thing or course of action that they should choose.","ex":{"en":"Textiles are a good bet for a country bent on industrialisation","cn":"纺织业对于致力于工业化的国家来说是个比较稳妥的产业。"}},{"pos":"PHRASE 短语","cn":"极有可能属实（或发生）的事","en":"If you say that it is a good bet or a safe bet that something is true or will happen, you are saying that it is extremely likely to be true or to happen.","ex":{"en":"It is a safe bet that the current owners will not sell.","cn":"十有八九现在的业主不会出售。"}},{"pos":"PHRASE 短语","cn":"两面下注；做两手准备","en":"If you hedge your bets, you follow two courses of action to avoid making a decision between two things because you cannot decide which one is right.","ex":{"en":"NASA is hedging its bets and adopting both strategies.","cn":"美国航空航天局做了两手准备，两套策略双管齐下。"}},{"pos":"PHRASE 短语","cn":"（通常感到恼火或好笑时表示同意或认为属实）那是，说的是，一点没错","en":"You use I bet or I'll bet in reply to a statement to show that you agree with it or that you expected it to be true, usually when you are annoyed or amused by it.","ex":{"en":"'I'd like to ask you something,' I said. — 'I bet you would,' she grinned.","cn":"“我想问你点事，”我说。——“我就知道你要问，”她笑道。"}},{"pos":"PHRASE 短语","cn":"我敢说；我认为","en":"You can use my bet is or it's my bet to give your personal opinion about something, when you are fairly sure that you are right.","ex":{"en":"My bet is that next year will be different","cn":"我敢说明年不会这样。"}},{"pos":"PHRASE 短语","cn":"不要认为；别指望；不一定","en":"If you say don't bet on something or I wouldn't bet on something, you mean that you do not think that something is true or will happen.","ex":{"en":"'We'll never get a table in there' — 'Don't bet on it.'","cn":"“我们在那儿是订不上座了。”——“那可不一定。”"}},{"pos":"CONVENTION 惯用语","cn":"（表示确信对方说的不对）敢打赌吗？","en":"If you reply 'Do you want to bet?' or 'Want a bet?' to someone, you mean you are certain that what they have said is wrong.","ex":{"en":"'Money can't buy happiness.' — 'Want to bet?'","cn":"“金钱买不到幸福。”——“敢打赌吗？”"}},{"pos":"PHRASE 短语","cn":"当然；一定；一点没错","en":"You use 'You bet' or 'you bet your life' to say yes in an emphatic way or to emphasize a reply or statement.","ex":{"en":"'It's settled, then?' — 'You bet.'","cn":"“那么，就这么定了？”——“定了。”"}}]},"media":{"uk":"media/uk/bet__gb_1.mp3","us":"media/us/bet__us_1.mp3"},"examples":[{"en":"We expect shares to rise unless the economy slows down again, in which case all bets are off.","cn":"我们预计股票会涨，除非经济再次下滑。如果真是那样的话，结局就难料了。"},{"en":"‘I nearly died when he told me.’ ‘I bet!’ “","cn":"他告诉我时，我差一点死掉了。” “肯定是这样！”"}]},"betting":{"media":{"uk":"media/uk/betting__gb_1.mp3","us":"media/us/betting__us_1.mp3"},"oxford":{"phon":"ˈbetɪŋ","pos":"noun","senses":[{"en":"the act of risking money, etc. on the unknown result of an event","cn":"打赌；赌钱","ex":{"en":"illegal betting","cn":"非法赌博"}}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"很有可能；十有八九","en":"If you say the betting is that something will happen or is true, you are suggesting that it is very likely to happen or to be true.","ex":{"en":"The betting is that the experience will make Japan more competitive still.","cn":"这场经历很有可能使日本更具竞争力。"}}]},"examples":[{"en":"What's the betting that he gets his own way?","cn":"你认为他可能会独行其是吗？"},{"en":"The betting is that he'll get his own way.","cn":"他很可能会独行其是。"}],"base":"bet"},"benevolence":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is kind tries to help people and make them happy or comfortable, and shows that they care about them","cn":""},{"en":"friendly and kind. Nice is very common in everyday spoken English and is often used instead of kind","cn":""}]},"examples":[{"en":"A benevolent uncle paid for her to have music lessons.","cn":"","src":"ld"}],"media":{"uk":"media/uk/benevolence__gb_1.mp3","us":"media/us/benevolence__us_1.mp3"},"oxford":{"phon":"bəˈnevələns","pos":"noun","senses":[{"en":"the quality of being kind, helpful and generous","cn":"善良、乐于助人和慷慨的品质","ex":{"en":"an act of benevolence","cn":"一种仁慈的行为"}}]}},"benefited":{"lemma":"benefit","media":{"uk":"media/uk/benefit__gb_1.mp3","us":"media/us/benefit__us_1.mp3"}},"beauty":{"media":{"uk":"media/uk/beauty__gb_1.mp3","us":"media/us/beauty__us_1.mp3"},"oxford":{"phon":"ˈbjuːti","pos":"noun","senses":[{"en":"the quality of giving pleasure to the senses or to the mind","cn":"美；美丽","g":"[uncountable]","ex":{"en":"the beauty of the sunset/of poetry/of his singing","cn":"落日／诗作／他的歌声之美"}},{"en":"a person or thing that is beautiful","cn":"美人；美好的东西","g":"[countable]","ex":{"en":"She had been a beauty in her day.","cn":"她年轻时是个美人。"}},{"en":"an excellent example of its type","cn":"极好的榜样；典型的例子","g":"[countable]","ex":{"en":"That last goal was a beauty!","cn":"最后进的一球真绝！"}},{"en":"an attractive feature","cn":"优点；好处","g":"[countable]","ex":{"en":"One of the beauties of living here is that it's so peaceful.","cn":"在这里生活的好处之一是安宁。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"美丽；漂亮","en":"Beauty is the state or quality of being beautiful.","ex":{"en":"...an area of outstanding natural beauty","cn":"自然美景美不胜收的景区"}},{"pos":"N-COUNT 可数名词","cn":"美女；美人","en":"A beauty is a beautiful woman.","ex":{"en":"She is known as a great beauty.","cn":"她是出了名的大美女。"}},{"pos":"N-COUNT 可数名词","cn":"极好的事物","en":"You can say that something is a beauty when you think it is very good.","ex":{"en":"The pass was a real beauty, but the shot was poor.","cn":"传得非常漂亮，但是临门一脚太臭了。"}},{"pos":"N-COUNT 可数名词","cn":"魅力；美好；吸引人之处","en":"The beauties of something are its attractive qualities or features.","ex":{"en":"He was beginning to enjoy the beauties of nature.","cn":"他开始享受大自然之美。"}},{"pos":"ADJ 形容词","cn":"美容的","en":"Beauty is used to describe people, products, and activities that are concerned with making women look beautiful.","ex":{"en":"Additional beauty treatments can be booked in advance.","cn":"额外的美容服务可以提前预订。"}},{"pos":"N-COUNT 可数名词","cn":"好处；妙处；优点","en":"If you say that a particular feature is the beauty of something, you mean that this feature is what makes the thing so good.","ex":{"en":"There would be no effect on animals—that's the beauty of such water-based materials.","cn":"对动物毫无影响——水基材料妙就妙在这儿。"}}]},"examples":[{"en":"The project will require very little work to start up; that's the beauty of it.","cn":"这项工程几乎不需要启动工作，好就好在这里。"},{"en":"The woods were designated an area of outstanding natural beauty.","cn":"这片森林被划定为超级自然美景区。"}]},"bereft":{"media":{"uk":"media/uk/bereft__gb_1.mp3","us":"media/us/bereft__us_1.mp3"},"oxford":{"phon":"bɪˈreft","pos":"adjective","senses":[{"en":"completely without something; having lost something","cn":"完全没有，丧失，失去（某物）","ex":{"en":"bereft of ideas/hope","cn":"无计可施；失去希望"}},{"en":"sad and lonely because you have lost something","cn":"感到失落","ex":{"en":"He was utterly bereft when his wife died.","cn":"他的妻子去世时，他十分凄凉。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"失去…的；丧失…的","en":"If a person or thing is bereft of something, they no longer have it.","ex":{"en":"The place seemed to be utterly bereft of human life.","cn":"这个地方似乎根本没有人烟。"}}]},"examples":[{"en":"He was utterly bereft when his wife died.","cn":"他的妻子去世时，他十分凄凉。"},{"en":"bereft of ideas/hope","cn":"无计可施；失去希望"}]},"belonging":{"oxford":{"phon":"bɪˈlɒŋɪŋ","pos":"noun","senses":[{"en":"the feeling of being comfortable and happy in a particular situation or with a particular group of people, and being treated as a full member of the group","cn":"归属感","ex":{"en":"to feel a sense of belonging","cn":"有归属感"}}]},"media":{"uk":"media/uk/belonging__gb_1.mp3","us":"media/us/belonging__us_1.mp3"},"examples":[{"en":"to feel a sense of belonging","cn":"有一种归属感"},{"en":"Put the chair back where it belongs.","cn":""}],"base":"belong"},"belong":{"media":{"uk":"media/uk/belong__gb_1.mp3","us":"media/us/belong__us_1.mp3"},"oxford":{"phon":"bɪˈlɒŋ","pos":"verb","senses":[{"en":"to be in the right or suitable place","cn":"应在（某处）","g":"[intransitive]","ex":{"en":"Where do these plates belong (= where are they kept)?","cn":"这些盘子该放在哪里？"}},{"en":"to feel comfortable and happy in a particular situation or with a particular group of people","cn":"适应；合得来","g":"[intransitive]","ex":{"en":"I don't feel as if I belong here.","cn":"我在这里感觉格格不入。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"属于；归…所有","en":"If something belongs to you, you own it.","ex":{"en":"The house had belonged to her family for three or four generations.","cn":"这套房子归她们家有三四代人了。"}},{"pos":"VERB 动词","cn":"与…有关；是…的一部分","en":"You say that something belongs to a particular person when you are guessing, discovering, or explaining that it was produced by or is part of that person.","ex":{"en":"The handwriting belongs to a male","cn":"这是男性的笔迹。"}},{"pos":"VERB 动词","cn":"是…的成员；属于（某团体）","en":"If someone belongs to a particular group, they are a member of that group.","ex":{"en":"I used to belong to a youth club.","cn":"我过去是一个青年俱乐部的成员。"}},{"pos":"VERB 动词","cn":"属于（某个类别、类型或群体）","en":"If something or someone belongs in or to a particular category, type, or group, they are of that category, type, or group.","ex":{"en":"The judges could not decide which category it belonged in","cn":"评委们无法判定它属于哪一类。"}},{"pos":"VERB 动词","cn":"源于，来自于（某个时代）","en":"If something belongs to a particular time, it comes from that time.","ex":{"en":"The pictures belong to an era when there was a preoccupation with high society.","cn":"这些画出自一个人人向往上流社会的时代。"}},{"pos":"VERB 动词","cn":"（权利）属于（某人）","en":"If you say that something belongs to someone, you mean that person has the right to it.","ex":{"en":"...but the last word belonged to Rosanne.","cn":"但是最终决定权在罗莎娜手里"}},{"pos":"VERB 动词","cn":"以…为特点；以…为特征","en":"If you say that a time belongs to a particular system or way of doing something, you mean that that time is or will be characterized by it.","ex":{"en":"The future belongs to democracy.","cn":"未来属于民主。"}},{"pos":"VERB 动词","cn":"（孩子）是…的，为…所拥有（或监护）","en":"If a baby or child belongs to a particular adult, that adult is his or her parent or the person who is looking after him or her.","ex":{"en":"He deduced that the two children belonged to the couple.","cn":"他推断这俩小孩是这对夫妇的。"}},{"pos":"V-RECIP 相互动词","cn":"属于彼此（恋人用来表示亲密关系）","en":"When lovers say that they belong together, they are expressing their closeness or commitment to each other.","ex":{"en":"I really think that we belong together","cn":"我真的觉得我们属于彼此。"}},{"pos":"VERB 动词","cn":"归属于（某地或某一情形）","en":"If a person or thing belongs in a particular place or situation, that is where they should be.","ex":{"en":"You don't belong here","cn":"你不属于这里。"}}]},"examples":[{"en":"British actors did well at the award ceremony, but the evening belonged to the Americans.","cn":"英国演员在颁奖仪式上表现很好，但整个晚上却是美国人大出风头。"},{"en":"Are you sure these documents belong together?","cn":"你肯定这些文件应放在一起吗？"}]},"began":{"lemma":"begin","media":{"uk":"media/uk/began__gb_1.mp3","us":"media/us/began__us_1.mp3"}},"bees":{"lemma":"bee"},"becomes":{"lemma":"become"},"berries":{"lemma":"berry"},"behaves":{"lemma":"behave"},"behavior":{"lemma":"behaviour"},"beverages":{"lemma":"beverage"},"bears":{"lemma":"bear"},"benches":{"lemma":"bench"},"beggars":{"oxford":{"phon":"ˈbeɡə(r)","pos":"noun","senses":[{"en":"a person who lives by asking people for money or food","cn":"乞丐；叫花子"},{"en":"( BrE ) ( informal ) used with an adjective to describe sb in a particular way （","cn":"与形容词连用）家伙"}]}},"betrays":{"lemma":"betray"},"beds":{"lemma":"bed","media":{"img":["media/pic/beds_comp.jpg"]}},"beneficiaries":{"oxford":{"phon":"ˌbenɪˈfɪʃəri","pos":"noun","senses":[{"en":"a person who gains as a result of sth","cn":"受益者；受惠人"},{"en":"a person who receives money or property when sb dies","cn":"遗产继承人"}]}},"beings":{"oxford":{"phon":"ˈbiːɪŋ","pos":"noun","senses":[{"en":"existence","cn":"存在；生存"},{"en":"a living creature","cn":"生物"}]}},"believes":{"lemma":"believe"},"begins":{"lemma":"begin"},"besetting":{"oxford":{"phon":"bɪˈset","pos":"verb","senses":[{"en":"( formal ) to affect sb/sth in an unpleasant or harmful way","cn":"困扰；威胁"}]}},"believed":{"lemma":"believe"},"belongs":{"lemma":"belong"},"belonged":{"lemma":"belong"},"beasts":{"lemma":"beast"},"beats":{"lemma":"beat"},"beliefs":{"lemma":"belief"},"bending":{"lemma":"bend"},"bemoaned":{"oxford":{"phon":"bɪˈməʊn","pos":"verb","senses":[{"en":"( formal ) to complain or say that you are not happy about sth","cn":"哀怨；悲叹"}]}},"behaved":{"lemma":"behave"},"benefits":{"lemma":"benefit"},"beaten":{"lemma":"beat","media":{"uk":"media/ldoce/hwd/bre/c/brelasdebeaten.mp3","us":"media/ldoce/hwd/ame/8/beaten.mp3"}},"beaches":{"lemma":"beach"},"bedrooms":{"lemma":"bedroom"},"bewitched":{"oxford":{"phon":"bɪˈwɪtʃ","pos":"verb","senses":[{"en":"to attract or impress sb so much that they cannot think in a sensible way","cn":"迷住；迷惑"},{"en":"to put a magic spell on sb","cn":"施魔法于；使中魔法"}]}},"believing":{"lemma":"believe"},"beg":{"collins":{"senses":[{"pos":"VERB 动词","cn":"请求；恳求；恳请","en":"If you beg someone to do something, you ask them very anxiously or eagerly to do it.","ex":{"en":"I begged him to come back to England with me","cn":"我恳求他和我一起回英格兰。"}},{"pos":"VERB 动词","cn":"乞讨；乞求施舍","en":"If someone who is poor is begging, they are asking people to give them food or money.","ex":{"en":"I was surrounded by people begging for food","cn":"我被一群讨饭的围住了。"}},{"pos":"PHRASE 短语","cn":"恕难苟同；斗胆唱反调","en":"You say 'I beg to differ' when you are politely emphasizing that you disagree with someone."},{"pos":"PHRASE 短语","cn":"没人要；没人用","en":"If you say that something is going begging, you mean that it is available but no one is using it or accepting it.","ex":{"en":"There is other housing going begging in town.","cn":"城里还有些住宅无人问津。"}},{"pos":"PHRASE 短语","cn":"引起疑问，使人想问（一些人认为此用法不正确）","en":"If you say that something begs a particular question, you mean that it makes people want to ask that question; some people consider that this use is incorrect.","ex":{"en":"Hopewell's success begs the question: why aren't more companies doing the same?","cn":"霍普韦尔的成功让人不禁要问：为什么其他公司不效仿呢？"}},{"pos":"PHRASE 短语","cn":"（认为问题已获解决而）绕过问题","en":"If you say that something begs a particular question, you mean that it assumes that the question has already been answered and so does not deal with it.","ex":{"en":"The research begs a number of questions.","cn":"研究绕过了一些问题。"}},{"pos":"","cn":"","en":"I beg your pardon→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tell someone you want them to give you something","cn":""},{"en":"to ask for food or drink in a restaurant","cn":""},{"en":"to ask for something in a firm way, insisting that someone gives you what you ask for","cn":""}]},"collocations":{"phrases":["VERB + BEG be forced to, have to","PREP. for begging for food | from He had to beg food from passers-by. 2 ask for sth with great emotion","ADV. almost, practically In the end they almost begged him to take the job. | humbly We humbly beg Your Majesty to show mercy. | silently Do","VERB + BEG be forced to, have to","PREP. for We went to him to beg for forgiveness. | of (formal) Do not do that, I beg of you."]},"media":{"uk":"media/ldoce/hwd/bre/0/beg0205.mp3","us":"media/ldoce/hwd/ame/5/beg.mp3"},"examples":[{"en":"‘It's on Duke Street.’ ‘I beg your pardon.’ ‘Duke Street.’ “","cn":"在公爵大街上。” “请再说一遍。” “公爵大街。”"},{"en":"All of which begs the question as to who will fund the project.","cn":"所有这一切都令人想到究竟由谁来投资该工程的问题。"}],"oxford":{"phon":"beɡ","pos":"verb","senses":[{"en":"to ask somebody for something especially in an anxious way because you want or need it very much","cn":"恳求；祈求；哀求","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"Now you have to beg and plead.","cn":"现在你不得不乞求别人。"}},{"en":"to ask somebody for money, food, etc., especially in the street","cn":"乞讨；行乞","g":"[intransitive, transitive]","ex":{"en":"A young woman was begging in the street.","cn":"一名年轻女子在街上乞讨。"}},{"en":"if a dog begs, it sits on its back legs with its front legs in the air, waiting to be given something","cn":"（狗蹲坐在后腿上将前腿抬起）等食物","g":"[intransitive]"}]}},"beloved":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"深爱的；钟爱的","en":"A beloved person, thing, or place is one that you feel great affection for.","ex":{"en":"He lost his beloved wife last year","cn":"他去年痛失爱妻。"}},{"pos":"N-SING 单数名词","cn":"爱人；心爱的人","en":"Your beloved is the person that you love.","ex":{"en":"He takes his beloved into his arms.","cn":"他将心爱之人拥入怀中。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"loved very much by someone","cn":"钟爱的﹐挚爱的﹔宝贝的"},{"en":"someone who is loved very much","cn":"我/她等的挚爱"}]},"vocab":{"pos":"adj n","senses":[{"en":"Your beloved is someone you love. You can also talk about a beloved pet or possession."}]},"collocations":{"phrases":["VERBS be","ADV. dearly, much the death of his much beloved wife","PREP. by an area beloved by artists | of She ran one of the little tea rooms so beloved of Londoners at the turn of the century."]},"media":{"uk":"media/ldoce/hwd/bre/d/beloved0205.mp3","us":"media/ldoce/hwd/ame/c/beloved.mp3"},"examples":[{"en":"It was a gift from her beloved.","cn":"那是她心爱的人送的礼物。"},{"en":"the deep purple flowers so beloved by artists","cn":"受艺术家青睐的深紫色花"}],"oxford":{"phon":"","pos":"adjective","senses":[{"en":"loved very much","cn":"深爱的；亲爱的","g":"[only before noun]","ex":{"en":"in memory of our dearly beloved son, John","cn":"为纪念我们的爱子约翰"}},{"en":"loved very much by somebody; very popular with somebody","cn":"钟爱的；深受喜爱的","ex":{"en":"the deep purple flowers so beloved by artists","cn":"受艺术家青睐的深紫色花"}},{"en":"a person who is loved very much by somebody","cn":"心爱的人","ex":{"en":"It was a gift from her beloved.","cn":"那是她心爱的人送的礼物。"},"pos":"noun"}]}},"bedside":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"床旁；床边；床侧","en":"Your bedside is the area beside your bed.","ex":{"en":"She put a cup of tea down on the bedside table","cn":"她在床头柜上放了一杯茶。"}},{"pos":"N-SING 单数名词","cn":"（某人的）病床边","en":"If you talk about being at someone's bedside, you are talking about being near them when they are ill in bed.","ex":{"en":"She kept vigil at the bedside of her critically ill son","cn":"她整夜都守在病重的儿子床边。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the area beside your bed – used especially when talking about someone who is ill in bed","cn":"床侧﹐床边〔尤用于谈论卧病在床的人〕"}]},"collocations":{"phrases":["VERB + BEDSIDE be called to, be summoned to The doctor was summoned to his bedside. | stay at/by | leave His wife never left his bedside.","BEDSIDE + NOUN cabinet, lamp, light, table","PREP. at sb's/the ~, by sb's/the ~ I like to keep a glass of water by my bedside."]},"media":{"img":["media/ldoce/img/bedside_table.jpg"],"uk":"media/ldoce/hwd/bre/0/bedside0205.mp3","us":"media/ldoce/hwd/ame/b/bedside.mp3"},"examples":[{"en":"His mother has been at his bedside throughout his illness.","cn":"在他生病期间，他母亲一直守候在他床边。"},{"en":"a bedside lamp","cn":"床头灯"}],"oxford":{"phon":"ˈbedsaɪd","pos":"noun","senses":[{"en":"the area next to a bed","cn":"床边","ex":{"en":"His mother has been at his bedside throughout his illness.","cn":"在他生病期间，他母亲一直守候在他床边。"}}]}},"believer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"相信…的人","en":"If you are a great believer in something, you think that it is good, right, or useful.","ex":{"en":"Mum was a great believer in herbal medicines.","cn":"妈妈特别相信草药。"}},{"pos":"N-COUNT 可数名词","cn":"（宗教）信徒，信仰者","en":"A believer is someone who is sure that God exists or that their religion is true.","ex":{"en":"I made no secret of the fact that I was not a believer.","cn":"我毫不掩饰我不信教。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you are all for something or all in favour of something , you strongly approve of it -- used especially when you do not approve of something else that is often connected with it","cn":""},{"en":"to approve of a particular way of living or of doing things because you think it brings good results","cn":""},{"en":"to believe strongly that something is good and effective","cn":"坚信某事﹐深信某事"}]},"collocations":{"phrases":["ADJ. devout, genuine, true | religious 2 sb who believes that sth is good","ADJ. fervent, firm, great, passionate, staunch, strong","PREP. ~ in I'm a firm believer in the benefits of exercise."]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdebeliever.mp3","us":"media/ldoce/hwd/ame/5/believer.mp3"},"examples":[{"en":"I’m a great believer in regular exercise.","cn":"我深信经常锻炼有好处。"}],"oxford":{"phon":"bɪˈliːvə(r)","pos":"noun","senses":[{"en":"a person who believes in the existence or truth of something, especially somebody who believes in a god or religious faith","cn":"信徒"}]}},"berth":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"对…敬而远之；避开","en":"If you give someone or something a wide berth, you avoid them because you think they are unpleasant, or dangerous, or simply because you do not like them.","ex":{"en":"More experienced hands in the Mission had given Miss Pickerstaff a wide berth that morning","cn":"那天早上，代表团里的老手对皮克斯塔芙小姐都敬而远之。"}},{"pos":"N-COUNT 可数名词","cn":"（船、火车、旅行拖车等的）卧铺，铺位","en":"A berth is a bed on a boat, train, or caravan.","ex":{"en":"Goldring booked a berth on the first boat he could.","cn":"戈德林订了他能订到的最早一班船的铺位。"}},{"pos":"N-COUNT 可数名词","cn":"泊位","en":"A berth is a space in a harbour where a ship stays for a period of time."},{"pos":"VERB 动词","cn":"（船舶）停泊，停靠","en":"When a ship berths, it sails into harbour and stops at the quay.","ex":{"en":"As the ship berthed in New York, McClintock was with the first immigration officers aboard.","cn":"船停靠在纽约后，麦克林托克和第一批移民局官员登上了船。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where a ship can stop and be tied up 〔","cn":"船的〕泊位﹐停泊处"},{"en":"a place for someone to sleep on a ship or on a train 〔","cn":"船的〕舱位；〔火车上的〕卧铺﹐铺位"},{"en":"to bring a ship into a berth, or arrive at a berth 〔","cn":"船〕停泊﹔使停泊"}]},"vocab":{"pos":"1 n v 2 n v 3 n","senses":[{"en":"A berth is a bed, usually stacked like bunk beds, on a train or a ship. If you're on an overnight train, you may want to spring for a berth instead of sitting up all night."}]},"collocations":{"phrases":["ADJ. empty | upper | lower","VERB + BERTH have | book, get, take I've managed to get berths on the overnight ferry.","PHRASES a two-berth, three berth, etc. cabin"]},"media":{"uk":"media/ldoce/hwd/bre/1/berth_v0205.mp3","us":"media/ldoce/hwd/ame/a/berth1.mp3"},"examples":[{"en":"The ship is berthed at Southampton.","cn":"船停泊在南安普敦。"}],"oxford":{"phon":"bɜːθ","pos":"noun","senses":[{"en":"a place to sleep on a ship or train, or in a caravan","cn":"（船、火车或旅行拖车等的）卧铺，舱位，铺位","ex":{"en":"a cabin with three berths","cn":"一个有三个泊位的小屋"}},{"en":"a place where a ship or boat can stop and stay, usually in a harbour","cn":"（船的）泊位，锚地","ex":{"en":"a berth in dock","cn":"码头泊位"}},{"en":"to put a ship in a berth or keep it there; to sail into a berth","cn":"（使船）停泊","ex":{"en":"The ship is berthed at Southampton.","cn":"船停泊在南安普敦。"},"pos":"verb"}]}},"beast":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兽；野兽","en":"You can refer to an animal as a beast, especially if it is a large, dangerous, or unusual one.","ex":{"en":"...the threats our ancestors faced from wild beasts.","cn":"我们祖先面对的来自野兽的威胁"}},{"pos":"N-COUNT 可数名词","cn":"兽性的人；畜生；禽兽","en":"If you refer to a man as a beast, you mean that his behaviour, especially his sexual behaviour, is very violent and uncontrolled.","ex":{"en":"...a sex beast who subjected two sisters to a terrifying ordeal.","cn":"使两姐妹遭受恐怖摧残的色魔"}},{"pos":"N-COUNT; N-VOC 可数名词；称呼名词","cn":"讨厌鬼；王八蛋","en":"If you call someone a beast, you think that they are behaving in a selfish, unkind, or unpleasant way.","ex":{"en":"Bully! Hooligan! Beast! Let me go, let go!","cn":"混蛋！流氓！王八蛋！放开我，放开！"}},{"pos":"N-COUNT 可数名词","cn":"（含诙谐意）有特定性质的事物，性格特别的人","en":"You can use beast to refer to something or someone in a light-hearted way, and to mention that they have a particular quality.","ex":{"en":"...that rare beast, a sports movie that isn't boring.","cn":"这场体育电影还挺有意思，真难得"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a living thing such as a dog, cow, or tiger, but not an insect, fish, or bird","cn":""},{"en":"an animal – used especially when describing a particular animal’s characteristics or when referring to animals generally","cn":""},{"en":"an animal, especially a large or dangerous one 〔","cn":"尤指大型或危险的〕野兽"}]},"vocab":{"pos":"n","senses":[{"en":"A beast is an animal — and usually not a gentle or attractive one. You can also call a person a beast when they're behaving in a crude, savage, or horrible way."}]},"collocations":{"phrases":["ADJ. ferocious, savage, snarling, wild Savage beasts once roamed these forests. | exotic, fabled, fantastic, legendary, mythical, rare, stra","PHRASES a beast of burden, a beast of prey 2 unpleasant/cruel person","ADJ. filthy You filthy beast! | sex Local people live in fear of this unknown sex beast.","PHRASES the beast in sb (= the violent or sexual part of sb's character) The beast in her wanted to destroy his house. | bring out the beast"]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdebeast.mp3","us":"media/ldoce/hwd/ame/7/beast.mp3"},"examples":[{"en":"mythical beasts such as unicorns and dragons","cn":"独角兽和龙之类的神异动物"},{"en":"The maths exam was a real beast.","cn":"数学考试实在令人憎恶。"}],"oxford":{"phon":"biːst","pos":"noun","senses":[{"en":"an animal, especially one that is large or dangerous, or one that is unusual","cn":"（尤指大型或凶猛、独特的）动物，兽","lab":"old-fashioned or formal","ex":{"en":"wild/savage/ferocious beasts","cn":"野兽；猛兽"}},{"en":"a person who is cruel and whose behaviour shows a lack of control","cn":"性情凶残的人；行为粗暴的人","ex":{"en":"The beast in her wanted to destroy his house.","cn":"她的兽性使她想毁掉他的房子。"}},{"en":"an unpleasant person or thing","cn":"讨厌的人（或事物）","lab":"informal, often humorous，，","ex":{"en":"The maths exam was a real beast.","cn":"数学考试实在令人讨厌。"}},{"en":"a thing of a particular kind","cn":"（某种）东西","lab":"informal","ex":{"en":"His new guitar is a very expensive beast.","cn":"他的新吉他贵得吓人。"}}]}},"believable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可信的","en":"Something that is believable makes you think that it could be true or real.","ex":{"en":"...believable evidence","cn":"可信的证据"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a story, explanation etc is believable , you can believe it because it seems possible or likely","cn":""},{"en":"a convincing explanation, argument, reason etc seems likely to be true","cn":""},{"en":"something that is plausible seems reasonable and likely to be true, even though it may actually be untrue - use this especially about an explanation, excuse, or idea","cn":""}]},"collocations":{"phrases":["VERBS be, sound | find sth","ADV. very All the characters were very believable. | hardly I find her story hardly believable."]},"media":{"uk":"media/ldoce/hwd/bre/6/believable0205.mp3","us":"media/ldoce/hwd/ame/b/believable.mp3"},"examples":[{"en":"Her explanation certainly sounded believable.","cn":"她的解释听起来的确可信。"},{"en":"a play with believable characters","cn":"剧中人物真实可信的戏剧"}],"oxford":{"phon":"bɪˈliːvəbl","pos":"adjective","senses":[{"en":"that can be believed","cn":"可相信的；可信任的","ex":{"en":"Her explanation certainly sounded believable.","cn":"她的解释听起来的确可信。"}}]}},"bereaved":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（人）新近失去亲友的","en":"A bereaved person is one who has a relative or close friend who has recently died.","ex":{"en":"Mr Dinkins visited the bereaved family to offer comfort.","cn":"丁金斯先生前往死者家吊唁。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you lose a close relative or friend, they die","cn":""},{"en":"if you are widowed , your husband or wife dies","cn":""},{"en":"if you are orphaned , both your parents die when you are still young","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Bereaved is an adjective describing people in deep sorrow at the loss of a loved one. For some, being bereaved helps them leave the sadness or release themselves from it by experiencing it for awhile."}]},"collocations":{"phrases":["VERBS be","ADJ. newly, recently a recently bereaved family"]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdebereaved.mp3","us":"media/ldoce/hwd/ame/c/bereaved.mp3"},"examples":[{"en":"an organization offering counselling for the bereaved","cn":"为死者亲友提供辅导的组织"},{"en":"recently bereaved families","cn":"刚刚痛失亲人的家庭"}],"oxford":{"phon":"bɪˈriːvd","pos":"adjective","senses":[{"en":"having lost a relative or close friend who has recently died","cn":"丧失亲友的","ex":{"en":"recently bereaved families","cn":"刚刚痛失亲人的家庭"}},{"en":"a person who is bereaved","cn":"死者的亲友","ex":{"en":"an organization offering counselling for the bereaved","cn":"为死者亲友提供辅导的组织"}}]}},"belly":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胃，腹部（在英国英语中属于非正式或文学用语）","en":"The belly of a person or animal is their stomach or abdomen. In British English, this is an informal or literary use.","ex":{"en":"She laid her hands on her swollen belly","cn":"她把双手放在自己隆起的肚子上。"}},{"pos":"PHRASE 短语","cn":"资不抵债；无力偿还债务","en":"If a company goes belly up, it does not have enough money to pay its debts.","ex":{"en":"I really can't afford to see this company go belly up.","cn":"我绝对不能眼睁睁地看着这家公司垮掉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"your stomach","cn":"胃"},{"en":"the front part of your body between your chest and your legs","cn":"肚子﹐腹部"},{"en":"the middle part of an animal’s body, near its stomach 〔","cn":"动物的〕腹部﹐肚子"}]},"collocations":{"phrases":["ADJ. empty, full | flat | fat, pot Since he turned 30 he's started to develop a pot belly. | distended, swollen | beer (= a fat stomach from","BELLY + VERB bulge | hang He's so fat, his belly hangs over his trousers. | swell","PREP. in your ~ She felt the child in her belly kick."]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdebelly.mp3","us":"media/ldoce/hwd/ame/7/belly1.mp3"},"examples":[{"en":"Last year the business went belly up after one of the partners resigned.","cn":"去年一位合伙人退出后，这家企业就垮掉了。"},{"en":"They crawled along on their bellies.","cn":"他们匍匐前进。"}],"oxford":{"phon":"ˈbeli","pos":"noun","senses":[{"en":"the part of the body below the chest","cn":"腹部；肚子","ex":{"en":"They crawled along on their bellies.","cn":"他们匍匐前进。"}},{"en":"the round or curved part of an object","cn":"（物体的）圆形或凸起部分","lab":"literary","ex":{"en":"the belly of a ship","cn":"船腹"}},{"en":"having the type of belly mentioned","cn":"腹部…形的","ex":{"en":"swollen-bellied","cn":"腹部肿胀的"}},{"en":"to fill with air and become rounder","cn":"胀满；鼓起","ex":{"en":"The sails bellied out in the wind.","cn":"船帆迎风鼓起。"},"pos":"verb"}]}},"beginner":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"初学者；新手；生手","en":"A beginner is someone who has just started learning to do something and cannot do it very well yet.","ex":{"en":"The course is suitable for beginners and advanced students","cn":"这门课程适合初学者和高级程度的学生。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is studying at a school, college, or university","cn":""},{"en":"someone who is learning a skill while working in a company or organization","cn":""},{"en":"someone who has recently started to learn something","cn":""}]},"collocations":{"phrases":["ADJ. absolute, complete, real"]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdebeginner.mp3","us":"media/ldoce/hwd/ame/9/beginner.mp3"},"examples":[{"en":"She's in the beginners' class.","cn":"她在初级班。"},{"en":"an absolute beginner","cn":"不折不扣的初学者"}],"oxford":{"phon":"bɪˈɡɪnə(r)","pos":"noun","senses":[{"en":"a person who is starting to learn something and cannot do it very well yet","cn":"新手；初学者","ex":{"en":"She's in the beginners' class.","cn":"她在初级班。"}}]}},"bengal":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"an area of southern Asia that includes Bangladesh and the Indian state of West Bengal","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/p028-000002216.mp3","us":"media/ldoce/hwd/ame/c/p028-000002216.mp3"}},"bewildered":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"困惑不解的；不知所措的；晕头转向的","en":"If you are bewildered, you are very confused and cannot understand something or decide what you should do.","ex":{"en":"Some shoppers looked bewildered by the sheer variety of goods on offer.","cn":"光是摆在那里的各式商品就让一些购物者晕头转向了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unable to understand what someone is saying or what is happening","cn":""},{"en":"confused because you cannot understand something, especially because it is different from what you expect","cn":""},{"en":"very confused and unable to understand something, even though you have tried hard for a long time","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If a conversation about quantum mechanics leaves you feeling bewildered, or lost and befuddled, don't feel bad: physics is a baffling and confusing subject."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound | become | leave sb She packed her bags and left?leaving Matthew bewildered and confused.","ADV. very | completely, quite, thoroughly, totally, utterly | a little, rather, slightly, somewhat","PREP. at He was rather bewildered at seeing her there. | by She was totally bewildered by his message."]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdebewildered.mp3","us":"media/ldoce/hwd/ame/5/laadbewildered.mp3"},"examples":[{"en":"He turned around, with a bewildered look on his face.","cn":"他转过身来，满脸困惑。"},{"en":"a bewildered expression on his face","cn":"他脸上困惑的表情"}],"oxford":{"phon":"bɪˈwɪldəd","pos":"adjective","senses":[{"en":"confused","cn":"糊涂的；困惑的；混乱的","ex":{"en":"He turned around, with a bewildered look on his face.","cn":"他转过身，一脸茫然。"}}]}},"benign":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"和蔼的；温和的；慈祥的","en":"You use benign to describe someone who is kind, gentle, and harmless.","ex":{"en":"They are normally a more benign audience","cn":"他们通常观看时比较温和。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有危害的","en":"A benign substance or process does not have any harmful effects.","ex":{"en":"We're taking relatively benign medicines and we're turning them into poisons.","cn":"我们服的药相对来说药性温和，但是我们却在把它们变成毒药。"}},{"pos":"ADJ 形容词","cn":"（肿瘤）良性的","en":"A benign tumour will not cause death or serious harm.","ex":{"en":"It wasn't cancer, only a benign tumour.","cn":"这不是癌症，只是良性肿瘤。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（条件、环境）良好的，宜人的","en":"Benign conditions are pleasant or make it easy for something to happen.","ex":{"en":"They enjoyed an especially benign climate","cn":"他们那里的气候非常宜人。"}},{"pos":"PHRASE 短语","cn":"不作为；善意忽视；顺其自然","en":"If you describe someone's approach to a problem as one of benign neglect, you disapprove of the fact that they are doing nothing and hoping that the problem will solve itself.","ex":{"en":"America and Japan have settled back into a policy of benign neglect of their currencies.","cn":"美国和日本又回到了不作为货币政策的老路。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"kind and gentle","cn":"慈祥的﹔宽厚亲切的"},{"en":"a benign tumour (= unnatural growth in the body ) is not caused by cancer 〔","cn":"肿瘤〕良性的"}]},"vocab":{"pos":"adj","senses":[{"en":"Someone or something that is benign is gentle, kind, mild, or unharmful: a benign soul wouldn't hurt a fly."}]},"collocations":{"phrases":["VERBS be, look, seem","ADV. fairly, rather, relatively The effects of this chemical are fairly benign. | environmentally We are looking for an environmentally beni"]},"media":{"uk":"media/ldoce/hwd/bre/c/benign0205.mp3","us":"media/ldoce/hwd/ame/8/benign.mp3"},"examples":[{"en":"He smiled benignly.","cn":"他露出了和蔼的笑容。"},{"en":"He shook his head in benign amusement.","cn":"他被逗乐了，和蔼地摇了摇头。"}],"oxford":{"phon":"bɪˈnaɪn","pos":"adjective","senses":[{"en":"kind and gentle; not hurting anybody","cn":"善良的；和善的；慈祥的","lab":"formal","ex":{"en":"You would never have guessed his intentions from the benign expression on his face.","cn":"你永远不会从他脸上和善的表情中猜到他的意图。"}},{"en":"not causing damage or harm","cn":"无害的","ex":{"en":"The industry's environmental impact is relatively benign, even positive.","cn":"该行业对环境的影响相对良性，甚至是积极的。"}},{"en":"not dangerous or likely to cause death","cn":"良性的","lab":"medical","ex":{"en":"She is recovering after surgery to remove a benign tumour.","cn":"她做了良性肿瘤切除手术，正在康复。"}}]}},"bearable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可忍受的；可容忍的；忍耐得住的","en":"If something is bearable, you feel that you can accept it or deal with it.","ex":{"en":"A cool breeze made the heat pleasantly bearable.","cn":"一阵凉风吹来，让炎热的天气变得稍微舒适了一些。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a situation or type of behaviour that is bearable is difficult or unpleasant, but you are just able to bear it","cn":""},{"en":"a situation that is tolerable is bad but you are able to accept it and deal with it","cn":""},{"en":"something that is bearable is difficult or unpleasant, but you can deal with it","cn":"可忍受的﹐可容忍的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that you can live through, disagreeable as it may be, is bearable . The world's most boring math class, while tedious, is bearable ."}]},"collocations":{"phrases":["VERBS be | become | make sth The camaraderie among fellow employees made the tedious work just bearable. | find sth He found the dullness of","ADV. almost | hardly, scarcely | just","PREP. for The money made life more bearable for her."]},"media":{"uk":"media/ldoce/hwd/bre/1/bearable0205.mp3","us":"media/ldoce/hwd/ame/d/bearable.mp3"},"examples":[{"en":"She was the only thing that made life bearable.","cn":"只因有了她生活才可以过得下去。"},{"en":"His friendship was the one thing that made life bearable.","cn":"有他的友情在，生活还可以过下去。"}],"oxford":{"phon":"ˈbeərəbl","pos":"adjective","senses":[{"en":"a person or thing that is bearable can be accepted or dealt with","cn":"可忍受的；能应付的","ex":{"en":"She was the only thing that made life bearable.","cn":"只因有了她，生活才可以过得下去。"}}]}},"benefactor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"捐助者；赞助人；施主","en":"A benefactor is a person who helps a person or organization by giving them money.","ex":{"en":"In his old age he became a benefactor of the arts.","cn":"他晚年成了一个艺术赞助人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to give money to an organization that will use it to help people who are poor, sick, in trouble etc","cn":""},{"en":"to give money, or something useful or valuable, in order to help people - use this especially about things that are given by companies or organizations","cn":""},{"en":"to give an amount of money to an organization that will use it to help people","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Every school, museum, and struggling artist is in search for a generous benefactor , or someone to provide the financial means to keep everything running smoothly."}]},"collocations":{"phrases":["ADJ. generous, kind | wealthy | great | anonymous, mysterious, unknown | private | public He was a great public benefactor and gave land for","BENEFACTOR + VERB donate sth, give sth A private benefactor donated &pound; 20,000.","PREP. ~ to She was a generous benefactor to the library."]},"media":{"uk":"media/ldoce/hwd/bre/6/benefactor0205.mp3","us":"media/ldoce/hwd/ame/0/benefactor.mp3"},"examples":[{"en":"An anonymous benefactor donated $2 million.","cn":"一位没留姓名的捐助人捐款二百万美元。"},{"en":"a generous benefactor of the university","cn":"该大学一名慷慨的捐助人"}],"oxford":{"phon":"ˈbenɪfæktə(r)","pos":"noun","senses":[{"en":"a person who gives money or other help to a person or an organization such as a school or charity","cn":"施主；捐款人；赞助人","ex":{"en":"a generous benefactor","cn":"慷慨的捐助者"}}]}},"beijing":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the capital city of the People's Republic of China. In English, it was formerly called Peking, and this name is still sometimes used.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/p028-000002173.mp3","us":"media/ldoce/hwd/ame/f/p028-000002173.mp3"}},"bequest":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"遗产","en":"A bequest is money or property which you legally leave to someone when you die.","ex":{"en":"The church here was left a bequest to hire doctors who would work amongst the poor.","cn":"这个教堂接收到一笔遗产，可以用来聘请医生为穷人治病。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"money or property that you arrange to give to someone after your death","cn":"遗产﹔遗赠物"}]},"vocab":{"pos":"n","senses":[{"en":"When you receive some kind of gift, be it money or property, through a will, that gift is known as a bequest . Your aunt left you a bequest of the earrings she always thought you admired."}]},"collocations":{"phrases":["ADJ. generous, large, substantial The library has received a generous bequest from a local businessman. | small | charitable","VERB + BEQUEST leave (sb), make (sb) In his will he made a substantial bequest to his wife. | receive","PREP. by ~ The picture was acquired by bequest in 1921. | ~ from a bequest from the late Jack Dawkins | ~ to"]},"media":{"uk":"media/ldoce/hwd/bre/6/bequest0205.mp3","us":"media/ldoce/hwd/ame/2/bequest.mp3"},"examples":[{"en":"He left a bequest to each of his grandchildren.","cn":"他给他的孙子孙女每人留下一笔遗产。"},{"en":"a bequest of $5,000","cn":"一笔五千美元的遗产"}],"oxford":{"phon":"bɪˈkwest","pos":"noun","senses":[{"en":"money or property that you ask to be given to a particular person when you die","cn":"遗产；遗赠","ex":{"en":"He left a bequest to each of his grandchildren.","cn":"他给他的孙子孙女每人留下一笔遗产。"}}]}},"bereavement":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"丧亲之痛；新丧","en":"Bereavement is the sorrow you feel or the state you are in when a relative or close friend dies.","ex":{"en":"When Mary died Anne did not share her brother's sense of bereavement.","cn":"玛丽去世后，安妮并没有像她弟弟那样哀痛。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone loses a close friend or relative because they have died","cn":"丧亲（之痛）﹔丧友（之痛）﹔居丧"}]},"vocab":{"pos":"n","senses":[{"en":"If you have ever mourned someone's passing, you know about bereavement — the period of sorrow that follows the death of a loved one."}]},"collocations":{"phrases":["ADJ. recent | family, personal","VERB + BEREAVEMENT suffer He has suffered a bereavement. | come to terms with, cope with, get over","BEREAVEMENT + NOUN counselling, counsellor","PHRASES the pain/shock of bereavement"]},"media":{"uk":"media/ldoce/hwd/bre/0/bereavement0205.mp3","us":"media/ldoce/hwd/ame/e/bereavement.mp3"},"examples":[{"en":"the pain of an emotional crisis such as divorce or bereavement","cn":"诸如离婚或痛失亲人等的情感危机的痛苦"},{"en":"A family bereavement meant that he could not attend the conference.","cn":"他家里有人去世了，所以不能出席会议。"}],"oxford":{"phon":"bɪˈriːvmənt","pos":"noun","senses":[{"en":"the state of having lost a relative or close friend because they have died","cn":"丧失亲人；丧亲之痛","g":"[uncountable]","ex":{"en":"the pain of an emotional crisis such as divorce or bereavement","cn":"诸如离婚或痛失亲人等的情感危机的痛苦"}},{"en":"the death of a relative or close friend","cn":"亲友的丧亡","g":"[countable]","ex":{"en":"A family bereavement meant that he could not attend the conference.","cn":"他家里有人去世了，所以不能出席会议。"}}]}},"bear":{"collins":{"senses":[{"pos":"VERB 动词","cn":"抬；背负；负载；驮","en":"If you bear something somewhere, you carry it there or take it there.","ex":{"en":"They bore the oblong hardwood box into the kitchen and put it on the table.","cn":"他们把那个长方形的硬木箱抬进厨房，放到桌上。"}},{"pos":"VERB 动词","cn":"持有；携带","en":"If you bear something such as a weapon, you hold it or carry it with you.","ex":{"en":"...the constitutional right to bear arms.","cn":"宪法规定的携带武器的权利"}},{"pos":"VERB 动词","cn":"承载；支撑","en":"If one thing bears the weight of something else, it supports the weight of that thing.","ex":{"en":"The ice was not thick enough to bear the weight of marching men.","cn":"冰不够厚，承载不了行军队伍的重量。"}},{"pos":"VERB 动词","cn":"带有（某种标记或特征）","en":"If something bears a particular mark or characteristic, it has that mark or characteristic.","ex":{"en":"The houses bear the marks of bullet holes.","cn":"房子上散布着弹孔。"}},{"pos":"VERB 动词","cn":"忍受，容忍，忍耐（不愉快经历）","en":"If you bear an unpleasant experience, you accept it because you are unable to do anything about it.","ex":{"en":"They will have to bear the misery of living in constant fear of war","cn":"他们不得不忍受长期生活在战争恐惧中的痛苦。"}},{"pos":"VERB 动词","cn":"接受，容忍（某人或某物）","en":"If you can't bear someone or something, you dislike them very much.","ex":{"en":"I can't bear people who make judgements and label me","cn":"我讨厌人们对我品头论足。"}},{"pos":"VERB 动词","cn":"负担（开支）；承担（费用）","en":"If someone bears the cost of something, they pay for it.","ex":{"en":"Patients should not have to bear the costs of their own treatment.","cn":"病人不应该自己承担治疗费用。"}},{"pos":"VERB 动词","cn":"承担（责任）；负（责）","en":"If you bear the responsibility for something, you accept responsibility for it.","ex":{"en":"If a woman makes a decision to have a child alone, she should bear that responsibility alone.","cn":"如果一个女人决定独自抚养孩子，她就必须独自承担所有责任。"}},{"pos":"VERB 动词","cn":"带有，具有（相似之处）；有（关系等）","en":"If one thing bears no resemblance or no relationship to another thing, they are not at all similar.","ex":{"en":"Their daily menus bore no resemblance whatsoever to what they were actually fed","cn":"他们每天的食谱和他们实际吃到的东西完全不同。"}},{"pos":"VERB 动词","cn":"开（花）；结（果）","en":"When a plant or tree bears flowers, fruit, or leaves, it produces them.","ex":{"en":"As the plants grow and start to bear fruit they will need a lot of water.","cn":"当植物生长并开始结果的时候，它们需要大量的水。"}},{"pos":"VERB 动词","cn":"带有，产生（利息等）","en":"If something such as a bank account or an investment bears interest, interest is paid on it.","ex":{"en":"The eight-year bond will bear annual interest of 10.5%.","cn":"这种8年期的债券年利率为10.5%。"}},{"pos":"VERB 动词","cn":"生（孩子）；生育","en":"When a woman bears a child, she gives birth to him or her.","ex":{"en":"Emma bore a son called Karl","cn":"埃玛生了个儿子叫卡尔。"}},{"pos":"VERB 动词","cn":"怀有（某种感情）","en":"If you bear someone a feeling such as love or hate, you feel that emotion towards them.","ex":{"en":"She bore no ill will. If people didn't like her, too bad","cn":"她没有恶意。如果人们不喜欢她，那就太糟糕了。"}},{"pos":"VERB 动词","cn":"举止；表现","en":"If you bear yourself in a particular way, you move or behave in that way.","ex":{"en":"There was elegance and simple dignity in the way he bore himself.","cn":"他举止优雅而庄重。"}},{"pos":"VERB 动词","cn":"向（左或右）转","en":"If you bear left or bear right when you are driving or walking along, you turn and continue in that direction.","ex":{"en":"Go left onto the A107 and bear left into Seven Sisters Road.","cn":"向左驶入A107号公路,然后左转进七姐妹路。"}},{"pos":"PHRASE 短语","cn":"用…处理；用…应对","en":"If you bring something to bear on a situation, you use it to deal with that situation.","ex":{"en":"British scientists have brought computer science to bear on this problem.","cn":"英国的科学家们已经应用计算机科学来解决这个问题。"}},{"pos":"PHRASE 短语","cn":"对…施加（影响、压力等）","en":"If you bring pressure or influence to bear on someone, you use it to try and persuade them to do something.","ex":{"en":"His companions brought pressure to bear on him, urging him to stop wasting money.","cn":"他的伙伴们给他施加压力，劝他不要再浪费钱。"}},{"pos":"","cn":"","en":"to bear the brunt of→see: ; to bear comparison→see: ; to bear fruit→see: ; to grin and bear it→see: ; to bear in mind→see: ; to bear witness to→see: ;"},{"pos":"","cn":"","en":"相关词组：bear down bear out bear up bear with"},{"pos":"N-COUNT 可数名词","cn":"熊","en":"A bear is a large, strong wild animal with thick fur and sharp claws."},{"pos":"N-COUNT 可数名词","cn":"（对股市行情）看跌的人","en":"On the stock market, bears are people who sell shares in expectation of a drop in price, in order to make a profit by buying them back again after a short time."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have something or someone in your hands or arms when you go somewhere","cn":""},{"en":"to carry something such as a bag or a gun","cn":""},{"en":"to carry something heavy, with difficulty","cn":""}]},"vocab":{"pos":"1 v 2 v 3 v 4 v 5 v ","senses":[{"en":"To bear is to carry or endure, whether by physical or mental force. If you can bear to read on, you'll find out all the different ways to use the word bear ."}]},"collocations":{"phrases":["VERB + BEAR be able/unable to, can/could (hardly/scarcely) Don't leave me alone. I wouldn't be able to bear it. How can you bear this awful ","VERB + BEAR have to, must Do parents have to bear the whole cost of tuition fees? You must bear at least some responsibility for what has ha","ADV. heavily The burden of the tax bore most heavily on the poor."]},"media":{"img":["media/ldoce/img/black_bear.jpg"],"uk":"media/ldoce/hwd/bre/c/brelasdebear.mp3","us":"media/ldoce/hwd/ame/4/bare1.mp3"},"examples":[{"en":"The joke doesn't bear repeating (= because it is not funny or may offend people).","cn":"这个笑话不可说第二遍（因为不好笑或可能得罪人）。"},{"en":"If you will bear with me (= be patient and listen to me) a little longer, I'll answer your question.","cn":"你如果能耐心点听我把话说完，我会回答你的问题的。"}],"oxford":{"phon":"beə(r)","pos":"verb","senses":[{"en":"to be able to accept and deal with something unpleasant","cn":"承受；忍受","g":"[transitive]","sc":"accept/deal with","ex":{"en":"The pain was almost more than he could bear.","cn":"这种痛苦几乎使他无法忍受。"}},{"en":"to take responsibility for something","cn":"承担责任","g":"[transitive]","lab":"formal","sc":"be responsible for something","ex":{"en":"She bore the responsibility for most of the changes.","cn":"她对大多数变革负责。"}},{"en":"to support the weight of somebody/something","cn":"支撑，承受（重量）","g":"[transitive]","sc":"support weight","ex":{"en":"The ice is too thin to bear your weight.","cn":"冰太薄，承受不住你的重量。"}},{"en":"to show something; to carry something so that it can be seen","cn":"显示；带有","g":"[transitive]","lab":"formal","sc":"show","ex":{"en":"The document bore her signature.","cn":"文件上有她的签字。"}},{"en":"to not be suitable for something","cn":"不适于某事（或做某事）","g":"[transitive]","sc":"not be suitable","ex":{"en":"Her later work does not bear comparison with her earlier novels (= because it is not nearly as good).","cn":"她后期的作品比不上她早期的小说。"}},{"en":"to have a feeling, especially a negative feeling","cn":"心怀（感情，尤指坏心情）","g":"[transitive]","sc":"negative feeling","ex":{"en":"He bears no resentment towards them.","cn":"他对他们毫无怨恨。"}},{"en":"to have a particular name","cn":"有（某个名称）","g":"[transitive]","lab":"formal","sc":"name","ex":{"en":"a family that bore an ancient and honoured name","cn":"名门世家"}},{"en":"to carry somebody/something, especially while moving","cn":"携带","g":"[transitive]","lab":"old-fashioned or formal","sc":"carry","ex":{"en":"three kings bearing gifts","cn":"三个带着礼品的国王"}},{"en":"to move, behave or act in a particular way","cn":"举止；表现","g":"[transitive]","lab":"formal","sc":"yourself","ex":{"en":"He bears himself (= stands, walks, etc.) proudly, like a soldier.","cn":"他昂首阔步，像个军人。"}},{"en":"to give birth to a child","cn":"生（孩子）","g":"[transitive]","lab":"formal","sc":"child","ex":{"en":"She was not able to bear children.","cn":"她不能生育。"}},{"en":"to produce flowers or fruit","cn":"开（花）；结（果实）","g":"[transitive]","lab":"formal","sc":"of trees/plants","ex":{"en":"These trees take a long time to bear fruit.","cn":"这些树要很长时间才结果实。"}},{"en":"to go or turn in the direction mentioned","cn":"转向（左或北等）","g":"[intransitive]","sc":"turn","ex":{"en":"When you get to the fork in the road, bear right.","cn":"走到岔道时向右拐。"}},{"en":"a heavy wild animal with thick fur and sharp claws (= pointed parts on the ends of its feet). There are many types of bear.","cn":"熊","ex":{"en":"a black bear","cn":"黑熊"},"pos":"noun"},{"en":"a person who sells shares in a company, etc., hoping to buy them back later at a lower price","cn":"（在证券市场等）卖空的人","lab":"finance","pos":"noun"}]}},"bead":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"珠子；小珠","en":"Beads are small pieces of coloured glass, wood, or plastic with a hole through the middle. Beads are often put together on a piece of string or wire to make jewellery.","ex":{"en":"...a string of beads.","cn":"一串珠子"}},{"pos":"N-COUNT 可数名词","cn":"（液体的）小珠，小滴","en":"A bead of liquid or moisture is a small drop of it.","ex":{"en":"...beads of blood","cn":"血滴"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of a set of small, usually round, pieces of glass, wood, plastic etc, that you can put on a string and wear as jewellery","cn":"珠子﹐小珠"},{"en":"a small drop of liquid such as water or blood 〔","cn":"液体的〕小珠子﹐小滴〔如水珠﹑血滴等〕"},{"en":"to aim carefully before shooting a weapon 〔","cn":"射击前〕瞄准某人/某物"}]},"collocations":{"phrases":["ADJ. amber, glass, wooden, etc. | prayer, rosary","QUANT. strand, string a string of wooden beads","VERB + BEAD wear | fasten, put on | take off, undo, unfasten | thread She threaded the beads carefully.","BEAD + VERB hang A strand of coral beads hung round her neck.","BEAD + NOUN curtain 2 small drop of liquid","PHRASES a bead of moisture/perspiration/sweat"]},"media":{"uk":"media/ldoce/hwd/bre/a/bead0205.mp3","us":"media/ldoce/hwd/ame/6/bead.mp3"},"examples":[{"en":"A bead curtain separated the two rooms.","cn":"一挂珠帘子把两个房间分开。"},{"en":"There were beads of sweat on his forehead.","cn":"他的额头上挂满汗珠。"}],"oxford":{"phon":"biːd","pos":"noun","senses":[{"en":"a small piece of glass, wood, etc., with a hole through it, that can be put on a string with others of the same type and worn as jewellery, etc.","cn":"（有孔的）珠子","g":"[countable]","ex":{"en":"a necklace of wooden beads","cn":"一条木珠项链"}},{"en":"a rosary","cn":"（天主教徒念经时用的）数珠，念珠","g":"[plural]","ex":{"en":"In one of the pews a woman was fingering her beads.","cn":"其中一个长凳上，一位女士正在拨弄珠子。"}},{"en":"a small drop of liquid","cn":"（液体的）小滴","g":"[countable]","ex":{"en":"There were beads of sweat on his forehead.","cn":"他的额头上挂满汗珠。"}}]}},"bellow":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（人）吼叫，咆哮","en":"If someone bellows, they shout angrily in a loud, deep voice.","ex":{"en":"'I didn't ask to be born!' she bellowed","cn":"“我没有要求你们把我生下来！”她吼道。"}},{"pos":"VERB 动词","cn":"（公牛、大象等大型动物）咆哮，吼叫","en":"When a large animal such as a bull or an elephant bellows, it makes a loud and deep noise.","ex":{"en":"A heifer bellowed in her stall.","cn":"小母牛在牛栏里吼叫。"}},{"pos":"N-COUNT 可数名词","cn":"风箱；鼓风机","en":"A bellows is or bellows are a device used for blowing air into a fire in order to make it burn more fiercely.","ex":{"en":"...two stone forges, each equipped with bellows.","cn":"两个都配有风箱的石头熔炉"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very loudly","cn":""},{"en":"to shout very loudly, especially because you are angry, excited, or in pain. Yell is more informal than shout","cn":""},{"en":"to shout in order to get someone’s attention","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To bellow is to shout in a deep, angry voice. If you constantly bellow at other drivers on the road, consider signing up for anger management classes."}]},"collocations":{"phrases":["ADJ. great, loud | angry","VERB + BELLOW give, let out She gave a great bellow of laughter. | hear","PREP. with a ~ He woke with a bellow of rage. | ~ of","PHRASES a bellow of laughter, a bellow of rage • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/4/bellow_n0205.mp3","us":"media/ldoce/hwd/ame/7/bellow.mp3"},"examples":[{"en":"The coach bellowed instructions from the sidelines.","cn":"教练在场边大声发号施令。"},{"en":"They bellowed at her to stop.","cn":"他们吼叫着让她停下。"}],"oxford":{"phon":"ˈbeləʊ","pos":"verb","senses":[{"en":"to shout in a loud deep voice, especially because you are angry","cn":"大声吼叫；怒吼","g":"[intransitive, transitive]","ex":{"en":"They bellowed at her to stop.","cn":"他们吼叫着让她停下。"}},{"en":"when a large animal such as a bull bellows, it makes a loud deep sound","cn":"（公牛等）吼叫","g":"[intransitive]"},{"en":"a shout in a loud deep voice, especially when you are angry","cn":"大声吼叫；怒吼","ex":{"en":"to let out a bellow of rage/pain","cn":"愤怒地／痛苦地吼叫"},"pos":"noun"},{"en":"a loud deep sound made by a large animal such as a bull","cn":"（公牛等）吼叫","pos":"noun"}]}},"beaker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常无柄的）塑料杯","en":"A beaker is a plastic cup used for drinking, usually one with no handle."},{"pos":"N-COUNT 可数名词","cn":"大口杯；大玻璃杯","en":"A beaker is a large cup or glass."},{"pos":"N-COUNT 可数名词","cn":"烧杯","en":"A beaker is a glass or plastic jar which is used in chemistry."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drinking cup with straight sides and no handle, usually made of plastic","cn":"广口杯〔直身无柄﹐一般用塑料做成〕"},{"en":"a glass cup with straight sides that is used in chemistry for measuring and heating liquids","cn":"烧杯﹐量杯"}]},"collocations":{"phrases":["ADJ. glass, plastic a glass beaker containing copper sulphate solution She drank from a plastic beaker.","VERB + BEAKER fill, refill | drain, empty | lift, pick up, raise | place, put down, replace, set down | drink from/out of","BEAKER + VERB contain sth"]},"media":{"uk":"media/ldoce/hwd/bre/8/beaker0205.mp3","us":"media/ldoce/hwd/ame/4/beaker.mp3","img":["media/thumb/beaker.jpg"]},"examples":[{"en":"a beaker of coffee","cn":"一杯咖啡"}],"oxford":{"phon":"ˈbiːkə(r)","pos":"noun","senses":[{"en":"a cup, usually made of plastic and often without a handle, used for drinking from","cn":"（常指无柄的）塑料杯","lab":"British English","ex":{"en":"She drank from a plastic beaker.","cn":"她用一只大塑料杯喝水。"}},{"en":"the amount contained in a beaker","cn":"一杯（的量）","lab":"British English","ex":{"en":"a beaker of coffee","cn":"一杯咖啡"}},{"en":"a glass cup with straight sides and a lip, used in chemistry, for example for measuring liquids","cn":"烧杯","ex":{"en":"a glass beaker containing copper sulphate solution","cn":"盛有硫酸铜溶液的玻璃烧杯"}}]}}});
